export default [{"id":257,"question":"ما حكم مَن أوتر بعد صلاة العشاء بركعةٍ واحدةٍ؟ ففي الحديث الذي ورد في البخاري: أنَّ معاوية  أوتر بعد العشاء بركعةٍ واحدةٍ، فقيل لابن عباس ذلك، فقال: \"دعوه فإنه فقيه\"؟","title":"حكم الوتر بعد صلاة العشاء بركعة واحدة","answer":"الجواب: صحيح، نعم، الوتر بواحدةٍ كافٍ، ومن هذا حديث أبي أيوب الأنصاري، وهو ثابتٌ عن النبي ﷺ قال: مَن أحبَّ أن يُوتر بخمسٍ فليفعل، ومَن أحبَّ أن يُوتر بثلاثٍ فليفعل، ومَن أحبَّ أن يُوتر بواحدةٍ فليفعل، فالوتر أقلّه ركعة واحدة من آخر الليل، أو من وسط الليل، أو من أول الليل، كافٍ، بعد العشاء، وكلما زاد فهو أفضل، إن أوتر بثلاثٍ فهو أفضل، بخمسٍ فهو أفضل، بسبعٍ فهو أفضل، بتسعٍ فهو أفضل، بإحدى عشرة، بثلاث عشرة، إلى هنا انتهى وتره ﷺ: ثلاث عشرة، ومَن زاد فلا بأس؛ لأنَّ هذا ليس بحدٍّ محدود، فلو أوتر بمئة ركعة وواحدة فلا بأس، يقول النبيُّ لما سُئل عن صلاة الليل: مثنى، مثنى، فإذا خشي أحدُكم الصبحَ صلَّى ركعةً واحدةً تُوتر له ما قد صلَّى خرجه البخاري ومسلم في \"الصحيحين\".\nفدلَّ ذلك على أنَّ صلاة الليل غير محدودةٍ، لا في رمضان، ولا في غيره، فمَن صلَّى إحدى عشرة كما صلَّى النبيُّ ﷺ أو ثلاث عشرة فهو أفضل، ومَن زاد لأنه أحبَّ أن يستفيد من الصلاة؛ لأنَّ عنده نشاطًا، استمر، صلَّى عشرين في رمضان، أو في غيره، أو صلَّى أكثر؛ فلا بأس بذلك.\nوقد جاء عن الصحابة أنهم صلوا عشرين، وصلوا إحدى عشرة بعده ﷺ، وصلَّى بعضُهم أكثر من ذلك، والأمر في هذا واسعٌ، وليس فيه حدٌّ محدود، إلا أن الأفضل أن تكون صلاته مثل صلاة النبي ﷺ إحدى عشرة أو ثلاث عشرة، مع العناية والركود والقراءة والتَّدبر والتَّعقل والركعات، حتى يُصلي صلاة كاملة، فيها من الخشوع والطّمأنينة ما ينفعه الله بها.","link":"https://binbaz.org.sa/fatwas/4249/حكم-الوتر-بعد-صلاة-العشاء-بركعة-واحدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0300.mp3","categories":["الوتر وقيام الليل","شروح الحديث"]},{"id":656,"question":"سنة الوتر هل تؤدى في ليلة مزدلفة؟","title":"هل تؤدى صلاة الوتر ليلة مزدلفة؟","answer":"الجواب: نعم في جميع الليالي، كون النبي ﷺ نام قد يكون نام لأجل تعب أصابه عليه الصلاة والسلام، ولأن الرسول ﷺ شرع لنا التهجد بالليل، والقرآن دل على ذلك.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6687/هل-تودى-صلاة-الوتر-ليلة-مزدلفة","audio":"https://files.zadapps.info/binbaz.org.sa/maram225 - 01 -  Start.mp3","categories":["المبيت بمزدلفة","الوتر وقيام الليل"]},{"id":659,"question":"س: قيام الليل هل هو واجب على الرسول ﷺ؟","title":"هل كان قيام الليل واجبًا على النبي ﷺ؟","answer":"الجواب: به قال بعض أهل العلم، وفيه خلاف بين أهل العلم؛ لأن الله قال: فَتَهَجَّدۡ أمْر، قالوا: فهذا يدل على الوجوب، وبعضهم قال: لا على السنية؛ لأن الرسول ﷺ لما سئل قال له رجل: يا رسول الله، هل عليّ غير الصلوات الخمس؟ قال: لا، إلا أن تطوع، والرسول ﷺ داخل في الأوامر.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6690/هل-كان-قيام-الليل-واجبا-على-النبي-ﷺ","audio":"https://files.zadapps.info/binbaz.org.sa/maram228 - 01 -  Start.mp3","categories":["الوتر وقيام الليل","شروح الحديث"]},{"id":688,"question":"من فسّر صلاة الليل بصلاة العشاء في قوله: وصلوا بالليل؟","title":"ما معنى :\" وصلوا بالليل\" في الحديث؟","answer":"الجواب: لا، التهجد في الليل؛ لأنه قال: والناس نيام.\n(دروس شرح بلوغ المرام، كتاب الجامع)","link":"https://binbaz.org.sa/fatwas/6835/ما-معنى-وصلوا-بالليل-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/maram256 - 03 - .mp3","categories":["شروح الحديث","الوتر وقيام الليل"]},{"id":696,"question":"س: سماحة الشيخ، أرجو الإيضاح: آخر وقتٍ من الليل تجوز فيه صلاة الوتر؟","title":"ما آخر وقت تجوز فيه صلاة الوتر؟","answer":"الجواب: الوتر ما بين صلاة العشاء إلى طلوع الفجر، كما في حديث خارجة بن حذافة: إنَّ الله أمدَّكم بصلاةٍ هي خيرٌ لكم من حُمْرِ النَّعَم، ما بين صلاة العشاء إلى طلوع الفجر، هذا وقته: من بعد صلاة العشاء وسُنتها الراتبة إلى طلوع الفجر.\nفمَن خشي أن يغلبه النومُ صلَّى من أول الليل، وأوتر من أول الليل، ومَن كان يطمع في آخر الليل ويستطيع القيام في آخر الليل فهو أفضل، وكان النبيُّ ﷺ أوتر في أول الليل، وأوتر في وسط الليل، ثم استقرَّ وتره في السحر عليه الصلاة والسلام، وصحَّ في حديث جابرٍ عند مسلمٍ: يقول عليه الصلاة والسلام: مَن خاف ألا يقوم من آخر الليل فليُوتر أوله، ومَن طمع أن يقوم آخر الليل فليُوتر آخر الليل، فإنَّ صلاة آخر الليل مشهودة، وذلك أفضل.\nفمَن تيسر له آخر الليل فهو أفضل، وهو وقت التنزل الإلهي الذي قال فيه النبيُّ ﷺ: ينزل ربنا إلى السماء الدنيا كل ليلةٍ حين يبقى ثلثُ الليل الآخر، فيقول: مَن يدعوني فأستجيب له؟ مَن يسألني فأعطيه؟ مَن يستغفرني فأغفر له؟ حتى ينفجر الفجر، وهذا حديثٌ عظيمٌ متواترٌ يدل على فضل قيام الليل، وأن آخر الليل أولى بهذه العبادة العظيمة.\nوهذا النزول يليق بالله، لا يُشابه خلقه في شيءٍ من صفاته، فنزوله سبحانه واستواؤه على عرشه وغضبه ورضاه ورحمته وكلامه وسمعه وبصره كله يليق بالله ، لا يُشابه خلقَه في شيءٍ من صفاته جلَّ وعلا.\nهذا قول أهل السنة والجماعة، كما قال سبحانه: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ الْبَصِيرُ [الشورى:11]، فهو ينزل كما يشاء نزولًا يليق بجلاله، لا يُشابه خلقه في نزوله، كما أنه استوى فوق العرش استواءً يليق بجلاله، كما قال مالك رحمه الله: \"الاستواء معلوم، والكيف مجهول، والإيمان به واجب»، وهكذا جاء معنى ذلك عن أمِّ سلمة رضي الله عنها، وعن ربيعة شيخ مالك رحمهما الله، وهذا قول أهل السنة قاطبةً في جميع الصِّفات؛ أنها تمرّ كما جاءت، مع الإيمان بها، واعتقاد ما دلَّت عليه، وأنه حقٌّ، لكن على الوجه الذي يليق بالله، لا يُشابه خلقه في شيءٍ من صفاته ، فإنَّ أهل السنة والجماعة يقولون في آيات الصفات وأحاديثها: أمرّوها كما جاءت، قراءتها تفسيرها، أمروها بلا كيفٍ، يعني: مع الإيمان بها، وإثباتها لله، من غير تحريف، ولا تعطيل، ولا تكييف، ولا تمثيل.","link":"https://binbaz.org.sa/fatwas/20260/ما-اخر-وقت-تجوز-فيه-صلاة-الوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0429.mp3","categories":["الوتر وقيام الليل"]},{"id":961,"question":"ما رأيك فيمَن ينتقل بين المساجد في صلاة التراويح بحثًا عن الصوت النَّدي؟","title":"حكم التنقل بين مساجد التراويح للصوت النَّدي","answer":"الجواب:","link":"https://binbaz.org.sa/fatwas/20995/حكم-التنقل-بين-مساجد-التراويح-للصوت-الندي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0792ما رأيكم فيمن يتنقل بين المساجد في صلاة التراويح بحثاً عن الصوت الندي؟ ابن باز فتاوى المحاضرات.mp3","categories":["الوتر وقيام الليل"]},{"id":1138,"question":"ما حكم حمل المصحف للمأموم أثناء الصلاة، وخاصةً ما يُلاحظ في صلاة التراويح في المساجد؟","title":"حكم حمل المصحف في الصلاة للإمام والمأموم","answer":"الجواب:\nلا حرج في ذلك إذا دعت الحاجةُ إلى أن يقرأ من المصحف في التراويح، أو في التهجد، لا بأس بذلك، قد كانت عائشةُ رضي الله عنها يُصلي بها مولاها من المصحف في رمضان، وليس كل أحدٍ يحفظ القرآن، فإذا قرأ من المصحف فلا حرج عليه.\n س: متابعة المأمومين؟\nالشيخ: أما المتابعة فلا، ينصت ولا يُتابع المصحف، ينصت ويجمع قلبه على سماع القرآن، ولا يشتغل بمراجعة تصفح القرآن والاستماع للإمام، الذي يظهر أنه ينبغي ترك ذلك؛ لأنه يشغله عن الإقبال والخشوع.","link":"https://binbaz.org.sa/fatwas/21194/حكم-حمل-المصحف-في-الصلاة-للامام-والماموم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0990ما حكم حمل المصحف في الصلاة وخاصة في التروايح وما حكم المتابعة؟.mp3","categories":["الوتر وقيام الليل"]},{"id":1177,"question":"لا أُصلي الوتر، وكذلك قيام الليل، فما تنصحني حفظك الله؟","title":"ما النصيحة لمن لا يصلي الوتر وقيام الليل؟","answer":"الجواب:\n\nأنصحك بأن تقوم من الليل ما تيسر، فهو دأب الصالحين قبلنا، وهو خلق النبي ﷺ، وخلق الأخيار من عباد الله، كما قال جلَّ وعلا في وصف عباد الرحمن في سورة الفرقان: وَالَّذِينَ يَبِيتُونَ لِرَبِّهِمْ سُجَّدًا وَقِيَامًا [الفرقان:64] يبيتون، وقال فيهم أيضًا: تَتَجَافَى جُنُوبُهُمْ عَنِ الْمَضَاجِعِ المضاجع: المراقد يَدْعُونَ رَبَّهُمْ خَوْفًا وَطَمَعًا وَمِمَّا رَزَقْنَاهُمْ يُنْفِقُونَ  ۝  فَلَا تَعْلَمُ نَفْسٌ مَا أُخْفِيَ لَهُمْ مِنْ قُرَّةِ أَعْيُنٍ جَزَاءً بِمَا كَانُوا يَعْمَلُونَ [السجدة:16- 17]، يتركون المضاجع للتَّهجد؛ خوفًا من الله، وطمعًا في ثوابه، ويُنفقون أيضًا من أموالهم، مع الصلاة والعبادة يُنفقون في وجوه الخير، ويُواسون الفقراء والمحاويج، ويُساعدون الفقراء من طلبة العلم، ويسعون في كل خيرٍ بالنفقة التي يستطيعونها، وقال جلَّ وعلا: يَا أَيُّهَا الْمُزَّمِّلُ  ۝  قُمِ اللَّيْلَ إِلَّا قَلِيلًا  ۝  نِصْفَهُ أَوِ انْقُصْ مِنْهُ قَلِيلًا  ۝  أَوْ زِدْ عَلَيْهِ وَرَتِّلِ الْقُرْآنَ تَرْتِيلًا [المزمل:1- 4]، وقال في وصف المتَّقين في سورة الذاريات: كَانُوا قَلِيلًا مِنَ اللَّيْلِ مَا يَهْجَعُونَ  ۝  وَبِالْأَسْحَارِ هُمْ يَسْتَغْفِرُونَ [الذاريات:17- 18].\n\nفعليك بخُلق الرسول ﷺ وخلق الأخيار، ولو قليلًا، أقلّه ركعة بعد العشاء، بعد صلاة العشاء صلِّ ما يسَّر الله، بعد راتبة العشاء، ثلاثًا أو خمسًا أو أكثر من ذلك، أو في وسط الليل قبل أن تنام، أو في آخر الليل، وأفضله آخر الليل، أفضل ذلك آخر الليل لمن استطاع؛ لقول النبي ﷺ في الحديث الصحيح الذي رواه مسلم: مَن خاف ألا يقوم من آخر الليل فليُوتر أوله، ومَن طمع أن يقوم آخر الليل فليُوتر آخر الليل، فإن صلاة آخر الليل مشهودة، وذلك أفضل رواه مسلمٌ في \"الصحيح\"، وهذا تفصيلٌ من النبي ﷺ.\n\nوكذلك يقول ﷺ فيما رواه أيوب: الوتر حقٌّ، فمَن أحبَّ أن يُوتر بخمسٍ فليفعل، ومَن أحبَّ أن يُوتر بثلاثٍ فليفعل، ومَن أحبَّ أن يُوتر بواحدةٍ فليفعل، وكان يُوتر بإحدى عشرة ﷺ، وربما أوتر بثلاث عشرة، هذا هو الغالب، وربما أوتر في بعض الأحيان بسبعٍ أو بتسعٍ أو بخمسٍ أو بثلاثٍ.\n\nفالوتر أقله ركعة، الوتر ركعة من آخر الليل، وقد أوصى النبيُّ ﷺ أبا هريرة وأبا الدَّرداء بالوتر قبل النوم، وقال العلماء: لعلَّ ذلك لأنَّهما يدرسان العلم قبل النوم، فيخشيان ألا يقوما في آخر الليل، أما مَن طمع أن يقوم آخر الليل فهو أفضل.","link":"https://binbaz.org.sa/fatwas/21255/ما-النصيحة-لمن-لا-يصلي-الوتر-وقيام-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1139ما نصيحتكم لشخص لا يصلي الوتر ولا يصلي قيام الليل؟.mp3","categories":["الوتر وقيام الليل"]},{"id":1370,"question":"الأمر بقيام الليل خاص بالرسول ﷺ أو للأمة عامة؟","title":"هل الأمر بقيام الليل خاص بالرسول ﷺ؟","answer":"الجواب:\nسُنَّة، للأمة عامَّة وَالَّذِينَ يَبِيتُونَ لِرَبِّهِمْ سُجَّدًا وَقِيَامًا [الفرقان:64]، ويقول عن المتقين: كَانُوا قَلِيلًا مِنَ اللَّيْلِ مَا يَهْجَعُونَ ۝ وبالأسحار هم يستغفرون [الذاريات:17-18].","link":"https://binbaz.org.sa/fatwas/21463/هل-الامر-بقيام-الليل-خاص-بالرسول-ﷺ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الأمر بقيام الليل خاص بالرسول أو للأمة عامة.mp3","categories":["الوتر وقيام الليل"]},{"id":1373,"question":"الصحيح في السجود: هل كثرة الركعات أو طول السجود؟","title":"هل كثرة الركعات أفضل أم طول السجود؟","answer":"الجواب:\nظاهر الحديث يقتضي كثرة الركعات، وبعض أهل العلم فضل طول القيام؛ ولأنه في بعض الليالي طوَّل في صلاته ﷺ، لكن الأفضل أن تكون معتدلة، صلاة معتدلة، ركوعها وسجودها وقيامها متقارب؛ حتى لا يَشُق على نفسه وحتى يُكثر من الركعات.","link":"https://binbaz.org.sa/fatwas/21466/هل-كثرة-الركعات-افضل-ام-طول-السجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في صلاة التطوع.mp3","categories":["الوتر وقيام الليل"]},{"id":1407,"question":"هدي النبي ﷺ في قيام الليل كما يفعل داود عليه السلام؟","title":"ما هَدْيُ النبي ﷺ في قيام الليل؟","answer":"الجواب:\nتقول عائشة: كان آخر أمره ﷺ يصلي آخر الليل، انتهى أمره إلى آخر الليل صلاته، صلى من أوله ومن وسطه ومن آخره، وانتهى وتره إلى آخر الليل، صار وتره حين التَّنَزُّل الإلهي في الثلث الأخير.\nس: هل الأفضل أن نفعل كما فعل النبي ﷺ؟\nج: نعم، الثلث الأخير إذا تيسر، يكون سُدُسًا بما فعل داود، وسُدُسًا من الثلث الأخير.\nس: إن قام في آخر الليل هل يُسَنُّ له أن ينام قبيل الفجر؟\nج: إذا تيسر ورأى المصلحة في ذلك، مثل ما فعل داود، إذا تهجد في السدس الرابع والخامس، ونام السدس السادس؛ حتى يتقوَّى على عمل النهار لا بأس؛ إذا ما كان يخشى ينام عن الفجر.","link":"https://binbaz.org.sa/fatwas/21500/ما-هدي-النبي-ﷺ-في-قيام-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هدي النبي عليه الصلاة والسلام في قيام الليل.mp3","categories":["الوتر وقيام الليل"]},{"id":1409,"question":"هناك حكمة من عدم الوِتْر في النهار؟","title":"هل للنهار وِتْر مثل وِتْر الليل؟","answer":"الجواب:\nالنهار وِتْره المغرب.  ووِتْر الليل الصلاة بالليل وصلاة ركعة في آخر الليل، هذا وِتر الليل.","link":"https://binbaz.org.sa/fatwas/21503/هل-للنهار-وتر-مثل-وتر-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/وتر النهار ووتر الليل.mp3","categories":["الوتر وقيام الليل"]},{"id":2116,"question":"قول الإمام أحمد: \"مَن ترك الوترَ باستمرار فهو رجلٌ فاسقٌ\"؟","title":"ما حكم مَن يترك الوتر باستمرار؟","answer":"الجواب:\n\"رجل سوء\"، هذا اجتهادٌ منه، فالوتر ليس بواجبٍ، بل هو سنة مؤكدة ولا يلزم، ولكن كلامه غير صحيح من جهة الأدلة الشرعية.\nس: إذا تركه يكون آثمًا؟\nج: لا، ليس آثمًا، فالرسول لما علَّم الرجلَ الصَّلوات الخمس قال له الرجل: هل عليَّ غيرها يا رسول الله؟ قال: لا، إلا أن تطوع.","link":"https://binbaz.org.sa/fatwas/22234/ما-حكم-من-يترك-الوتر-باستمرار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى قول الإمام أحمد من ترك الوتر باستمرار فهو رجل فاسق.mp3","categories":["الوتر وقيام الليل"]},{"id":2252,"question":"مَن نسي الوتر؟","title":"كيف ومتى يقضي الوتر مَنْ نسيه؟","answer":"الجواب:\nيُصليها في وقت الضُّحى قبل الظهر، فيُصلي ما تيسر، فقد كان النبيُّ إذا فاته ورده من الليل قضاه من النهار، كذا قالت عائشة رضي الله عنها، فيُصليه شفعًا، لا يُوتِر، ثنتين، ثنتين..... الأقرب -والله أعلم- أنه الضُّحى أو الظهر، أما العصر فلا، يقول في الحديث الآخر: مَن فاته حزبَه من الليل فقضاه من النهار قبل الظهر فكأنما قضاه من الليل.","link":"https://binbaz.org.sa/fatwas/22375/كيف-ومتى-يقضي-الوتر-من-نسيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم مَن نسي الوتر.mp3","categories":["الوتر وقيام الليل"]},{"id":2303,"question":"في التراويح: الإمام إذا صلَّى الوِتر هل الأولى أن يُوافقه المأمومُ أم يقوم ويأتي بركعةٍ زائدةٍ؟","title":"هل الوِتر أفضل مع إمام التراويح أم تأجيله؟","answer":"الجواب:\nلا، الأفضل أن يُصلي معه، ثم يُصلي ما تيسر في آخر الليل.\nس: مثنى، مثنى؟\nج: نعم.\nس: أليس الوترُ آخر الليل أفضل؟\nج: مَن قام مع الإمام حتى ينصرف كُتِبَ له قيام ليلةٍ، فيُصلي مع الإمام، وإذا أحبَّ أن يتطوع بعد ذلك فله أن يتطوع بدون وِترٍ، فالوِتر الأول يكفي.","link":"https://binbaz.org.sa/fatwas/22427/هل-الوتر-افضل-مع-امام-التراويح-ام-تاجيله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صلى إمام التراويح الوتر فهل الأولى أن يُوافقه المأمومُ.mp3","categories":["الوتر وقيام الليل"]},{"id":2375,"question":"الركعتين التي بعد الوتر، يقرأ في الأولى الزلزلة؟","title":"حكم صلاة ركعتين أو أكثر بعد الوتر","answer":"الجواب:\nثبت أن النبي ﷺ كان يصلي ركعتين بعد الوتر، يبين الجواز، أنه يجوز فعل الصلاة بعد الوتر، لكن الأفضل أن يكون الوتر هو الآخر ؛للحديث الصحيح: اجعلوا آخر صلاتكم بالليل وترًا فالأفضل أن يختم بركعة الوتر، وإن صلى ركعتين تأسيًا بالنبي ﷺ لبيان الجواز وأنه يجوز لمن صلى في أول الليل أو في أثنائه وأوتر أن يتهجد أيضًا ركعتين أو أكثر، لكن كونه يختم بالوتر هو الأفضل، كما في الصحيحين.","link":"https://binbaz.org.sa/fatwas/22500/حكم-صلاة-ركعتين-او-اكثر-بعد-الوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم صلاة ركعتين بعد الوتر.mp3","categories":["الوتر وقيام الليل"]},{"id":2424,"question":"التراويح هل الأفضل إحدى عشر ركعة؟","title":"ما الأفضل في عدد ركعات القيام والقنوت؟","answer":"الجواب:\nنعم هذا هو الأفضل، وإن أوتر بثلاث وعشرين فلا بأس، لكن مع التأنّي وعدم العجلة، يَرْكُد في قراءته وفي سجوده وركوعه أفضل، وإن صلى ثلاثًا وعشرين مع الركود فلا بأس.\nس: بالنسبة للدعاء كل ليلة يدعو أو لا؟\nالشيخ: القنوت أفضل كل ليلة.","link":"https://binbaz.org.sa/fatwas/22552/ما-الافضل-في-عدد-ركعات-القيام-والقنوت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/عدد ركعات صلاة التراويح والقنوت فيها.mp3","categories":["الوتر وقيام الليل"]},{"id":2452,"question":"مَن ترك الوتر أبدًا؟","title":"ما حكم الوِتْر وسَرْدِه وقضائه وحكم تركه؟","answer":"الجواب:\nسنة ما هو بفريضة، الفريضة خمس صلوات: الظهر والعصر والمغرب والعشاء والفجر.\nس: ما يأثم؟\nالشيخ: ما يأثم لا.\nس: ولا يُفَسَّق؟\nالشيخ: ولا يُفَسَّق.\nس: أوتروا يا أهل القرآن؟\nالشيخ: الوتر سُنة، لما سُئل النبي ﷺ لما أخبر المسلمين عن الصلوات الخمس قال له السائل: هل علي غيرها؟ قال: لا، إلا أن تطوع.\nس: لو سرد إحدى عشرة ركعة؟\nالشيخ: لا، السنة أن لا يسردها، يسلم من كل ثنتين، لكن لو سرد تسعًا لا بأس، أو سبعًا لا بأس، يجلس في الثامنة التشهد الأول أو في السادسة التشهد الأول، وإن سرد سبعًا جميعًا أو خمسًا جميعًا أو ثلاثًا جميعًا فلا بأس؛ لأنه فعله النبي ﷺ.\nس: لو طلع الفجر ولم يكن أوتر من قبل؟\nالشيخ: يُوتِر ولو في الفجر؛ لأن الأذان على الظن، ما هو على جزم الصبح.\nس: يُقال يا أهل القرآن للمسلمين أم للحَفَظَة؟\nالشيخ: للمسلمين.\nس: لو فاته الوتر؟\nالشيخ: يصلي من النهار ما تيسر مقابل صلاة ثلاث يسلم تسليمتين، عادته خمس يسلم ثلاث تسليمات، عادته سبع يسلم أربع تسليمات يزيد واحدة، النبي ﷺ كان إذا شغله عن وتره نوم أو مرض صلى من النهار ثنتي عشرة ركعة، كان الغالب عليه إحدى عشرة فإذا شغل عنها في الليل من نوم أو مرض صلى ثنتي عشرة، ست تسليمات.\nس: الركعتان التي تفتح بهما صلاة الليل؟\nالشيخ: ما تحسب هذيك ركعتين خفيفتين.\nس: إن كانوا يصلون الوتر في المسجد؟\nالشيخ: ما في بأس، لكن في البيت أفضل، ومن صلاها في المسجد فلا بأس، والبيت أفضل.\nس: حديث عائشة أنه كان يصلي أربعا فلا تسأل عن حسنهن هل يسردها كلها؟\nالشيخ: لا، تسليمتين، يسلم من كل ثنتين؛ لأن الأحاديث تفسر بعضها بعضًا.","link":"https://binbaz.org.sa/fatwas/22581/ما-حكم-الوتر-وسرده-وقضاىه-وحكم-تركه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الوتر وحكمه وحكم تركه أبدا.mp3","categories":["الوتر وقيام الليل"]},{"id":2460,"question":"رجل عليه وتر وأراد أن يوتر بركعة واحدة فدخل المسجد ليلاً فهل هذه الركعة إذا أدّاها....؟","title":"حكم تحية المسجد لمَن أراد أن يوتر بواحدة","answer":"الجواب:\nلا، يصلي تحية المسجد أولًا ركعتين ثم يوتر، تحية المسجد ركعتان ثم يوتر بواحدة، السنة ركعتان تحية المسجد، ما زاد فليس من تحية المسجد، تطوع.","link":"https://binbaz.org.sa/fatwas/22589/حكم-تحية-المسجد-لمن-اراد-ان-يوتر-بواحدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أراد أن يوتر بواحدة بعد أن دخل المسجد.mp3","categories":["قضايا المرأة","الوتر وقيام الليل","الحيض والنفاس","المساجد ومواضع السجود"]},{"id":2489,"question":"قول الرسول ﷺ: نعم الرجل عبدالله لو كان يقوم من الليل ألا يدل على أن القيام شرط في العدالة؟","title":"هل قيام الليل شَرْطٌ في العدالة؟","answer":"الجواب:\nلا ما هو بشرط، بس مَدْح، مزيد مدح، وإلا هو تطوع، نافلة، ليس بفريضة، لكن يدل على أن أهل الليل يُمدحون بهذا، يُثنى عليهم كما أثنى الله عليهم، هذا الأسلوب فيه حث وتحريض.","link":"https://binbaz.org.sa/fatwas/22619/هل-قيام-الليل-شرط-في-العدالة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل قيام الليل شرط في العدالة.mp3","categories":["الوتر وقيام الليل"]},{"id":2490,"question":"إذا أوتر الإنسان بعد العشاء ونام إلى الفجر ما يبول الشيطان في أذنيه؟","title":"هل يَسْلَم مَنْ بكّر بالوتر مِن بَوْل الشيطان؟","answer":"الجواب:\nلا حرج، ما دام صلى ما يسّر الله له.\nس:إذا أوتر قبل أن ينام؟\nالشيخ: نعم، حصل المطلوب يصلي ما تيسّر، إذا استيقظ في آخر الليل يصلي ثنتين أربع.\nس: كيف يفعل وقد أوتر بواحدة؟\nالشيخ: يكفيه الوِتْر الأول، لا يعيد الوتر، النبي عليه السلام يقول: لا وتران في ليلة يصلي \"شفع\" ثنتان أربع ست ثمان، يسلم من كل ثنتين. س: يجعل آخرها وِترًا؟ الشيخ: لا... س: يكفيه الوِتر السابق؟ الشيخ: نعم.","link":"https://binbaz.org.sa/fatwas/22620/هل-يسلم-من-بكر-بالوتر-من-بول-الشيطان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أوتر بعد العشاء أو قبل أن ينام.mp3","categories":["الوتر وقيام الليل"]},{"id":2498,"question":"بعضهم يقول النبي ﷺ أوتر بسبع وخمس وإحدى عشر وثلاثة عشر، ما يعارض أنه كان عمله دِيمَة؟","title":"هل تَنَوُّع الوِتر يعارض أن عمله ﷺ ديمة؟","answer":"الجواب:\nدِيمَة، لكن حسب التيسير.","link":"https://binbaz.org.sa/fatwas/22628/هل-تنوع-الوتر-يعارض-ان-عمله-ﷺ-ديمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الوتر بسبع وخمس وإحدى عشر وثلاثة عشر.mp3","categories":["الوتر وقيام الليل"]},{"id":2509,"question":"من قال من الفقهاء أن لليل وِتْرًا وللنهار وِتْرًا؟","title":"هل لليل وِتْر وللنهار وِتْر؟","answer":"الجواب:\nوِتْر النهار المغرب في نهاية النهار عند غروب الشمس، وفي النهار يشفع كما دلت عليه السنة.","link":"https://binbaz.org.sa/fatwas/22639/هل-لليل-وتر-وللنهار-وتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل لليل وتر وللنهار وتر.mp3","categories":["الوتر وقيام الليل"]},{"id":2655,"question":"هل يأثمون الذين يصلون في الحرم في أثناء الصلاة الناس يتكلمون ويتقهوون وصلاة التراويح مقامة، هل يأثمون؟","title":"حكم مَن يتكلمون بالمسجد أثناء صلاة التراويح","answer":"الجواب: لا، ما يأثمون، صلاة التراويح نافلة، ما هي فريضة، لكن بس لا يشوّشون على الناس، الواجب عليهم عدم التشويش، أما إذا كان ما حولهم أحد يشوّشون عليه؛ ما يخالف.","link":"https://binbaz.org.sa/fatwas/22791/حكم-من-يتكلمون-بالمسجد-اثناء-صلاة-التراويح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صلاة التراويح مقامة والبعض يتكلمون ويتقهوون.mp3","categories":["المساجد ومواضع السجود","الوتر وقيام الليل"]},{"id":2656,"question":"في فرق بين التراويح والقيام والتهجد؟","title":"ما الفرق بين التراويح والقيام والتهجد؟","answer":"الجواب: كله يُسمّى \"قيام\"، يُسمّى \"تراويح\" اصطلاحًا، ويُسمّى قيامًا، يسمى قيام الليل، ويُسمّى \"تراويح\". وفي العشر الأخيرة السُّنَّة إحياء الليل.","link":"https://binbaz.org.sa/fatwas/22792/ما-الفرق-بين-التراويح-والقيام-والتهجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الفرق بين التراويح والقيام والتهجد.mp3","categories":["الوتر وقيام الليل"]},{"id":2696,"question":"إذا كان يخشى أن لا يقوم: يُوتِر أول الليل، ثم إذا قام يصلي؟","title":"ما يفعل من أوتر أول الليل ثم أراد الصلاة؟","answer":"الجواب: إذا قام من آخر الليل يصلي ما تيسر، لكن يسده الوتر الأول، لا يعيد الوتر، يصلي ثنتين أو أربع أو أكثر، يسلم من كل ثنتين.\nس: لا حد لذلك؟\nالشيخ: نعم.","link":"https://binbaz.org.sa/fatwas/22835/ما-يفعل-من-اوتر-اول-الليل-ثم-اراد-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الوتر أول الليل ثم أراد الصلاة.mp3","categories":["الوتر وقيام الليل"]},{"id":2711,"question":"تقصير الصلاة في التراويح والقيام هل جاء عن السلف؟","title":"حكم التقصير والتطويل في القيام والتراويح","answer":"الجواب: ما أخْبُرُ في هذا شيئًا، ما أعلم شيئًا منصوصًا في هذا، لكن الأمر واسع؛ إذا خفف بعضها، وطوّل بعضها؛ الأمر واسع.","link":"https://binbaz.org.sa/fatwas/22853/حكم-التقصير-والتطويل-في-القيام-والتراويح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تقصير صلاة القيام أو تطويلها.mp3","categories":["الوتر وقيام الليل"]},{"id":2715,"question":"ركعتان بين صلاة العشاء وصلاة التراويح، هل الأفضل الإنسان يسبح أو يصلي ركعتين؟","title":"ما الأفضل من التطوّع بين العشاء والتراويح؟","answer":"الجواب: سنة العشاء أول قبل التراويح، التهجد بعد نافلة العشاء، بعد الراتبة. يصلي العشاء ثم الراتبة ثم يتهجد في الليل التراويح أو غيرها.\nس: هل الأفضل يسبّح أو يقوم يؤدي هاتين الركعتين؟\nالشيخ: بعد ما يفرغ من الأذكار يصلي الراتبة، هذه السنة، السنة أولاً يأتي بالأذكار الشرعية، ثم يصلي الراتبة.\nس: حتى إذا تقدم الإمام وصلى التراويح؟\nالشيخ الإمام لا يتقدم إلا بعد ما يصلى الناس النافلة.","link":"https://binbaz.org.sa/fatwas/22857/ما-الافضل-من-التطوع-بين-العشاء-والتراويح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الأفضل التسبيه أم صلاة ركعتين بين صلاة العشاء وصلاة التراويح.mp3","categories":["صلاة التطوع","الوتر وقيام الليل"]},{"id":3587,"question":"الدعاء في رمضان في القيام في كل يوم هل هو سُنة؟","title":"حكم الدعاء في رمضان في القيام كل ليلة","answer":"الجواب: هذا قنوت الوتر الذي جاء في حديث الحسن .","link":"https://binbaz.org.sa/fatwas/23769/حكم-الدعاء-في-رمضان-في-القيام-كل-ليلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الدعاء في رمضان في القيام في كل يوم.mp3","categories":["القنوت في الصلاة","الوتر وقيام الليل"]},{"id":3629,"question":"لو وُجد قوم قالوا: نريد أن نجتمع ونصلي آخر الليل بدلاً من أن نصلي مع الناس في أوله؟","title":"حكم تأخير جماعة للتراويح إلى آخر الليل","answer":"الجواب: الصلاة مع الناس في المساجد أفضل؛ لأنها صارت شعارًا؛ النبي صلى بهم بعد صلاة العشاء لأنها أرفق بالناس......\nس: لو اتفق الجماعة مع الإمام أن يجعلوا صلاتهم آخر الليل؟\nلو كانوا في قرية خاصة لا مانع؛ لأن آخر الليل أفضل لكن قد يكون هناك مساجد، قد يكون فيه مشقة على الناس، هذا يقتدي بهذا وهذا يقتدي بهذا؛ فيشق على الناس........\nخروجه ﷺ وكانوا في المسجد، فخرج في جوف الليل يصلي فصلوا معه، ما كان ابتداء من حين صلى العشاء، بل قد دخل بيته ثم خرج في جوف الليل.","link":"https://binbaz.org.sa/fatwas/23813/حكم-تاخير-جماعة-للتراويح-الى-اخر-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صلاة التراويح مع الناس في المساجد أفضل.mp3","categories":["الوتر وقيام الليل"]},{"id":3630,"question":"لو مجموعة في سفر أرادوا أن يصلوا التراويح جماعة؟","title":"هل تُصلى التراويح جماعة في السفر؟","answer":"الجواب: لا بأس، ما في مانع، تُصلى سفرًا وحضرًا.","link":"https://binbaz.org.sa/fatwas/23814/هل-تصلى-التراويح-جماعة-في-السفر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا أراد مسافرون صلاة التراويح جماعة.mp3","categories":["الوتر وقيام الليل"]},{"id":3631,"question":"لما سألته عائشة رضي الله عنها تقول: تنام قبل أن توتر. وقد أوتر، أليس كذلك؟","title":"هل كان النبي ﷺ ينام قبل أن يوتر؟","answer":"الجواب: هذا في بعض الليالي، في بعض الليالي يوتر وفي بعض الليالي يؤخر الوتر، سألته عن الليالي التي أخر فيها الوتر...... مقصودها أنه ﷺ قد ينام قبل أن يوتر، قال: إن عيناي تنامان ولا ينام قلبي، يعني: يستيقظ حتى يوتر عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/23815/هل-كان-النبي-ﷺ-ينام-قبل-ان-يوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كان النبي ينام قبل أن يوتر وكان يوتر قبل أن ينام.mp3","categories":["الوتر وقيام الليل"]},{"id":4352,"question":"بعض النساء تعودت أن تصلي صلاة التراويح في أيام رمضان في المسجد فإذا أتتها الدورة تقول: أريد أن أذهب وأجلس في طرف المسجد؛ كي تراجع مع الإمام، وتتعلم القراءة الصحيحة، هل لها ذلك؟","title":"حكم مكث الحائض في المصلى لسماع التراويح","answer":"الجواب: إذا كان في محل خارج المسجد ما يخالف، عند الباب، خارج المسجد، ما في بأس.\nس: في نفس مصلى النساء؟\nج: إذا كان في المسجد لا، إذا كان مصلاهن من المسجد لا.","link":"https://binbaz.org.sa/fatwas/24628/حكم-مكث-الحاىض-في-المصلى-لسماع-التراويح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في صلاة المرأة التراويح في المسجد.mp3","categories":["المساجد ومواضع السجود","الوتر وقيام الليل"]},{"id":4550,"question":"مكوث النساء في الحرم الآن؟","title":"حكم مكوث النساء في الحرم","answer":"الجواب: النساء كذلك إن كان ما في ضرر، مع التَّستر ومع البُعد عن الفتنة فلا بأس، كما في قصة سعد بن معاذ لما أُصيب في أكحله يوم الخندق ضرب عليه النبيُّ ﷺ خيمةً في المسجد، وكان في المسجد أيضًا امرأة لها خيمة، عندها خيمة في المسجد، ما لها أهل، وأقرَّها النبيُّ في المسجد عليه الصلاة والسلام.  فإذا دعت الحاجةُ إلى ذلك فلا بأس، لكن تكون في محلٍّ مستورٍ .....، وكان بعض نساء النبي ﷺ يعتكفن في المسجد في خيام مستورة، فإذا كان وجود المرأة في المسجد لا ضررَ فيه كخيمةٍ خاصةٍ ..... خاصة، ودعت الحاجةُ إلى ذلك فلا حرج في ذلك .......، لكن لا بد [من] الحذر من إيذاء المسجد، حتى ولو كان بعض الناس يُقيم الأعياد في المساجد، أدركت هذا في هذه البلاد وفي غيرها، يوم العيد يُقدِّمون الطعام في المسجد؛ لأنهم ما عندهم مساكن تتسع للناس .....، فالمسجد أوسع، فإذا جعلوه للطعام وأكلوا فلا بأس عند الحاجة، لكن إذا ..... ألا يقع في المسجد فيه من الأكل.","link":"https://binbaz.org.sa/fatwas/24830/حكم-مكوث-النساء-في-الحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مكوث النساء في الحرم.mp3","categories":["قضايا المرأة","الوتر وقيام الليل","الحيض والنفاس","المساجد ومواضع السجود"]},{"id":4587,"question":"إذا صلَّى أول الليل وأوتر، وقام آخر الليل وأراد أن يُصلي فهل يُوتر؟","title":"حكم من أوتر أول الليل ثم أراد الصلاة آخره","answer":"الجواب: إذا أوتر في أول الليل ثم قام في آخر الليل يُصلي ما تيسر من دون وترٍ، يكفيه الوتر الأول، يصلي ثنتين أو أربعًا أو أكثر لكن يكفيه الوتر الأول؛ لقول النبي ﷺ: لا وتران في ليلةٍ، يُصلي ما تيسر له من آخر الليل، ولكن لا يُعيد الوتر، ويكفيه الوتر الأول.","link":"https://binbaz.org.sa/fatwas/24876/حكم-من-اوتر-اول-الليل-ثم-اراد-الصلاة-اخره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من صلَّى أول الليل وأوتر، ثم قام آخر الليل وأراد الصلاة.mp3","categories":["الوتر وقيام الليل"]},{"id":4588,"question":"بالنسبة للتفضيل: هل الأفضل الزيادة على إحدى عشر ركعة أو إطالة القراءة؟","title":"هل الأفضل في القيام زيادة الركعات أم الإطالة؟","answer":"الجواب: الأفضل التطويل، تطويل الركوع والسجود، هذا هو الأفضل؛ لفعله ﷺ، ولو ما صلَّى إلا خمسًا أو ثلاثًا، وإن صلَّى سبعًا أو تسعًا أو إحدى عشرة ولم يُطوّل فلا حرج، الأمر واسع بحمد الله، لكن التطويل هو الأفضل؛ لما فيه من الخشوع والتَّدبر في القراءة، والتَّمهل في الركوع والسجود؛ حتى يتمكَّن من كثرة التَّسبيح والدعاء في السجود، وفعله يدل على هذا؛ لأنه كان يُطوّل عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/24877/هل-الافضل-في-القيام-زيادة-الركعات-ام-الاطالة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alzyadah-3la-e7dy3ashr-rak3ah-fi-qiam-allail.mp3","categories":["الوتر وقيام الليل"]},{"id":4589,"question":"في التراويح إذا قام إلى الركعة الثالثة ساهيًا؟","title":"حكم القيام لثالثة في التراويح ساهيًا","answer":"الجواب: يرجع، صلاة الليل مثنى مثنى، يرجع ويسجد للسهو، مثل: لو قام إلى الثالثة في الفجر أو في الجمعة يرجع.","link":"https://binbaz.org.sa/fatwas/24878/حكم-القيام-لثالثة-في-التراويح-ساهيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/القيام لثالثة في التراويح ساهيًا.mp3","categories":["الوتر وقيام الليل"]},{"id":4590,"question":"مَن فاته الوتر إلى بعد صلاة الفجر هل الأفضل التَّأخير؟","title":"ما يفعل مَن فاته الوتر إلى وقت صلاة الفجر؟","answer":"الجواب: يُصلي من الضُّحى، إذا فاته الوتر يُصلي من النهار، الضُّحى.\nس: بعد الأذان مثلًا؟\nج: لا، لا، إذا جاء الصبح انتهى الوتر، الفروق اليسيرة يُعفى عنها عند بعض أهل العلم، لا حرج في الشيء اليسير.","link":"https://binbaz.org.sa/fatwas/24879/ما-يفعل-من-فاته-الوتر-الى-وقت-صلاة-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم مَن فاته الوتر إلى بعد صلاة الفجر.mp3","categories":["الوتر وقيام الليل"]},{"id":4591,"question":"إذا داوم على القنوت في الوتر؟","title":"حكم المداومة على قنوت الوتر والتطويل فيه؟","answer":"الجواب: الذي أوصى به النبيُّ ﷺ الحسن: علَّمه ﷺ القنوت: اللهم اهدني فيمَن هديتَ، وعافني فيمَن عافيتَ، وتولَّني فيمَن تولَّيتَ، وبارك لي فيما أعطيتَ، وقني شرَّ ما قضيتَ، فإنك تقضي ولا يُقضى عليك، فإنه لا يذلُّ مَن واليتَ، ولا يعزُّ مَن عاديتَ، تباركتَ ربنا وتعاليت.\nوكان النبي ﷺ يقول في آخر وتره:  اللهم إني أعوذ برضاك من سخطك، وبمُعافاتك من عقوبتك، وأعوذ بك منك، لا أُحصي ثناءً عليك أنت كما أثنيتَ على نفسك خرَّجهما الخمسة: أحمد وأهل السنن.\nفهذا يدل على شرعية قنوت الوتر، وأن يقول هذا الدعاء، وحديث الحسن ثابت، وحديث عليٍّ ثابت أيضًا، وهو يدل على شرعية القنوت.\nوكان بعضُ السلف من الصحابة وغيرهم لا يقنتون إلا في النصف الأخير من رمضان، والصواب أنه مشروع دائمًا في الوتر: في رمضان وفي غيره؛ لحديث الحسن وما جاء في معناه.\nأما زيادة \"ولا يعزُّ مَن عاديتَ\" فالمؤلف ذكرها هنا، وذكر الحافظُ رحمه الله وجماعة أنها في بعض نسخ أبي داود، وذكرها البيهقي رحمه الله، وليست عند الترمذي وابن ماجه وأحمد والنَّسائي، والمؤلف ذكرها هنا لأنها جاءت عند أبي داود في بعض النُّسخ.\nس: بالنسبة لإطالة القنوت والأدعية في هذه الأيام، ما رأيكم فيه؟\nج: لا بأس أن يزيد، ولكن ينبغي أن يُراعي عدم الطول، لا يشقّ على الناس، لو زاد دعوات لا بأس، لكن لا يشقّ على الناس؛ ولهذا كان عمر يزيد: \"اللهم إنا نستعينك ونستهديك ..\" إلى آخره، فإذا زاد بعض الدَّعوات لكن يُراعي عدم المشقَّة.","link":"https://binbaz.org.sa/fatwas/24880/حكم-المداومة-على-قنوت-الوتر-والتطويل-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المداومة على القنوت في الوتر والتطويل فيه.mp3","categories":["الوتر وقيام الليل","القنوت في الصلاة"]},{"id":4592,"question":"الحكمة في استفتاح القيام بركعتين خفيفتين؟","title":"ما الحكمة في استفتاح القيام بركعتين خفيفتين؟","answer":"الجواب: الله أعلم، لكن لعلَّ السر في ذلك أن يتهيَّأ إلى التطويل في القراءة والركوع، فإنه ينشط؛ لأنه قد يكون عنده شيء من الضعف، فإذا صلَّى ركعتين خفيفتين كان فيها نشاط له على ما بعدها، والله أعلم، لا أعلم نصًّا في هذا، لكن لعلَّ هذا هو الصواب.","link":"https://binbaz.org.sa/fatwas/24881/ما-الحكمة-في-استفتاح-القيام-بركعتين-خفيفتين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما الحكمة في استفتاح القيام بركعتين خفيفتين.mp3","categories":["الوتر وقيام الليل"]},{"id":4594,"question":"الأفضل أنه يجمع الوتر مع الشفع، أو يُؤخر الشفع إلى آخر الليل، مثل: لو إنسان صلَّى الشفع في أول الليل، وأحبَّ أن يُؤخر الوتر إلى آخر الليل، يفصل بينهما، يُصلي الوتر وحده في آخر الليل؟","title":"ما الأفضل في جمع الوتر مع الشفع؟","answer":"الجواب: الأمر واسع، لا أعلم في هذا شيئًا، لكن إذا تيسر له أن يكون الوترُ معه أفضل؛ لأن الصلاة في آخر الليل أفضل، إذا تيسر يُؤخّر معه ركعتين أو أربع ركعات، يُصلي خمسًا من آخر الليل أو ثلاثًا يكون أفضل؛ لأنه أكثر في الأجر.","link":"https://binbaz.org.sa/fatwas/24883/ما-الافضل-في-جمع-الوتر-مع-الشفع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة جمع الوتر مع الشفع.mp3","categories":["الوتر وقيام الليل"]},{"id":4610,"question":"صلاة المرأة في المسجد الحرام أفضل من صلاتها في بيتها؟","title":"هل صلاة المرأة في الحرم أفضل من بيتها؟","answer":"الجواب: بيتها أفضل، وإن صلَّت في المسجد الحرام متأدبةً بدون تجمُّلٍ ولا طيبٍ ولا شيءٍ من المحظورات فلا بأس.","link":"https://binbaz.org.sa/fatwas/24899/هل-صلاة-المراة-في-الحرم-افضل-من-بيتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أيهما أفضل للمرأة صلاتها في المسجد الحرام أم في بيتها.mp3","categories":["قضايا المرأة","الوتر وقيام الليل","الحيض والنفاس","المساجد ومواضع السجود"]},{"id":4712,"question":"هل أوتر الرسول ﷺ في مُزدلفة؟","title":"هل أوتر النبي في مُزدلفة؟","answer":"الجواب: ما ذكر شيئًا، لكن الظاهر أنه على عادته؛ لأنه اضطجع بعد التَّعب، وقد يكون أوتر قبل أن ينام؛ لأنه اضطجع بعد تعب وقوفه في مُزدلفة من بعد الظهر إلى غروب الشمس، لا شكَّ أنه في يوم حارٍّ، فلا بدَّ من تعبٍ؛ ولهذا اضطجع حتى طلع الفجرُ، لعله قد يكون شُغل عن ذلك بالتَّعب، أو أنه أوتر قبل النوم، تقول عائشةُ رضي الله عنها: \"كان إذا شغله عن التَّهجد بالليل مرضٌ أو نومٌ صلَّى من النهار ثنتي عشرة ركعة\"، السنة أن يُوتر الإنسان ولو قبل النوم في مُزدلفة وغيرها، وفي السفر والحضر، سنة دائمة.","link":"https://binbaz.org.sa/fatwas/25004/هل-اوتر-النبي-في-مزدلفة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل أوتر النبي في مُزدلفة.mp3","categories":["الوتر وقيام الليل","المبيت بمزدلفة"]},{"id":4831,"question":"مَن فسَّر صلاة الليل بصلاة العشاء: صلوا بالليل؟","title":"ما المراد بالصلاة في حديث «وصلوا بالليل والناس نيام»؟","answer":"لا، التهجد بالليل؛ لأنه قال: والناس نيام، التهجد بالليل.","link":"https://binbaz.org.sa/fatwas/25251/ما-المراد-بالصلاة-في-حديث-وصلوا-بالليل-والناس-نيام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بالصلاة في حديث وصلوا بالليل والناس نيام.mp3","categories":["الوتر وقيام الليل","شروح الحديث"]},{"id":4970,"question":"إذا كان الرجل يصلي بأمه ونسائه التراويح في البيت، فهل يقال: أن هذا أفضل من ذهابه إلى المسجد، أم يصلي في المسجد ثم يرجع يصلي بهن؟","title":"حكم صلاة الرجل التراويح بأهل بيته؟","answer":"الجواب: الأمر واسع إن شاء الله.","link":"https://binbaz.org.sa/fatwas/27770/حكم-صلاة-الرجل-التراويح-باهل-بيته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم صلاة الرجل التراويح بأهل بيته؟.mp3","categories":["الوتر وقيام الليل"]},{"id":5266,"question":"هل كان قيام الليل فرضا واجبًا على رسول الله ﷺ؟","title":"هل كان قيام الليل فرضًا على النبي عليه الصلاة والسلام؟","answer":"الجواب: الصواب أنه نافلة قال: فَتَهَجَّدْ بِهِ نَافِلَةً لَكَ [الإسراء:79] لكن أمره أمر استحباب؛ لأن الرسول ﷺ قال: الصلوات الخمس والجمعة هي الفرض، قال لما سأله سائل هل عليَّ غيرها؟ قال: لا، إلا أن تطوع، هو داخل في الخطاب عليه الصلاة والسلام. س: طيب هي مستحبة لنا؟ ج: وله كذلك، كلها متأكدة في حق الجميع. س: كل الشهر أو بعض الأيام؟ ج: كل الشهر.[1]","link":"https://binbaz.org.sa/fatwas/30870/هل-كان-قيام-الليل-فرضا-على-النبي-عليه-الصلاة-والسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/wazayif ramadan 008.mp3","categories":["الوتر وقيام الليل"]},{"id":5267,"question":"ما هي الأسباب المعينة على قيام الليل؟","title":"ما الأسباب التي تعين المرء على قيام الليل؟","answer":"الجواب: عدم السهر، ينام مبكرًا، يعينه الله على قيامه، وإنْ صلى قبل أن ينام من باب الحزم مثلما أوصى رسول الله ﷺ بها أبا هريرة وأبا الدرداء فلا بأس، لكن إذا كان يحب أن يقوم في آخر الليل فليبكِّر لا يسهر، يبكر ويعتني يوقت الساعة، الوقت المطلوب، الساعة من أسباب التيسير، الساعة تيسّرت والحمد لله، يستطيع الإنسان أن يوقّتها على الوقت الذي يريد ثم يقوم لعبادته، الحمد لله.[1]","link":"https://binbaz.org.sa/fatwas/30869/ما-الاسباب-التي-تعين-المرء-على-قيام-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/wazayif ramadan 007.mp3","categories":["الوتر وقيام الليل"]},{"id":5414,"question":"مَن نام عن صلاة الليل؟","title":"حكم القضاء لمَن نام عن صلاة الليل؟","answer":"الجواب: يقضيها في النهار، والأفضل في الضُّحى، وإن قضاها بعد الظهر لا بأس، ولكن إن قضاها قبل الزوال فهذا أحسن؛ لأنَّه في الحديث الصحيح يقول ﷺ: مَن فاته حزبه من الليل فقضاه من النهار قبل صلاة الظهر كان كمَن قرأه في الليل، أو: كُتِبَ له كما قرأه في الليل، فالصَّلوات التي تفوته -مثل حزبه من القرآن- إذا فعلها في الضَّحى يكون أحسن.[1]","link":"https://binbaz.org.sa/fatwas/31183/حكم-القضاء-لمن-نام-عن-صلاة-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 030.mp3","categories":["الوتر وقيام الليل"]},{"id":5539,"question":"قول: \"اللهم اهدني فيمن هديت\" هل قنت ﷺ بهذا القنوت؟","title":"هل ثبت دعاء قنوت الوتر في السُّنة؟","answer":"الجواب: لا، ما قنت، إنما يقنت يدعو على قومٍ، أو لقومٍ، أما هذا: علَّمه النبيُّ ﷺ للحسن في القنوت، ثم كان ﷺ إذا دعا وهو إمام ما يقول بالإفراد، يقول بالجمع، إذا دعا للمسلمين يجمع، وإنما يقول: \"اهدني، واغفر لي\" إذا كان وحده عليه الصلاة والسلام، وإذا كان في صلاته يدعو لنفسه فيما بينه وبين ربه، كما يقول في السجود: اللهم اغفر لي ذنبي كله، دقه وجله، أما الدعاء العام في الخطب والقنوت فهذا يعمّ: \"اللهم اغفر لنا، اللهم ارحمنا، اللهم أنجنا، اللهم انصرنا\"، ونحو ذلك.[1]","link":"https://binbaz.org.sa/fatwas/31472/هل-ثبت-دعاء-قنوت-الوتر-في-السنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/zad almaad 001.mp3","categories":["الوتر وقيام الليل","القنوت في الصلاة"]},{"id":6206,"question":"إذا لم أذكر الوتر إلا بعد يومين، أو ثلاثة، فماذا أفعل فيه؟","title":"كيفية قضاء من نام عن الوتر أو نسيه","answer":"الجواب: إذا نام عن الوتر، أو نسيه؛ شرع له أن يصلي من الضحى ما تيسر، فإذا ذهب الضحى؛ زالت السنة، ولم يبقَ عليه شيء، ولكن يشرع له أن يتعوض عنه بالضحى إذا نسيه بالليل؛ صلى من الضحى ركعات؛ هذه السنة. وإذا فاته  الوتر؛ يسن له أن يصلي في الضحى ما يقابل ذلك، لكن يشفع صلاته، ولا يوتر، قالت عائشة -رضي الله عنها-: كان النبي ﷺ إذا شغله عن وتره نوم، أو مرض؛ صلى من النهار ثنتي عشرة ركعة وكان وتره في الغالب إحدى عشرة ركعة -عليه الصلاة والسلام- فإذا نام عنه، أو شغله عنه مرض؛ صلى من النهار ثنتي عشرة ركعة، يعني ست تسليمات، هذا هو الأفضل. إذا كنت تصلي من الليل خمس ركعات، وفاتك الوتر لنوم، أو مرض، تصل من النهار ست ركعات؛ زيد واحدة، ثلاث تسليمات، وإذا كانت عادتك سبع  ركعات؛ توتر بها، تصلي من النهار ثمان ركعات، أربع تسليمات، وإذا كانت عادتك ثلاث ركعات؛ توتر بها في الليل، ألهيت عنها، أو شغلت عنها بمرض، تصلي من النهار أربع ركعات تسليمتين، ومن زاد؛ فلا بأس، من زاد على هذا؛ فهو خير، وهذا يكون قبل الظهر، فإذا فاته هذا الوقت؛ فالظاهر أنه سنة فات محلها.","link":"https://binbaz.org.sa/fatwas/1643/كيفية-قضاء-من-نام-عن-الوتر-او-نسيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_556.mp3","categories":["الوتر وقيام الليل","قضاء الفوائت"]},{"id":6689,"question":"هل الأفضل أن نصلي صلاة القيام ثمان ركعات، ثم نزيد ثلاثًا، وترًا، أم عشرًا، ثم نزيد ثلاثة؟","title":"ما عدد ركعات صلاة القيام؟","answer":"الجواب: الأفضل إحدى عشر، وإذا صلى ثلاث عشر؛ فلا بأس، فعل النبي هذا وهذا، صلى مرة إحدى عشرة، ومرة صلى ثلاثة عشرة، كان يصلي هذا تارة، وهذا تارة، والأغلب إحدى عشرة، وإذا صلوا عشرين مع الوتر، أو أكثر؛ فلا بأس مثل ما فعل بعض الصحابة، لا حرج في ذلك، الأمر في هذا واسع، النبي -عليه السلام- قال: صلاة الليل مثنى مثنى ولم يحدد بعدد معلوم، فأوتر بسبع، وأوتر بخمس، وأوتر بإحدى عشرة، وأوتر بثلاثة عشرة، وأوتر بتسع، كله وارد بحمد الله، والصحابة صلوا ثلاثًا وعشرين مع عمر -رضي الله عنه وأرضاه- وصلوا ثلاثة عشرة، وصلى أبو بكر، وصلى بعضهم أكثر من ذلك، فلا بأس بهذا. السؤال: يلزم جماعة ضروري يكون في جماعة؟ الجواب: هذا أفضل، وإن صلى في البيت فلا بأس.","link":"https://binbaz.org.sa/fatwas/2551/ما-عدد-ركعات-صلاة-القيام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1046.mp3","categories":["الوتر وقيام الليل"]},{"id":6741,"question":"هل يجوز الجهر بالقراءة في صلاة التهجد، أم لا؟ وهل يجوز القراءة في المصحف في صلاة التهجد، أم لا؟","title":"حكم الجهر والقراءة من المصحف في التهجد","answer":"الجواب: أفضل، الجهر أفضل؛ لأنه ينشط، ويطرد النعاس، ويرغم الشيطان، وينفع المستمع، فالأفضل له الجهر في صلاة التهجد بالليل، هذا هو الأفضل، ولا بأس أن يقرأ في المصحف، إلا إذا كان حوله نيام يشق عليهم؛ خفض صوته حتى لا يشغلهم، وحتى لا يؤذيهم. أما إذا كان ما حوله أحد يتأذى بذلك، فالأفضل الجهر، جهرًا لا يتعبهم، ولا يؤذي أحدًا، وكذلك إذا كان حوله يصلون؛ لا يشغلهم أيضًا، لا يجهر جهرًا، لا يؤذي مصليًا، ولا يؤذي نائمًا، وكذلك لا بأس بالقراءة في المصحف، كان مولى عائشة -رضي الله عنها- يصلي بها من المصحف في رمضان، فالذي ما عنده حفظ، وقرأ من المصحف لتهجده؛ فلا بأس. السؤال: حتى ولو كان إمامًا يا شيخ؟ الجواب: ولو كان إمامًا نعم. السؤال: وصلاة الفريضة؟ الجواب: الفريضة ما هو محتاج للمصحف في الغالب، الحمد لله الفاتحة ميسرة، وما تيسر معها ميسر، لكن الغالب يحتاج إلى هذا في التهجدات، ولو قرأ من المصحف ما في شيء، صحيح، لكن ما له حاجة فيه.","link":"https://binbaz.org.sa/fatwas/2618/حكم-الجهر-والقراءة-من-المصحف-في-التهجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1114.mp3","categories":["الوتر وقيام الليل","القراءة في الصلاة"]},{"id":6748,"question":"هل يجوز ترك سنة الوتر، وقد سمعت بأن الرسول لم يترك الوتر، لا في سفر، ولا حضر، وضح لنا الطريق؟","title":"هل يجوز ترك صلاة الوتر؟","answer":"الجواب: الوتر سنة مؤكدة في الحضر، والسفر، الوتر سنة مؤكدة، أقله ركعة في السفر، والحضر، ولكن لو تركه لا شيء عليه، هو نافلة، تطوع، ليس بواجب، وكان يوتر على بعيره، ولا يصلي الفريضة إلا على الأرض. فالوتر من النوافل، كسنة الظهر، والمغرب، والعشاء، والفجر، وسنة الجمعة، كلها من النوافل، ولما سأله رجل عن الصلاة؛ علمه أنها خمس صلوات، فقال: هل علي غيرها؟ قال: لا، إلا أن تطوع فالذي ... الصلوات الخمس بالرواتب، والوتر صلاة الضحى كلها نوافل، كلها تطوع.","link":"https://binbaz.org.sa/fatwas/2622/هل-يجوز-ترك-صلاة-الوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1118.mp3","categories":["القراءة في الصلاة","الوتر وقيام الليل"]},{"id":6936,"question":"هناك شبهة يروج لها المبتدعة، وهي: ما سنه عمر  من جميع المسلمين في صلاة التراويح على إمام واحد، وصلى بهم إحدى وعشرين ركعة، وقوله : (نعمت البدعة) مع أن السنة عن رسول الله صلاة التراويح إحدى عشرة ركعة، وفي رواية ثلاث عشرة، فكيف يخالف عمر  هدي رسول الله ﷺ ويزيد في صلاة التراويح إحدى وعشرين ركعة؟ وما هو الأولى في ذلك، صلاة التراويح إحدى عشر كهدي الرسول ﷺ أم ثلاث وعشرين، كما بين عمر ؟","title":"الرد على من أنكر صلاة التراويح","answer":"الجواب: هذا لا تعلق للبدعة فيه؛ لأن عمر  إنما أراد بقوله: (نعمت البدعة) يعني من حيث اللغة؛ لأن البدعة من حيث اللغة ما عمل على غير مثال سابق، ما عمله الناس على غير مثال سابق؛ يسمى بدعة في اللغة، وليس مراده أن هذا بدعة في الدين، لو كان في بدعة في الدين ما فعله، هو أبعد الناس عن البدع -رضي الله عنه وارضاه-. وإنما أراد أنه فعله على غير الطريقة التي كان عليها رسول الله ﷺ فإنه كان رسول الله ﷺ يصلي في بيته، وخاف على الناس من الصلاة في المسجد أن تفرض عليهم، صلى بهم النبي ﷺ عدة ليال، ثلاث ليال، ثم تأخر، وقال: إني خشيت أن تفرض عليكم فدل ذلك على أنه إنما تركها؛ خوف الفريضة عليه، فلما توفي النبي ﷺ أمن الناس من الفريضة؛ لأن التشريع انقطع، الوحي انقطع، ما بقي تشريع، فلهذا فعلها عمر  وأمر أُبَيّ أن يصلي بالناس، رضي الله عنهم وأرضاهم جميعًا. فليست بدعة، وإنما هي سنة سنها الرسول ﷺ وفعلها، وفعلها الصحابة في وقته، كانوا يصلون في وقت النبي ﷺ أوزاعًا، كان الرجل وحده يصلي، الرجل بالرجلين، وبالثلاثة أوزاعًا، يعني جماعات في المسجد، فجمعهم عمر على إمام واحد، فهي سنة، وليست بدعة، وإنما أراد من حيث اللغة، سماها بدعة من حيث اللغة .. وأما كونه صلى ثلاثًا وعشرين، فقد ثبت عنه هذا، وهذا، ثبت عنه: صلى إحدى عشرة، وثبت عنه: أنه صلى ثلاثًا وعشرين، والسبب في ذلك أن الإحدى عشر كانوا يطولون فيها، ثم رأى التخفيف بعض الشيء، وأن تكون ثلاثًا وعشرين، وكله سنة، هذا سنة، وهذا سنة، لأن الرسول ﷺ قال: صلاة الليل مثنى مثنى ولم يحدد إحدى عشرة، ولا ثلاث عشرة، ولا أكثر من ذلك قال: صلاة الليل مثنى مثنى، فإذا خشي أحدكم الصبح؛ صلى ركعة واحدة، توتر له ما قد صلى ولم يقل: فإذا زاد على إحدى عشرة؛ فليقف، أو ثلاث عشرة، قال: فإذا خشي الصبح؛ صلى ركعة واحدة، توتر له ما قد صلى. فصلاة الليل موسع فيها، ولهذا كان بعض السلف يصلي أربعين، وبعضهم يصلي أكثر من ذلك، فصلاة الليل فيها سعة، فعمر  لما علم هذا؛ عمر خففها من ثلاث وعشرين إلى إحدى عشرة؛ حتى يتمكن الناس من أدائها بنشاط، من غير تعب، فمن صلاها إحدى عشرة، أو ثلاث عشرة، أو ثلاثًا وعشرين، أو أكثر من ذلك؛ فلا حرج، لكن الأفضل إحدى عشرة، أو ثلاث عشرة. هذا الأفضل كونه يوافق فعل النبي ﷺ هذا هو الأفضل، ولكن ليس بمخالفة ذلك بدعة، ولا إنكار؛ لأن المشروع في صلاة الليل أمر واسع -بحمد الله- وفي النهار كذلك.","link":"https://binbaz.org.sa/fatwas/2866/الرد-على-من-انكر-صلاة-التراويح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1314.mp3","categories":["القراءة في الصلاة","الوتر وقيام الليل"]},{"id":6937,"question":"حديث عائشة: \"لم يزد الرسول في رمضان، ولا غير رمضان على إحدى عشرة ركعة\"؟","title":"ما معنى قول عائشة: «لم يزد الرسول في رمضان ولا في غيره»؟","answer":"الجواب: يعني في الغالب، وإلا فقد ثبت عنه ﷺ أنه صلى ثلاثة عشر ركعة، وثبت عنه أنه أوتر بتسع، وبسبع، وبخمس، نقص عن إحدى عشر. السؤال: لم يزد ... في رمضان، ولا غير رمضان؟ الجواب: المراد أنه في الغالب، هي ممن روت أنه صلى ثلاثة عشر، يعني غالبًا إحدى عشر، وإلا قد يزيد عنها، ويصلي ثلاثة عشر، وقد ينقص، ويصلي تسعًا، وسبعًا، وخمسًا -عليه الصلاة والسلام- وثلاثًا. السؤال: يمكن القيام يصلى ثماني ركعات؟ الجواب: لو صلى ثماني ركعاتٍ، وأوتر في ثلاث، أو صلى عشرًا، وأوتر في ثلاث؛ هذا طيب، أو صلى أقل من ذلك، أو أكثر، الأمر واسع.","link":"https://binbaz.org.sa/fatwas/2867/ما-معنى-قول-عاىشة-لم-يزد-الرسول-في-رمضان-ولا-في-غيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1315.mp3","categories":["الوتر وقيام الليل","شروح الحديث"]},{"id":7028,"question":"هل صلاة الوتر تختلف عن صلاة الليل من حيث وقتها، والدعاء الذي يقال في الصلاتين، وكذلك عدد ركعات الصلاة؟","title":"هل صلاة الوتر تختلف عن صلاة الليل؟","answer":"الجواب:\n\nالوتر من صلاة الليل وهو ختامها، ركعة واحدة، يختم بها صلاة الليل في آخر الليل، أو في وسط الليل، أو في أول الليل، بعد صلاة العشاء يصلي ما تيسر، ثم يختم بواحدة يقرأ فيها: الْحَمْد [الفاتحة:2]، وقُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص:1]، هذا الوتر.\n\nالسؤال: فيها دعاء يا شيخ؟\n\nالجواب: فيها قنوت إذا أراد، يقنت بعد الركوع اللهم اهدني فيمن هديت ... إلى آخره، أو يدعو بغير ذلك لا بأس.","link":"https://binbaz.org.sa/fatwas/3010/هل-صلاة-الوتر-تختلف-عن-صلاة-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1417.mp3","categories":["القراءة في الصلاة","الوتر وقيام الليل"]},{"id":7487,"question":"هذه رسالة وصلت إلى البرنامج من السائل ناصر محمد أبو طالب بشيري يسأل عن صلاة العشاء والتراويح يقول: حضر لصلاة العشاء ووجد الناس يصلون فدخل معهم، ثم تبين أنهم يصلون التراويح، فأكمل معهم ثم صلى العشاء، هل تجوز العشاء بعد التراويح؟ وهل تجوز التراويح قبل العشاء؟","title":"حكم تقديم صلاة التراويح على صلاة العشاء","answer":"الجواب: على كل حال السنة التراويح بعد العشاء، قيام رمضان بعد العشاء؛ لكن هذه نافلة صلاته معهم قبل صلاة العشاء تعتبر صلاة نافلة بين العشاءين، في حقه بين العشاءين، والصلاة بين العشاءين جائزة لكن ليست هي القيام المعروف؛ قيام رمضان، قيام رمضان يكون بعد العشاء، فتعتبر هذه نافلة له بين العشاءين وصلاته بعد ذلك صحيحة، صلاة العشاء، صلاته صحيحة، وإنما الأفضل والأولى أنه بدأ بالفريضة، بدأ بها ثم صلى معهم التراويح، هذا الذي ينبغي حتى يجتمع له فعل السنة مع أداء الفريضة، ولو أنه صلى معهم بنية الفريضة، فلما سلم من التراويح قام وتمم الفريضة أجزأه ذلك، لو صلى معهم الثنتين؛ الأولى مع الإمام بنية التراويح وهو يصلي الفريضة، ثم إذا سلم قام فتمم صلاته أجزأه ذلك.\nفالحاصل: أن هذا لا حرج فيه إن شاء الله، صلاته صحيحة، وصلاته التراويح صحيحة وتعتبر نافلة، ليست هي التراويح وليست هي قيام رمضان المشهور، إنما قيام رمضان يكون بعد العشاء، وهذا صلاها قبل العشاء، فتكون من النوافل التي تستحب بين المغرب والعشاء. نعم.","link":"https://binbaz.org.sa/fatwas/4332/حكم-تقديم-صلاة-التراويح-على-صلاة-العشاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_005/00506.mp3","categories":["الوتر وقيام الليل"]},{"id":7499,"question":"هذه رسالة من عدنان السيد صالح، محافظة عدن، جمهورية اليمن الديمقراطية الشعبية، يسأل في أول رسالته عن العنوان للبرنامج التي تصل له الرسائل بسرعة، نقول للأخ/ عدنان السيد صالح ، ونقول أيضاً للمستمعين الكرام: إن عنوان برنامج نور على الدرب هو إذاعة المملكة العربية السعودية. الرياض.أما سؤاله فيقول: عرفنا من برنامجكم نور على الدرب أن صلاة التراويح سنة، لكن هل يلزم المسلم إذا شرع فيها أن يكملها، أو يصلي ما شاء ثم ينصرف؟","title":"أفضلية إكمال صلاة التراويح مع الإمام حتى ينصرف","answer":"الجواب: لا شك أنها سنة وأنها نافلة، التراويح، يعني: قيام رمضان، وهكذا صلاة الليل، وهكذا صلاة الضحى، وهكذا الرواتب التي مع الفرائض، كلها سنة كلها نافلة، إن شاء فعلها وإن شاء تركها، وفعلها أفضل، وإن شرع مع الإمام في التراويح وأحب أن ينفتل منها قبل أن يكبر فلا بأس عليه، لكن بقاؤه مع الإمام حتى ينصرف أفضل، ويكتب له بهذا قيام الليلة، لقول النبي ﷺ: من قام مع الإمام حتى ينصرف كتب الله له قيام ليلة فإذا بقي مع الإمام حتى يكمل كان له فضل قيام الليلة كلها، وإن انصرف بعدما يصلي بعض الركعات فلا بأس، لا حرج في ذلك؛ لأنها نافلة.","link":"https://binbaz.org.sa/fatwas/4460/افضلية-اكمال-صلاة-التراويح-مع-الامام-حتى-ينصرف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_007/00704.mp3","categories":["الوتر وقيام الليل"]},{"id":7709,"question":"وردتنا هذه الرسالة من المرسل فهمي عبد الرحمن أحمد يسأل عن الصلاة في عدة أسئلة، يقول: السؤال الأول: أديت صلاة العشاء وكذلك الوتر ثم نمت، وقمت بعد منتصف الليل، فهل تجوز الصلاة، أي التي هي قيام الليل بعد الوتر؟","title":"حكم الصلاة بعد الوتر","answer":"الجواب: السنة للمؤمن أن يتحرى الوقت الذي يستطيعه للتهجد بالليل، فإن كان يستطيع القيام إلى آخر الليل أخر تهجده إلى آخر الليل؛ لأن هذا أفضل، وقت التنزل الإلهي الذي جاء فيه الحديث الصحيح المستفيض عن رسول الله عليه الصلاة والسلام أنه قال: ينزل ربنا إلى سماء الدنيا كل ليلة حين يبقى ثلث الآخر، فيقول: من يدعوني فأستجيب له؟ من يسألني فأعطيه؟ من يستغفرني فأغفر له، حتى ينفجر الفجر. فهذا الوقت وقت عظيم في نزول الرب عز وجل نزول يليق بجلاله سبحانه وتعالى، وفيه أنه يقول: هل من داع فيستجاب له؟ هل من سائل فيعطى سؤله ؟ هل من مستغفر فيغفر له؟ وفي رواية ثانية: هل من تائب فيتاب عليه؟ هذا فضل عظيم، ينبغي تحري هذا الوقت الذي هو آخر الليل.. الثلث الأخير؛ لهذا الحديث الصحيح في النزول، وهذا النزول وصف لربنا عز وجل كما يليق به سبحانه وتعالى لا يكيف ولا يمثل، بل يقال في هذا: نزول يليق بجلاله لا يشابهه في خلقه سبحانه وتعالى كسائر الصفات، كما نقول: استوى على العرش استواء يليق بجلاله، لا أشبهه بخلقه سبحانه وتعالى، وكما نقول: إن علمه يليق بجلاله، ورحمته وهكذا وجهه وهكذا يده وهكذا سائر الصفات، كلها حق، وكلها ثابتة لله سبحانه وتعالى على الوجه اللائق بالله جل وعلا، كما قال سبحانه: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11] أثبت لنفسه السمع والبصر ونفى عن نفسه المماثلة سبحانه وتعالى، وهذا هو الحق الذي درج عليه أهل السنة والجماعة ، وذلك هو إثبات جميع الصفات والأسماء الواردة في الكتاب العزيز أو في السنة الصحيحة المطهرة عن رسول الله عليه الصلاة والسلام، نثبتها إثباتاً بلا تمثيل، وننزهها عن التعطيل، فنقول: إنه يجب إثبات صفات الرب وأسمائه من النزول والاستواء والرحمة والغضب والوجه واليد والأصابع وغير ذلك، نثبتها لله كما جاءت في النصوص إثباتاً بلا تمثيل وننزه صفاته عن مشابهة خلقه تنزيهاً بريئاً من التعطيل، هكذا يقول أهل السنة والجماعة ، فالنزول من ذلك الباب، نزول الرب في آخر الليل من هذا الباب، نثبته لله على الوجه اللائق بالله سبحانه وتعالى مع الإيمان بعلوه فوق العرش وأنه فوق العرش جل وعلا، فإن صفاته لا تساوي صفات خلقه، فلا يتنافى النزول في حقه مع علوه فوق العرش سبحانه وتعالى، لا يتنافى هذا وهذا في حقه عز وجل، فإنه نزول لا يعلم كنهه وكيفيته إلا هو سبحانه وتعالى، فهو نزول يليق بالله فيه هذا الخير العظيم، فيه أنه  يقول: هل من تائب فيتاب عليه؟ هل من سائل فيعطى سؤله؟ هل من مستغفر فيغفر له؟. هذا فضل عظيم ينبغي في هذا الوقت الإكثار من الدعاء في آخر الليل مع الصلاة مع القراءة، هكذا أرشد النبي عليه الصلاة والسلام، أما إن كان لا يستطيع ذلك ويخشى أنه ينام فإنه يوتر في أول الليل، يصلي ما تيسر في أول الليل، يوتر بثلاث.. بخمس.. بسبع.. بأكثر أو بالواحدة على الأقل، لا بأس، يكفيه واحدة بعد سنة العشاء، إذا صلى العشاء وصلى راتبتها ثنتين وأوتر بواحدة كفى، وإن أوتر بثلاث فهو أفضل، وإن أوتر بأكثر فهو أفضل، ثم إذا قام من آخر الليل أو في أثناء الليل وأحب أن يتهجد فلا بأس، إذا قام من آخر الليل وأحب أن يصلي ركعتين أو أربع ركعات أو أكثر بلا وتر فلا بأس، الوتر لا يعيده، النبي عليه السلام قال: لا وتران في ليلة لكن يصلي ما تيسر في أثناء الليل أو في آخر الليل شفعًا، ثنتين، أربع، ست، ثمان، من دون وتر، الوتر الأول يكفيه، وقد ثبت عنه ﷺأنه كان يصلي بعض الأحيان ركعتين بعد الوتر وهو جالس، وهذا والله أعلم ليبين للناس أن الصلاة بعد الوتر جائزة غير محرمة، وإنما الأفضل أن يكون الوتر هو آخر الصلاة، أن يختم صلاته بالوتر، لقوله عليه الصلاة والسلام: اجعلوا آخر صلاتكم بالليل وتراً، فالأفضل أن يختم بالوتر، لكن لو قدر أنه أوتر ثم تيسر له نشاط وقام في آخر الليل فلا بأس في ذلك، يصلي ما تيسر ركعتين أو أربع ركعات، فلا حرج في ذلك والحمد لله. نعم.","link":"https://binbaz.org.sa/fatwas/4908/حكم-الصلاة-بعد-الوتر ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_030/03003.mp3","categories":["الوتر وقيام الليل"]},{"id":7780,"question":"سؤاله الرابع يقول: ما هي صلاة الوتر، ومتى وقتها، وكم ركعة، وكيف أداؤها؟","title":"ما صفة صلاة الوتر ووقتها وعدد ركعاتها؟","answer":"الجواب: صلاة الوتر سنة قربة متأكدة، تبدأ بعد صلاة العشاء وتنتهي بطلوع الفجر هذه صلاة الوتر، تبدأ بعد صلاة العشاء وتنتهي بطلوع الفجر، وأقلها ركعة واحدة، هذا أقلها، وأفضلها إحدى عشرة ركعة أو ثلاثة عشرة ركعة لفعل النبي ﷺ، وإن زاد على ذلك فأوتر بخمس عشرة أو بعشرين مع الوتر أو ما أشبه ذلك فلا بأس فلا حرج؛ لأن النبي ﷺ قال: صلاة الليل مثنى مثنى، فإذا خشي أحدكم الصبح صلى ركعة واحدة توتر له ما قد صلى ولم يحد حداً، فدل ذلك على أنه إذا أوتر بخمس أو سبع أو تسع أو إحدى عشرة أو ثلاث عشرة أو خمس عشرة أو سبع عشرة أو تسع عشرة أو إحدى وعشرين أو ثلاث وعشرين كله طيب، أو أكثر من ذلك، أو أوتر بواحدة فقط أجزأه ذلك، وهذا واضح من السنة عن النبي عليه الصلاة والسلام. نعم.\nالمقدم: يقول أيضاً: ما دخلها في الشفع؟\nالشيخ: الشفع تارة يكون منفصلاً عنها وهو أفضل، وتارة يكون وتراً متصلاً، خمساً جميعاً، سبعاً جميعاً، تسعاً جميعاً، لا بأس، فعله النبي ﷺ، لكن إذا صلى سبعاً جميعاً يجلس في السادسة، يتشهد التشهد الأول ثم يقوم ويأتي بالسابعة، وإذا صلى تسعاً جميعاً فالسنة أن يجلس في الثامنة ويتشهد التشهد الأول ثم يقوم ثم يأتي بالتاسعة، والأفضل أن يسلم من كل ركعتين، هذا هو الأفضل لقول النبي ﷺ: صلاة الليل مثنى مثنى هذا هو الأفضل، وإذا سرد خمساً جميعاً وأوتر بها أو ثلاثاً جميعاً وأوتر بها؛ سردها سرداً من غير جلوس، ثلاثاً جميعاً من دون جلوس في الثانية أو خمساً جميعاً بدون جلوس فيها كلها إلا في الأخيرة، هذا هو الأفضل، وأما في السبع والتسع فيجلس في السادسة في السبع، وفي الثامنة في التسع للتشهد الأول، ثم يقوم ويأتي بالسابعة ويأتي بالتاسعة، ولكن الأفضل مثلما تقدم أن يسلم من كل ثنتين ثم يوتر بواحدة، سواء صلى سبعاً أو خمساً أو ثلاثاً أو تسعاً أو إحدى عشرة أو ثلاث عشرة أو أكثر من ذلك، نعم، والأمر في هذا واسع بحمد لله، ليس فيه يعني حرج.\nالمقدم: أحسنتم.","link":"https://binbaz.org.sa/fatwas/5129/ما-صفة-صلاة-الوتر-ووقتها-وعدد-ركعاتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_048/04808.mp3","categories":["الوتر وقيام الليل"]},{"id":7861,"question":"أيضاً يقول في رسالته: هل من لوازم صلاة الوتر القنوت وهل ورد عنه ﷺ أنه صلى الوتر بدون قنوت؟","title":"هل يلزم القنوت في صلاة الوتر؟","answer":"الجواب: ليس من اللوازم القنوت، مستحب القنوت، الوتر مستحب والقنوت مستحب، قد علمه النبي ﷺ الحسن بن علي فهو مستحب وليس بفرض، ولا نعلم أنه ﷺ داوم على القنوت كما أننا لا نعلم أنه تركه تارة وفعله تارة، لكن فعله الصحابة تارة وتركوه تارة، أبي بن كعب لما أم الناس في عهد عمر كان يتركه تارة ويقنت تارة، فلا حرج في تركه؛ لأنه نافلة، إذا تركه بعض الأحيان فلا بأس. نعم.","link":"https://binbaz.org.sa/fatwas/5273/هل-يلزم-القنوت-في-صلاة-الوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_056/05601.mp3","categories":["قضايا المرأة","الوتر وقيام الليل","القنوت في الصلاة"]},{"id":8055,"question":"من سعد سعود بن سليمان بالرياض وردتنا هذه الرسالة حول السنة التي تأتي بعد صلاة العشاء، يقول: إذا صليت بعد صلاة العشاء الراتبة، ثم قمت فصليت الشفع، ثم أتيت بالوتر بعدها ولم أجلس للتشهد، فهل ذلك جائز أم لا؟الشيخ: كأنه يريد أنه صلى الشفع والوتر جميعاً؟المقدم: نعم نعم.الشيخ: يعني سرد الثلاث؟المقدم: نعم.","title":"حكم سرد صلاة الليل مع الوتر دون فصل بينهما","answer":"الجواب: إذا صلى الإنسان راتبة العشاء، ثم قام فصلى ثلاثاً جميعاً سردها سرداً ولم يجلس فلا بأس، قد جاء عن النبي ﷺ أنه فعل هذا في بعض الأحيان، أوتر بثلاث لم يسلم إلا في آخرهن عليه الصلاة والسلام، فهذا نوع من السنة ولا حرج في ذلك، لكن يكره أن يجلس في الثانية ويأتيها ثم يقوم من دون سلام كالمغرب، لا، هذا يكره، بل إما أن يسلم من الثنتين وهو أفضل، ثم يأتي بواحدة وحدها مفردة هذا هو الأفضل، وهو الأكثر من فعل النبي ﷺ ، وإن سردها من دون جلوس في الثانية، سردها سرداً ثم سلم في الثالثة فلا بأس بذلك، قد فعله النبي ﷺ ، لكن الأحاديث الصحيحة الكثيرة فيها أنه كان يسلم من الثنتين، ثم يقوم فيأتي بركعة الوتر وحدها، هذا هو الأفضل، وهذا هو الأغلب من فعل النبي عليه الصلاة والسلام. نعم.\nالمقدم: لكن سماحة الشيخ لو نسي وقام في الثانية أو بعد الثانية، هل يسجد للسهو أو ...... ؟\nالشيخ: هو كان ناوي؟\nالملقي: نعم هو يريد أن يأتي بالوتر .....\nالشيخ: إذا نوى الجلوس في الثنتين ثم سها وقام، فالأفضل أن يرجع، الأفضل يرجع ويجلس ويكمل ويسجد للسهو، ثم يأتي الواحدة وحدها، ركعة الوتر وحدها؛ لأن الرسول عليه الصلاة والسلام قال: صلاة الليل مثنى مثنى، فإذا كان ما نوى سرد الثلاث، فإنه إذا قام يجلس، يجلس ويتشهد ويكمل تشهده ويدعو دعاءه، ثم يسجد سجدتين للسهو، ثم يسلم ثم يقوم فيأتي بواحدة، التي هي الوتر.\nأما إذا نوى الثلاث يسردها سرداً فلا حرج عليه، فقد ثبت عنه ﷺ أنه سرد ثلاثاً جميعاً، وسرد خمساً جميعاً، لم يجلس إلا في آخرها عليه الصلاة والسلام، وثبت عنه أنه سرد سبعاً جميعاً وجلس في السادسة وتشهد ثم قام ولم يسلم، ثم أتى بالسابعة وتشهد وسلم، وثبت عنه أنه صلى تسعاً جميعاً، وجلس في الثامنة وتشهد ولم يسلم، ثم قام وأتى بالتاسعة، هذا كله ثابت من فعله صلى الله عليه وسلم، لكن الأفضل والأغلب والأكثر من فعله ﷺ ، هو أنه يسلم من كل ثنتين، كما قال عليه الصلاة والسلام: صلاة الليل مثنى مثنى، وقالت عائشة رضي الله عنها: كان النبي ﷺ يصلي من الليل إحدى عشرة ركعة، يسلم من كل ثنتين، ثم يوتر بواحدة عليه الصلاة والسلام، هذا هو الأفضل وهذا هو الأكثر من فعل النبي صلى الله عليه وسلم، ولكن من سرد ثلاثاً ولم يجلس إلا في الثالثة، أو خمساً ولم يجلس إلا في الخامسة فلا حرج عليه؛ لأن الرسول فعل هذا في بعض الأحيان عليه الصلاة والسلام، وهكذا لو سرد سبعاً وجلس في السادسة وتشهد ولم يسلم ثم قام للسابعة، أو سرد تسعاً وجلس في الثامنة وتشهد ولم يسلم، ثم قام فأتى بالتاسعة فهذا أيضاً لا بأس به، كلاهما صح عن النبي صلى الله عليه وسلم، فلا حرج في ذلك.\nالمقدم: أثابكم الله!","link":"https://binbaz.org.sa/fatwas/5855/حكم-سرد-صلاة-الليل-مع-الوتر-دون-فصل-بينهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_082/08209.mp3","categories":["الوتر وقيام الليل"]},{"id":8056,"question":"هذه رسالة وردتنا من ندى عبد الجليل أمي تقول في الرسالة: والدتي تصلي العشاء مع الوتر، ثم تنام وتصلي صلاة قبل صلاة الفجر، وكثير من الناس يقولون لها: لا يجوز أن تصلي الوتر ما دام لك صلاة قبل صلاة الفجر، أفيدونا وفقكم الله؟","title":"حكم صلاة الوتر في أول الليل والصلاة بعده","answer":"الجواب: الأفضل أنها تؤخر الوتر إلى آخر الليل ما دامت تقوم آخر الليل فالأفضل أن وترها يكون آخر الليل، بعد ما تصلي الصلاة التي يكتب الله لها؛ لقول النبي ﷺ: اجعلوا آخر صلاتكم من الليل وتراً، هذا هو الأفضل، أن الصلاة تكون في آخر الليل، وتختم بالوتر إذا تيسر ذلك.\nأما إن كانت تخشى أن لا تقوم في آخر الليل، وتريد أن تعمل بالاحتياط، فتوتر في أول الليل فلا بأس، النبي ﷺ أوصى أبا هريرة ، وأوصى أبا الدرداء بالإيتار أول الليل، قال بعض أهل العلم: لأنهما كانا يدرسان الحديث، ويخشيان أن لا يقوما في آخر الليل، فلهذا أوصاهما بالوتر في أول الليل.\nوصح عنه عليه الصلاة والسلام أنه قال: من خاف أن لا يقوم من آخر الليل فليوتر أوله، ومن طمع أن يقوم آخر الليل فليوتر آخر الليل، فإن صلاة آخر الليل مشهودة وذلك أفضل، خرجه مسلم في الصحيح.\nفهذا هو التفصيل، إن كانت المرأة تستطيع أن تقوم آخر الليل، فالأفضل أن يكون وترها آخر الليل، بعد ما تصلي ما كتب الله لها، ثم توتر قبل الفجر، هذا هو الأفضل، لكن إن كانت تخشى أن لا تقوم ولا تفق، فالأفضل لها أن توتر في أول الليل، وإذا قامت آخر الليل ويسر الله لها القيام تصلي ما تيسر ركعتين، أو أربع ركعات، أو ست ركعات، من دون وتر الوتر الأول يكفي، ولا تعيد الوتر؛ لأن النبي عليه السلام قال: لا وتران في ليلة، فإذا الإنسان أوتر في أول الليل ثم يسر الله له القيام في آخر الليل فإنه لا يعيد الوتر، بل يكفيه الوتر الأول، ويصلي من آخر الليل ما تيسر، ركعتين، أو أربع ركعات، أو أكثر من ذلك بدون وتر. نعم.","link":"https://binbaz.org.sa/fatwas/5850/حكم-صلاة-الوتر-في-اول-الليل-والصلاة-بعده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_082/08203.mp3","categories":["الوتر وقيام الليل"]},{"id":8059,"question":"هذه رسالة وردتنا من ندى عبد الجليل أمي تقول في الرسالة: والدتي تصلي العشاء مع الوتر، ثم تنام وتصلي صلاة قبل صلاة الفجر، وكثير من الناس يقولون لها: لا يجوز أن تصلي الوتر ما دام لك صلاة قبل صلاة الفجر، أفيدونا وفقكم الله؟","title":"حكم صلاة الوتر في أول الليل والصلاة بعده","answer":"الجواب: الأفضل أنها تؤخر الوتر إلى آخر الليل ما دامت تقوم آخر الليل فالأفضل أن وترها يكون آخر الليل، بعد ما تصلي الصلاة التي يكتب الله لها؛ لقول النبي ﷺ: اجعلوا آخر صلاتكم من الليل وتراً، هذا هو الأفضل، أن الصلاة تكون في آخر الليل، وتختم بالوتر إذا تيسر ذلك.\nأما إن كانت تخشى أن لا تقوم في آخر الليل، وتريد أن تعمل بالاحتياط، فتوتر في أول الليل فلا بأس، النبي ﷺ أوصى أبا هريرة ، وأوصى أبا الدرداء بالإيتار أول الليل، قال بعض أهل العلم: لأنهما كانا يدرسان الحديث، ويخشيان أن لا يقوما في آخر الليل، فلهذا أوصاهما بالوتر في أول الليل.\nوصح عنه عليه الصلاة والسلام أنه قال: من خاف أن لا يقوم من آخر الليل فليوتر أوله، ومن طمع أن يقوم آخر الليل فليوتر آخر الليل، فإن صلاة آخر الليل مشهودة وذلك أفضل، خرجه مسلم في الصحيح.\nفهذا هو التفصيل، إن كانت المرأة تستطيع أن تقوم آخر الليل، فالأفضل أن يكون وترها آخر الليل، بعد ما تصلي ما كتب الله لها، ثم توتر قبل الفجر، هذا هو الأفضل، لكن إن كانت تخشى أن لا تقوم ولا تفق، فالأفضل لها أن توتر في أول الليل، وإذا قامت آخر الليل ويسر الله لها القيام تصلي ما تيسر ركعتين، أو أربع ركعات، أو ست ركعات، من دون وتر الوتر الأول يكفي، ولا تعيد الوتر؛ لأن النبي عليه السلام قال: لا وتران في ليلة، فإذا الإنسان أوتر في أول الليل ثم يسر الله له القيام في آخر الليل فإنه لا يعيد الوتر، بل يكفيه الوتر الأول، ويصلي من آخر الليل ما تيسر، ركعتين، أو أربع ركعات، أو أكثر من ذلك بدون وتر. نعم.","link":"https://binbaz.org.sa/fatwas/5850/حكم-صلاة-الوتر-في-اول-الليل-والصلاة-بعده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_082/08203.mp3","categories":["الوتر وقيام الليل"]},{"id":8072,"question":"هذه رسالة وردتنا من المستمع من الرياض (أ. ع. م. م) يقول: سؤالي عن صلاة الوتر إذا صليت الوتر بعد العشاء قبل أن أنام، خوفاً من عدم القيام آخر الليل ثم قمت آخر الليل وأردت أن أصلي من آخر الليل، فهل يجوز ذلك وأوتر في الأخير أم لا؟","title":"حكم من أوتر أول الليل وأراد التهجد آخره","answer":"الجواب: إذا أوتر الإنسان من أول الليل احتياطاً فهذا حق طيب، النبي ﷺ أوصى أبا الدرداء و أبا هريرة بالإيتار أول الليل، قال بعض أهل العلم: إنما أوصاهما بذلك؛ لأنهما يشتغلان بالعلم في أول الليل، ويصعب عليهما القيام في آخر الليل، فإذا أوتر الإنسان من أول الليل ثم يسر الله له القيام في آخر الليل فإنه يصلي ما تيسر من الركعات من دون وتر، يكتفي بالوتر الأول؛ لأن النبي عليه الصلاة والسلام قال: لا وتران في ليلة فيصلى ركعتين، أو أربع كعات، أو ست ركعات، أو أكثر من دون وتر في آخر الليل، ولا حرج في ذلك ولا بأس بذلك، وإنما يؤمر بتأخير الوتر في آخر الليل إذا كان لا يوتر في أول الليل، ويتيسر له القيام في آخر الليل، فهذا يوصى بأن يكون وتره في آخر الليل إذا تيسر له ذلك؛ لأن آخر الليل أفضل، فإذا يسر الله للعبد أن يوتر في آخر الليل فهذا أفضل، أما إذا خاف وخشي أن لا يقوم من آخر الليل، فإنه يأخذ بالحزم فيوتر بأول الليل، وإذا رزقه الله القيام في آخر الليل صلى ما تيسر من دون وتر، كما جاء في السنة عن الرسول عليه الصلاة والسلام، فقد ثبت عن عائشة رضي الله عنها: أن النبي ﷺ صلى بعد الوتر ركعتين ليبين للناس أن الصلاة بعد الوتر جائزة، ولا حرج فيها. نعم.","link":"https://binbaz.org.sa/fatwas/5873/حكم-من-اوتر-اول-الليل-واراد-التهجد-اخره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_084/08408.mp3","categories":["الوتر وقيام الليل"]},{"id":8076,"question":"هذه رسالة وردتنا من المستمع من الرياض (أ. ع. م. م) يقول: سؤالي عن صلاة الوتر إذا صليت الوتر بعد العشاء قبل أن أنام، خوفاً من عدم القيام آخر الليل ثم قمت آخر الليل وأردت أن أصلي من آخر الليل، فهل يجوز ذلك وأوتر في الأخير أم لا؟","title":"حكم من أوتر أول الليل وأراد التهجد آخره","answer":"الجواب: إذا أوتر الإنسان من أول الليل احتياطاً فهذا حق طيب، النبي ﷺ أوصى أبا الدرداء و أبا هريرة بالإيتار أول الليل، قال بعض أهل العلم: إنما أوصاهما بذلك؛ لأنهما يشتغلان بالعلم في أول الليل، ويصعب عليهما القيام في آخر الليل، فإذا أوتر الإنسان من أول الليل ثم يسر الله له القيام في آخر الليل فإنه يصلي ما تيسر من الركعات من دون وتر، يكتفي بالوتر الأول؛ لأن النبي عليه الصلاة والسلام قال: لا وتران في ليلة فيصلى ركعتين، أو أربع كعات، أو ست ركعات، أو أكثر من دون وتر في آخر الليل، ولا حرج في ذلك ولا بأس بذلك، وإنما يؤمر بتأخير الوتر في آخر الليل إذا كان لا يوتر في أول الليل، ويتيسر له القيام في آخر الليل، فهذا يوصى بأن يكون وتره في آخر الليل إذا تيسر له ذلك؛ لأن آخر الليل أفضل، فإذا يسر الله للعبد أن يوتر في آخر الليل فهذا أفضل، أما إذا خاف وخشي أن لا يقوم من آخر الليل، فإنه يأخذ بالحزم فيوتر بأول الليل، وإذا رزقه الله القيام في آخر الليل صلى ما تيسر من دون وتر، كما جاء في السنة عن الرسول عليه الصلاة والسلام، فقد ثبت عن عائشة رضي الله عنها: أن النبي ﷺ صلى بعد الوتر ركعتين ليبين للناس أن الصلاة بعد الوتر جائزة، ولا حرج فيها. نعم.","link":"https://binbaz.org.sa/fatwas/5873/حكم-من-اوتر-اول-الليل-واراد-التهجد-اخره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_084/08408.mp3","categories":["الوتر وقيام الليل"]},{"id":8078,"question":"يقول: نرى كثيرا من أهل الخير ومن محبيه ومن الفضلاء، الذين يصلون التراويح في رمضان مع الجماعة، إذا جاءت الشفع والوتر تركوا أمكنتهم وانصرفوا إلى منازلهم، يقول: إذا كان المسلم يصلي مع الجماعة في رمضان صلاة التراويح، وكانت صلاة في آخر الليل، فأيهما أحسن وأولى يوتر مع الجماعة ويشفع وتره، أم يترك الشفع والوتر مع الجماعة ويوتر آخر الليل؟","title":"صلاة الوتر مع الإمام أفضل أم صلاته آخر الليل؟","answer":"الجواب: الأفضل أنه يكمل مع الإمام كما شرع الله؛ لأن النبي عليه السلام قال: إن الرجل إذا قام مع الإمام حتى ينصرف كتب الله له بقية ليلته.\nوذلك لما صلى بالصحابة في بعض الليالي إلى ثلث الليل، وفي بعضها إلى نصف الليل قالوا: يا رسول الله! لو نفلتنا بقية ليلتنا قال: إن الرجل إذا قام مع الإمام حتى ينصرف كتب الله له بقية ليلته هذا هو الأفضل أنه يستمر مع الإمام حتى يوتر، ثم إذا صلى في آخر الليل يكفيه الوتر الأول، لا حاجة لوتر، ثاني والحمد لله، يوتر مع الإمام، ويصلي ما تيسر في آخر الليل شفعاً من دون وتر. نعم. كما تقدم في السؤال الأول. نعم.\nالمقدم: لو أوتر مع الإمام ثم شفع وتره وأوتر آخر الليل..\nالشيخ: إن شفع فلا بأس، إن شفع ... سلم الإمام قام وأتى بركعة وشفع ثم جعل الوتر آخر الليل لا بأس، لكن هذا قد يثقل على النفوس، وقد يعني يخشى صاحبه أن يعد بهذا مرائياً، فالحاصل أنه إذا اكتفى بالوتر الحمد لله يكفي، وإن شفعه فلا حرج، إن شفعه وأوتر في آخر الليل فلا حرج، وإن اكتفى بالوتر ثم صلى في آخر الليل ما تيسر من ركعتين أو أربع أو ست أو ثمان، أو أشبه ذلك فلا حرج ولا حاجة إلى وتر يكفيه الوتر الأول. نعم.","link":"https://binbaz.org.sa/fatwas/5874/صلاة-الوتر-مع-الامام-افضل-ام-صلاته-اخر-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_084/08409.mp3","categories":["الوتر وقيام الليل"]},{"id":8092,"question":"أيضاً يقول في رسالته: حضرة المشايخ أنا أصلي بعد صلاة العشاء أحد عشرة ركعة وأوتر، وأعجز بعض الأيام لأنني أشتغل كل اليوم، وأصليها في الثلث الأخير، وإذا غلب علي النوم لم أستيقظ صليتها في النهار، هل تصح أفيدوني جزاكم الله عني خير الجزاء؟","title":"كيفية صلاة الوتر في النهار لمن نام عنه","answer":"الجواب: هذا عمل طيب، وهذا موافق للسنة؛ لأن الرسول ﷺ كان في الغالب يوتر بإحدى عشرة ركعة وربما أوتر في أول الليل، ثم أوتر في وسطه، ثم أوتر في آخره، ثم انتهى أخيراً إلى آخر الليل عليه الصلاة والسلام، فكان الغالب عليه أنه يصلي في آخر الليل عليه الصلاة والسلام، هذا الذي فعلته هو السنة، وإذا نمت عنها فلا حرج، إذا نمت عنها بعض الأحيان أو ثقلت عنها، أو لم يتيسر لك أداؤها، فافعلها في النهار، صل من النهار ما تيسر، لكن من غير إيتار، تصليها شفعاً: تصلي مثلاً ثنتي عشرة ركعة. يعني: ست تسليمات بدل إحدى عشرة ركعة، إذا تيسر ذلك، وإن صليت أقل من ذلك كثمان، أو ست ركعات، أو أربع ركعات كله طيب، لكن الأفضل أن تصلي بعدد ما كنت تفعله في الليل وتزيد ركعة، تزيد ركعة حتى لا توتر بواحدة في النهار، أو تصلي شفعاً، وكان النبي ﷺ إذا فاته ورده من الليل لمرض أو نوم، صلى من النهار ثنتي عشرة ركعة، كما قالته عائشة رضي الله عنها، هذا هو السنة، الذي يفوته ورده من الليل لنوم أو مرض أو نحو ذلك، فإنه يصلي من النهار لكن يكون شفعاً لا وتراً، وأنت بحمد الله قد وفقت للسنة، ولو أوتر الإنسان بأقل من ذلك، أو أوتر بواحدة أو بثلاث أو بخمس فكله سنة والحمد لله، أقله واحدة، إذا صلاها بعد العشاء أو صلاها في آخر الليل فقد فعل السنة. نعم.","link":"https://binbaz.org.sa/fatwas/5890/كيفية-صلاة-الوتر-في-النهار-لمن-نام-عنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_086/08606.mp3","categories":["الوتر وقيام الليل"]},{"id":8096,"question":"هذه رسالة وردتنا من محمد صالح محمد من الدمام يقول: ما حكم قراءة دعاء القنوت في كل ليلة في بعد الوتر؟","title":"حكم المداومة على دعاء القنوت في الوتر","answer":"الجواب: لا حرج في ذلك، دعاء القنوت سنة، كان النبي ﷺ يقنت، وقد علم الحسن كلمات القنوت في الوتر فهو سنة، فإذا قرأت في كل ليلة فلا بأس، وإن تركه بعض الأحيان حتى يعلم الناس أنه ليس بواجب، فهذا لا بأس به، إذا ترك الإمام القنوت بعض الأحيان، ليعلم الجماعة أنه ليس بواجب فهذا لا بأس، وإذا استمر فلا بأس، النبي ﷺ لما علم الحسن القنوت ما قال له: دعه في بعض الأيام، فدل ذلك على أنه إذا استمر فلا حرج. نعم.\nالمقدم: شكراً أثابكم الله.","link":"https://binbaz.org.sa/fatwas/5894/حكم-المداومة-على-دعاء-القنوت-في-الوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_086/08609.mp3","categories":["القنوت في الصلاة","الوتر وقيام الليل"]},{"id":8125,"question":"يقول: أصلي أحد عشر ركعة كل ليلة، وأجهر بالقراءة، وأصلي من غير نذر لهذه الصلاة، وأدعو في الصلاة الأخيرة -أي الوتر- وابتدأ فيها من الساعة العاشرة، فهل صلاتي هذه صحيحة أم لا؟","title":"السنة في صلاة الوتر","answer":"الجواب: هذا هو الأفضل هذا وتر السنة إحدى عشر ركعة، هذا أفضل ما يكون إحدى عشر أو ثلاثة عشر، هذا فعل النبي عليه الصلاة والسلام، وهذا تهجد حسن ووتر حسن، إذا فعلته هذا من السنة، وأنت مأجور على هذا إن شاء الله، ولا حرج في ذلك، ولكن ليس بلازم بل مستحب، ليس بلازم لو أوترت في بعض الليالي بخمس، أو بسبع أو بثلاث فلا حرج في ذلك. نعم.\nالمقدم: شكراً لفضيلة الشيخ عبد العزيز بن عبد الله بن باز .","link":"https://binbaz.org.sa/fatwas/5926/السنة-في-صلاة-الوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_087/08712.mp3","categories":["الوتر وقيام الليل"]},{"id":8211,"question":"سؤاله الثالث: أصلي بجماعة وهم يصرون على قراءة دعاء القنوت في الركعة الأخيرة من صلاة الصبح، إلا أن يقيني في هذا الدعاء وحسب علمي من بعض المصادر الصحيحة أن الرسول ﷺ كان يقرأه في الركعة الأخيرة من صلاة الصبح عند الابتلاءات فقط، فهل أعمل برأيهم وأخالف السنة، أم أعمل برأيي فأصيب السنة، أم أتنازل عن الإمامة تفادياً للخلاف، أفيدونا أفادكم الله؟","title":"هل من السنة المداومة على القنوت في صلاة الصبح؟","answer":"الجواب: عليك أن تعمل بالسنة وأن تنبههم على هذا، وترشدهم إلى ذلك بالأسلوب الحسن، فإن القنوت دائماً في الفجر ليس من المشروع، بل هو محدث، ثبت في مسند أحمد رحمه الله وسنن الترمذي و النسائي وابن ماجة عن سعد بن طارق بن أشيم الأشجعي، عن أبيه أن سعداً قال: يا أبت! إنك صليت خلف رسول الله ﷺ، وخلف أبي بكر و عمر وعثمان وعلي -رضي الله عن الجميع- أفكانوا يقنتون في الفجر؟ فقال: أي بني! محدث فبين طارق أن هذا محدث.\nوثبت من حديث أنس ومن حديث غير أنس كـأبي هريرة وجماعة أنه صلى الله عليه وسلم: كان يقنت في النوازل في الصبح وغيرها، فإذا وقع ابتلاء من عدو وقع بالمسلمين أو نزل بالمسلمين، أو سرية قتلت بالمسلمين، أو ما أشبه ذلك، يدعو الأئمة في المساجد في الركعة الأخيرة من الفجر، بعد الركوع بقدر النازلة أياماً أو شهراً أو نحو ذلك، ثم يمسكون، ما يستمرون هذا السنة عند الحاجة والنازلة يدعى ويقنت، لكن من غير استمرار، أما الاستمرار دائماً دائماً فهذا خلاف السنة، فعليك أن تقنعهم وأن توجههم إلى الخير، فإذا لم يقنعوا ولم يحصل من التئام بينك وبينهم، فلا مانع من الانتقال عنهم إلى مسجد آخر وعدم مخالفة السنة.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6019/هل-من-السنة-المداومة-على-القنوت-في-صلاة-الصبح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_095/09505.mp3","categories":["القنوت في الصلاة","الوتر وقيام الليل"]},{"id":8497,"question":"أختنا تقول: ما حكم من نسي دعاء القنوت في صلاة الوتر وسجد قبل أن يدعو به، وهل يجبره سجود السهو؟","title":"حكم من نسي قنوت الوتر","answer":"الجواب: ليس عليه شيء من نسي قنوت الوتر فلا شيء عليه، ولا يلزمه سجود السهو، فإن سجد فلا بأس ولكن لا يلزمه؛ لأن قنوت الوتر مستحب وليس بواجب وإذا تركه بعض الأحيان عمداً فلا بأس، كما فعله الصحابة  فالأمر في هذا واسع والحمد لله. نعم.","link":"https://binbaz.org.sa/fatwas/6557/حكم-من-نسي-قنوت-الوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_126/12611.mp3","categories":["قضايا المرأة","الوتر وقيام الليل","القنوت في الصلاة"]},{"id":8912,"question":"الرسالة التالية وصلت إلى البرنامج من أحد الإخوة المستمعين، يقول: أحمد جاسم من قرية مرجانة من العراق، أخونا يطلب من سماحة الشيخ الحديث عن صلاة الليل وعن صفة الصلاة، ولاسيما أنه قد قرأ كثيرًا من الأوصاف عن هذه الصلاة؟","title":"ما صفة صلاة قيام الليل؟","answer":"فصلاة الليل لها شأن عظيم، والأفضل فيها أن تكون مثنى مثنى، يقول النبي ﷺ: صلاة الليل مثنى مثنى فإذا خشي الصبح صلى ركعة واحدة توتر لها ما قد صلى ، فيصلي ما تيسر له ثنتين ثنتين ثم يوتر بواحدة، وأفضلها في آخر الليل - الثلث الأخير- وإن صلى في أول الليل قبل أن ينام لئلا يغلب عليه النوم في آخر الليل واحتاط في ذلك فلا بأس، هو أعلم بنفسه، إن قدر في آخر الليل فهو أفضل، وإن لم يتيسر له ذلك أوتر في أول الليل.\nوأقله واحدة، أقل الإيتار في الليل واحدة بعد صلاة العشاء وبعد سنتها الراتبة ركعة واحدة، فإن أوتر بثلاث، فالأفضل يسلم من الثنتين ثم يوتر بواحدة، وهكذا إذا أوتر بخمس يسلم من أربع من كل ثنتين ثم يوتر بواحدة، وهكذا.\nوكان النبي ﷺ في الغالب يوتر بإحدى عشرة ركعة، يسلم من كل ثنتين ثم يوتر بواحدة، وربما أوتر بثلاث عشرة، وسلم من كل ثنتين وأوتر بواحدة عليه الصلاة والسلام، والأمر في هذا واسع والحمد لله، وليس فيه حد محدود، فلو أوتر بعشرين أو بثلاثين أو بأربعين يسلم من كل ثنتين ثم أوتر بواحدة، فكل هذا لا بأس به، ولكن يراعى في هذا الطمأنينة وعدم العجلة والنقر، يطمئن في صلاته ويخشع فيها ولا يعجل، فخمس ركعات أو سبع ركعات مع الطمأنينة والعناية أفضل من تسع أو إحدى عشرة مع العجلة. نعم.\nالسؤال: كيف يعتاد المرء عليها، لو تكرمتم سماحة الشيخ؟\nالجواب: السنة أن يداوم عليها دائمًا سواء كان في أول الليل أو في وسط الليل أو في آخر الليل، والأفضل آخر الليل إذا تيسر، يقول ﷺ: من خاف أن لا يقوم من آخر الليل فليوتر أول الليل، ومن طمع أن يقوم آخر الليل فليوتر آخر الليل، فإن صلاة آخر الليل مشهودة وذلك أفضل رواه مسلم في الصحيح، هذا هو الأفضل إذا تيسر، ويقول ﷺ في الحديث الصحيح: ينزل ربنا إلى سماء الدنيا كل ليلة حين يبقى ثلث الليل الآخر، فيقول: من يدعوني فأستجيب له، من يسألني فأعطيه، من يستغفرني فأغفر له، حتى يطلع الفجر متفق على صحته، هذا الحديث العظيم يدل على أن آخر الليل أفضل؛ لأنه وقت التنزل الإلهي، وهو نزول يليق بالله لا يشابه خلقه ، مثل: الاستواء والغضب والرضا والرحمة، كلها تليق بالله لا يشابه خلقه ، فهو ينزل ربنا، يعني: نزولًا يليق بجلاله لا يشابه نزول خلقه، ولا يعلم كيفيته إلا هو ، وهكذا قوله: الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى [طه:5] قوله جل وعلا: رَضِيَ اللَّهُ عَنْهُمْ وَرَضُوا عَنْهُ [البينة:8]، وَغَضِبَ اللَّهُ عَلَيْهِمْ [الفتح:6] وما أشبه ذلك، كلها صفة تليق بالله، لا يشابه خلقه في غضبهم، ولا في استوائهم، ولا في نزولهم، ولا في رحمتهم.. إلى غير ذلك، صفات الله كلها تليق بالله يجب إثباتها لله على الوجه اللائق بالله سبحانه من غير تحريف ولا تعطيل ولا تكييف ولا تمثيل.\nالمقدم: جزاكم الله خيرًا، إذًا كيفية الاعتياد عليها حتى يكون المرء معتادًا لصلاة الليل أو على صلاة الليل كيف يفعل؟\nالشيخ: كيف، كيف ... ؟\nالمقدم: إذا أراد الإنسان أن تكون صلاة الليل له عادةً معتادة عبادة، كيف يفعل؟\nالشيخ: يستمر على عدد معلوم الذي يستطيعه، على ثلاث على خمس على سبع، وإذا زاد بعض الأحيان عند النشاط فلا بأس، لكن يعتاد عددًا معلوم ويداوم عليه؛ لقول النبي ﷺ: إن أحب العمل إلى الله ما دام عليه صاحبه وإن قل فالعمل الدائم أفضل، فإذا زاد في بعض الأحيان عند النشاط، هذا ينفعه ولا يضره.","link":"https://binbaz.org.sa/fatwas/7068/ما-صفة-صلاة-قيام-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_169/169004.mp3","categories":["الوتر وقيام الليل"]},{"id":8913,"question":"كثرت الصوارف عن صلاة الليل سماحة الشيخ، هل من توجيه لو تكرمتم؟","title":"ما النصيحة للتغلُّب على التقصير في صلاة الليل؟","answer":"فالحاصل أنه يجب على المؤمن أن يحذر ما يشغله عن صلاة الفريضة، ويستحب له أن يعتاد التبكير حتى يقوم من الليل، وحتى يتيسر له القيام من الليل، لأداء العبادة التي هي النافلة في التهجد من الليل، ولا ينبغي له السمر مطلقًا إلا في مصالح المسلمين أو في أمورٍ ضرورية مع ضيف ونحوه أو مع أهله، وكل سمر قد يفضي به إلى ترك الفريضة، إلى إضاعة صلاة الفجر، فهو سمر ممنوع لا يجوز، حتى ولو كان في قراءة القرآن ولو في صلاة التهجد، ليس له أن يسمر ويسهر على وجه يضيع عليه صلاة الفجر، بل ينام مبكرًا ويصلي ما تيسر في أول الليل أو في آخره حتى يصلي صلاة الفجر، ويستعين على هذا بخير أهله يوقظونه، أو بالساعة المنبهة، يؤكدها على وقت مناسب قبل أذان الفجر بقليل حتى يقوم، أو في وقت تهجده قبل الأذان بساعة أو بأكثر على حسب حاله حتى يقوم الليل بتهجده، فإذا أوتر في أول الليل ولم يقم إلا عند الفجر فلا بأس به، لا حرج في ذلك. نعم.\nالمقدم: جزاكم الله خيرًا، كدت أسألكم عن القراءة، وإذا بكم تقولون: حتى السهر على قراءة القرآن إذا أدى ذلك إلى التأثير على صلاة الفريضة أو على قيام الليل فإن المرء مدعو لتركه.\nالشيخ: الله المستعان! وفق الله الجميع.\nالمقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/7070/ما-النصيحة-للتغلب-على-التقصير-في-صلاة-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_169/16906.mp3","categories":["نصائح وتوجيهات","الوتر وقيام الليل"]},{"id":9067,"question":"يحرص كثير من الأئمة سماحة الشيخ على أن يختم القرآن في التراويح وفي التهجد؟","title":"هل يستحب ختم القرآن في التراويح؟","answer":"الجواب: هذا لأجل سماع الناس جميع القرآن، إذا تيسر أن يسمع جميع القرآن بحيث يكون كل ليلة فيها جزء أو أقل من جزء لكن في العشرة الأخيرة يزيد حتى يختم القرآن ويكمله هذا يكون أفضل إذا تيسر من دون مشقة، وهكذا دعاء الختم يدعو بهم حتى يؤمنوا كان السلف يفعلون ذلك فإذا فعل ذلك فلا حرج، وقد عقد العلامة ابن القيم رحمه الله باباً في كتابه: جلاء الأفهام في الصلاة والسلام على خير الأنام، وذكر في ذلك حال السلف في العناية بختم القرآن. نعم.\nالمقدم: بارك الله فيك.\nالشيخ: وفق الله الجميع. نعم.\nالمقدم: اللهم آمين. الذين لا يتمكنون من الختم يشعرون بشيء من الألم سماحة الشيخ ماذا يقول لهم؟\nالشيخ: لا حرج في ذلك الأمر في هذا واسع، إن ختمت فهو أفضل حتى يسمع الناس وحتى يفوز بالأجر العظيم في هذا الشهر الكريم، وإن حال حائل ولم يتيسر له الختم وهو إمام إما لأجل الرفق بهم لأنهم أصحاب أشغال، أو لأسباب أخرى فلا حرج الأمر واسع بحمد الله، والمؤمن يراعي المأمومين ولا يشق عليهم ويرفق بهم، وإذا كانوا تشق عليهم الإطالة فكونهم يقيمونها أولى من تركها خوفاً من الإطالة، فإذا صلى بهم إحدى عشرة ركعة فهو أفضل إحدى عشرة أو ثلاث عشرة مع الترتيل ومع الركود في الركوع والسجود فهو أفضل من كثرة القراءة ومن صلاة عشرين أو أكثر، كونه يتحرى فعل النبي ﷺ إحدى عشرة ركعة أو ثلاثة عشرة ركعة كان هذا أفضل، والإحدى عشر أفضل من الثلاث عشرة؛ لأن هذا هو المحفوظ عنه ﷺ في الغالب كما قالت عائشة رضي الله عنها، وربما صلى بعض الأحيان ثلاث عشرة، وربما صلى أقل من ذلك، وصلى الصحابة  عشرين ركعة مع الوتر، كل هذا بحمد الله واسع، فمن زاد أو نقص فلا حرج؛ لقوله ﷺ: صلاة الليل مثنى مثنى - ولم يحدد عدداً معلوماً ثم قال:- فإذا خشي أحدكم الصبح صلى ركعة واحدة توتر له ما قد صلى، وهذا عام في رمضان وفي غيره، فمن زعم أنه يجب الاقتصار على إحدى عشرة أو ثلاث عشرة فقد غلط، ومن كره الزيادة فقد غلط، ومن حرمها فهو أشد غلطاً وإنما ذلك أفضل إذا اقتصر على إحدى عشرة أو ثلاث عشرة هذا أفضل من أجل التمكن من إطالة القراءة وإطالة الركوع والسجود، ومن أجل تمكين المأمومين من ذلك، ومن أجل موافقة السنة التي هي الغالبة من فعل النبي صلى الله عليه وسلم لكن من زاد فلا حرج. نعم.","link":"https://binbaz.org.sa/fatwas/7227/هل-يستحب-ختم-القران-في-التراويح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_149/14910.mp3","categories":["الوتر وقيام الليل"]},{"id":9073,"question":"ماذا عن القراءة من المصحف سماحة الشيخ؟","title":"حكم قراءة الإمام من المصحف في التراويح","answer":"الجواب: لا حرج في ذلك، الصواب أنه لا حرج في ذلك، فإذا احتاج إلى أن يقرأ من المصحف لأنه لم يحفظ القرآن فلا بأس يقرأ من المصحف، وقد ثبت أن عائشة رضي الله عنها كان يصلي بها مولاها ذكوان من المصحف ذكره البخاري رحمه الله تعليقاً جازماًَ به، والأصل أنه لا بأس بهذا فمن منع فعليه الدليل، الأصل جواز القراءة حفظاً وقراءة من المصحف هذا هو الأصل، فمن قال: (يمنع من المصحف) فعليه الدليل، والأصل أنه لا دليل، فمعنى الأصل وهو جواز القراءة من المصحف، وقد فعلتها أم المؤمنين وهي من أفقه الناس رضي الله عنها. نعم.","link":"https://binbaz.org.sa/fatwas/7228/حكم-قراءة-الامام-من-المصحف-في-التراويح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_149/14911.mp3","categories":["الوتر وقيام الليل"]},{"id":9076,"question":"يتحدث الناس كثيراً سماحة الشيخ عن صلاة النساء للتهجد أو التراويح في المساجد هل من كلمة حول هذا لو تكرمتم؟","title":"حكم خروج النساء لصلاة التراويح","answer":"الجواب: نعم، لا بأس بذلك أن يصلي النساء مع المسلمين في المساجد لكن مع العناية بالحجاب والتحرز من الفتنة وعدم الأطياب التي يمرون بها في الأسواق، تكون متحرزة من الطيب ومن التبرج وإظهار المحاسن، بل تكون محتجبة متسترة بعيدة عن أسباب الفتنة وإلا فبيتها خير لها، بيتها أولى بها وأكرم لها، لكن إذا دعت الحاجة إلى الخروج؛ لأنها تكسل في بيتها أو لأنها تريد أن تسمع المواعظ والذكر فهذا لا بأس به لكن بهذا الشرط؛ التحفظ والعناية والتستر والبعد عن أسباب الفتنة لا من جهة الطيب ولا من جهة الملابس ولا من جهة إظهار المحاسن. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7235/حكم-خروج-النساء-لصلاة-التراويح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_149/14912.mp3","categories":["قضايا المرأة","الوتر وقيام الليل","القنوت في الصلاة"]},{"id":9172,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول: من أبناء اليمن عبد الله أحمد حسن يمني مقيم في مدينة الدمام، أخونا يسأل سؤالاً وليقول: هل يجوز في شهر رمضان اختصار أقصر السور في صلاة التراويح أم يكون القرآن كاملاً على ظهر وبطن -كما يعبر- حيث عندنا في القرية لم يتمونه بل من أقصر السور، أرجو أن تتفضلوا بالتوجيه نحو هذا جزاكم الله خيراً؟","title":"حكم اختيار قصار السور لقراءتها في التراويح","answer":"الجواب: الشهر الكريم المؤمنون فيه يحتاجون إلى التشجيع والتوجيه والنصيحة والعظة المختصرة التي ليس فيها طول ولا إسهاب بل في كل مقام بحسبه، وفي قراءة التراويح لا يطول كثيراً ولكن إذا أمكن أن يختم بهم ختمة في جميع الشهر فهذا أولى وأكمل حتى يسمعوا جميع القرآن، وينبغي له أن يقرأ في التراويح في كل ركعة آيات كربع الثمن ثلث الثمن لا تشق عليهم، أما تعمده قصار السور وهو يستطيع أن يقرأ خلاف ذلك فالأولى ترك ذلك، أما إذا كان لا يحفظ وإنما يحفظ قصار السور فيرددها فلا حرج في ذلك، لكن لو قرأ من أول القرآن إلى آخره ولم يطول عليهم ولو من المصحف إذا كان لا يحفظ، من المصحف لا بأس، كان ذكوان مولى عائشة رضي الله عنها كان يصلي بها ويقرأ من المصحف، والصواب أنه لا حرج في ذلك، لكن من تيسر له أن يقرأ حفظاً فذلك أولى وأكمل، أما من لا يتيسر له ذلك لأنه لا يحفظ القرآن فلا مانع من أن يقرأ من المصحف، ولكن لا يطول على إخوانه يراعي أحوالهم، وقد يكون لهم أعمال، وقد يكون لهم شئون تمنعهم من الإطالة وتمنعهم من الرضا بالتطويل بل يشق عليهم ذلك فإنه يلاحظهم، فالناس أقسام؛ منهم من يتحمل ومنهم من لا يتحمل، والنبي عليه السلام قال في حق الأئمة: من أم الناس فليخفف فإن فيهم الضعيف والصغير والكبير وذا الحاجة، هذا في الفرائض فكيف بالنوافل؟ التراويح نافلة فهو يلاحظ الشيء الذي لا يشق عليهم ويحصل لهم به المتابعة له والصلاة معه والراحة في هذه العبادة والخشوع فيها، فلا ينبغي له أن يفعل شيء ينفرهم ويجعلهم يخرجون من المسجد ولا يصلون معه إلا الشيء القليل، وقد قال عليه الصلاة والسلام: من قام مع الإمام حتى ينصرف كتب الله له قيام ليلة، هذا فضل عظيم، لكن متى طول عليهم فقد ينفرون وقد لا يكملون، فالإمام يشرع له أن يراعيهم وأن يصلي بهم صلاة بين الصلاتين ليس فيها مشقة ولا تطويل، وليس فيها نقر واختصار كثير، نسأل الله للجميع التوفيق.نعم.","link":"https://binbaz.org.sa/fatwas/7332/حكم-اختيار-قصار-السور-لقراءتها-في-التراويح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_150/15006.mp3","categories":["الوتر وقيام الليل"]},{"id":9244,"question":"بارك الله فيكم، يسأل أيضاً ويقول: إذا كان الشخص يصلي صلاة الليل النافلة مداوماً عليها منذ مدة طويلة، ثم رجع يصلي هذه النافلة في الضحى، وتركها في الليل فهل يكون آثماً أم لا؟","title":"حكم ترك قيام الليل والصلاة في الضحى بدلاً عنه","answer":"الجواب: لا ، ليس بآثم، التهجد بالليل نافلة وتطوع، فإذا صلى في الليل أو في النهار تطوع فهو مأجور، ولكن صلاة الليل أفضل، فإذا تيسر له أن يكون تهجده بالليل ونافلته بالليل يصلي خمساً أو سبعاً أو أكثر من ذلك، هذا أفضل في الليل، فإن لم يتيسر فليوتر بما تيسر كركعة أو ثلاث ثم يجعل مزيد النافلة في النهار أرفق به، لا بأس بذلك؛ لأنها كلها نافلة. نعم.\nالمقدم: لكن الوتر محله الليل؟\nالشيخ: الوتر محله الليل، يوتر ولو بواحدة في الليل، والباقي يتطوع في الضحى لا بأس، وبعد الظهر لا بأس. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7408/حكم-ترك-قيام-الليل-والصلاة-في-الضحى-بدلا-عنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_235/23507.mp3","categories":["الوتر وقيام الليل"]},{"id":9609,"question":"وهذه رسالة من المستمعة نسيمة أحمد حاجي من البحرين، تقول: هل يجوز تأخير صلاتي الشفع والوتر إلى حين قيام الليل، بأن يصلي صلاة قيام الليل ثم يختتمها بالشفع والوتر، أو أنه يجب الإتيان بها قبل النوم أفيدونا أفادكم الله؟","title":"ما الأفضل في وقت صلاة الوتر؟","answer":"الجواب: المؤمن والمؤمنة مخيران، من شاء أوتر في أول الليل ومن شاء أوتر في آخر الليل، والأفضل آخر الليل لمن تيسر له ذلك، يقول النبي ﷺ: من خاف أن لا يقوم من آخر الليل فليوتر أوله، ومن طمع أن يقوم آخر الليل فليوتر آخر الليل، فإن صلاة آخر الليل مشهودة وذلك أفضل رواه مسلم في الصحيح.\nفإذا تيسر للمؤمن أو المؤمنة الإيتار والتهجد في آخر الليل كان أفضل؛ لأن ذلك وقت التنزل الإلهي، ووقت إجابة الدعاء، ثبت عن رسول الله عليه الصلاة والسلام أنه قال: ينزل ربنا إلى سماء الدنيا كل ليلة حين يبقى ثلث الليل الآخر، فيقول: من يدعوني فأستجيب له؟ من يسألني فأعطيه؟ من يستغفرني فأغفر له؟ حتى ينفجر الفجر وفي اللفظ الآخر فيقول سبحانه: هل من سائل فيعطى سؤله؟ هل من مستغفر فيغفر له؟ هل من تائب فيتاب عليه؟ وهذا الحديث العظيم متواتر عن رسول الله عليه الصلاة والسلام، وهذا النزول يليق بالله لا يشابه خلقه سبحانه وتعالى في شيء من صفاته، فهو نزول يليق بالله لا يكيف ولا يمثل، كاستوائه على عرشه، وكسمعه وبصره وغضبه ورضاه ونحو ذلك كلها صفات تليق بالله، لا يشابه فيها خلقه ، هكذا قال أهل السنة والجماعة: يجب إثبات الصفات لله سبحانه وإمرارها كما جاءت في الكتاب العظيم وفي السنة الصحيحة المطهرة على الوجه اللائق بالله سبحانه وتعالى، كما قال : لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11] .. وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ [الإخلاص:4].\nفإذا تيسر للمؤمن أو المؤمنة التهجد في آخر الليل والاستغفار والدعاء ثم يختم صلاته بالوتر واحدة فهذا هو الأفضل، والسنة أن تكون واحدة فقط هي الأخيرة مفردة بسلام واحد، يقرأ فيها الفاتحة وقل هو الله أحد، ثم يركع ثم يرفع فيقنت القنوت المشروع إذا تيسر له ذلك هذا هو السنة، وإن سرد ثلاثاً جميعاً وأوتر بثلاث جميعاً سرداً بسلام واحد وجلوس واحد فلا بأس، وإن سرد خمساً فلا بأس بجلوس واحد وسلام واحد لا بأس، ولكن الأفضل مثنى مثنى، يسلم من كل ثنتين ويوتر بواحدة؛ لقوله عليه الصلاة والسلام: صلاة الليل مثنى مثنى، فإذا خشي أحدكم الصبح صلى ركعةً واحدة توتر له ما قد صلى فهذا هو السنة.\nأما إن كان يخاف أن لا يقوم من آخر الليل؛ فإن الأفضل أن يوتر في أول الليل، يصلي ما تيسر من أول الليل ثم يوتر بواحدة، يصلي أربعاً أو ستاً أو ثماناً أو أكثر ثم يوتر بواحدة قبل أن ينام. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7768/ما-الافضل-في-وقت-صلاة-الوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_249/24902.mp3","categories":["الوتر وقيام الليل"]},{"id":9840,"question":"لها استفسار آخر في رسالتها تقول فيه: هل تصح صلاة التهجد بعد صلاة الوتر حيث أنني أصلي الوتر بعد العشاء مباشرة ثم أعود مرة ثانية في منتصف الليل أصلي صلاة التهجد، وقد سمعت حديثًا عن رسول الله ﷺ يقول فيه: اجعلوا آخر صلاتكم في الليل وترًا، فأفيدوني في ذلك بارك الله فيكم؟","title":"حكم من أوتر أول الليل وأراد أن يقوم آخره","answer":"الجواب: نعم، الحديث صحيح، رواه البخاري ومسلم في الصحيحين من حديث عبد الله بن عمر رضي الله عنهما عن النبي ﷺ أنه قال: اجعلوا آخر صلاتكم بالليل وترًا.\nفينبغي لك أن تدعي الوتر في آخر الليل ما دمت بحمد الله تقومين في وسط الليل وهو شيء معتاد لك؛ فالسنة لك أن تأخري الوتر وتجعليه بعد التهجد، فإذا تهجدت ما قدر الله لك، تصلين الركعة الواحدة في الوتر قبل طلوع الفجر، وقد قال عليه الصلاة والسلام: صلاة الليل مثنى مثنى يعني: ثنتين ثنتين، فإذا خشي أحدكم الصبح صلى ركعة واحدة توتر له ما قد صلى، هذا هو المشروع أن تصلي ما تيسر من الليل ثنتين ثنتين، ثم إذا فرغت من التهجد صليت ركعة واحدة قبل الصبح توتر لك ما قد صليت من التهجد.\nولكن لو فرضنا أنك أوترت في أول الليل وخفت أن لا تقومي من آخر الليل ثم يسر الله لك القيام من آخر الليل فإنك تصلين ما قسم الله لك من الركعات ويكفي الوتر الأول ولا حاجة إلى إعادة الوتر؛ لقول النبي ﷺ: لا وتران في ليلة، فإذا أوتر الإنسان في أول الليل ثم يسر الله له فقام في آخر الليل فإنه يصلي ما قسم الله له ركعتين أو أربع ركعات أو أكثر ثنتين ثنتين، ويكفيه الوتر الأول ولا حاجة إلى إعادته؛ لأن الرسول ﷺ نهى عنه بقوله: لا وتران في ليلة، اللهم صل عليه وسلم. نعم.\nالمقدم: لكن ما تشفع الوتر يا سماحة الشيخ، تشفع الوتر الأول؟\nالجواب: القول هذا ضعيف، وقول وأن تشفع الوتر بركعة ثم توتر قول ضعيف، والصواب: أنه يكفي الوتر الأول ولا حاجة إلى شفعها. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/8007/حكم-من-اوتر-اول-الليل-واراد-ان-يقوم-اخره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_198/19807.mp3","categories":["الوتر وقيام الليل"]},{"id":9909,"question":"يقول السائل: كم عدد ركعات سنة قيام الليل وسنة التهجد؟ وفي أي وقت تصلى؟ جزاكم الله خيراً.","title":"عدد ركعات صلاة الليل","answer":"الجواب: على كل حال: هذا يرجع إلى قدرته، النبي ﷺ كان يصلي إحدى عشر ركعة، يسلم من كل ثنتين، يطيل في قراءته وركوعه وسجوده عليه الصلاة والسلام، ويستفتح بركعتين خفيفتين، فهذا أفضل ما يكون، وإذا صلى ثلاث أو خمس أو أكثر فلا حرج كل يصلي قدرته، والحمد لله، يقول النبي ﷺ: صلاة الليل مثنى مثنى، فإذا خشي أحدكم الصبح صلى ركعة واحدة توتر له ما قد صلى والله جل وعلا أثنى على عباده المؤمنين فقال: وَالَّذِينَ يَبِيتُونَ لِرَبِّهِمْ سُجَّدًا وَقِيَامًا [الفرقان:64] وقال سبحانه: كَانُوا قَلِيلًا مِنََ اللَّيْلِ مَا يَهْجَعُونَ ۝ وَبِالأَسْحَارِ هُمْ يَسْتَغْفِرُونَ [الذاريات:17-18] فليس فيها حد محدود، إذا صلى ثنتين وأوتر بواحدة أو صلى تسليمتين وأوتر بالخامسة أو صلى ثلاث تسليمات وأوتر بالسابعة أو صلى أربع تسليمات وأوتر بالتاسعة كل ذلك لا حرج فيه والحمد لله.\nوأفضل ذلك أن يصلي إحدى عشرة يسلم من كل ثنتين بالطمأنينة والقراءة المرتلة والتدبر والركود في سجوده كله في سجوده وركوعه ثم يوتر بواحدة هذا هو الأفضل، وإن زاد أو نقص فلا حرج.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8077/عدد-ركعات-صلاة-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_273/27321.mp3","categories":["الوتر وقيام الليل"]},{"id":10105,"question":"المستمع عبدالله بن عبدالعزيز التويجري من القصيم بريدة بعث يسأل ويقول في حكم الوتر: هل هو واجب أم مستحب؟","title":"هل الوتر مستحب أم واجب؟","answer":"الجواب: الوتر سنة، مستحب وليس بواجب عند جمهور أهل العلم؛ لأنه ﷺ لما سئل بعدما أخبر المسلمين بالصلوات الخمس قال بعضهم: هل علي غيرها؟ قال: لا، إلا أن تطوع، فالوتر والسنن الراتبة كلها مستحبة، وهكذا صلاة الضحى كلها مستحبة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8275/هل-الوتر-مستحب-ام-واجب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_333/33316.mp3","categories":["الوتر وقيام الليل"]},{"id":10171,"question":"أرجو أن تفيدوني عن صلاة الوتر هل هي ركعة واحدة، أم ثلاث؟ جزاكم الله خيراً.","title":"عدد ركعات صلاة الوتر","answer":"الجواب: صلاة الوتر أقلها ركعة واحدة بعد العشاء أو في آخر الليل، ركعة واحدة هذا أقلها، وإن صلى ثلاثاً أو خمساً أو أكثر فهو أفضل، لكن أقلها واحدة بعد سنة العشاء أو في وسط الليل أو في آخر الليل، والأفضل أن يزيد يصلي ثلاث أو خمس أو أكثر من ذلك ثنتين ثنتين، يسلم من كل ثنتين ويوتر بواحدة، هذا هو السنة لقوله ﷺ في الحديث الصحيح: صلاة الليل مثنى مثنى فإذا خشي أحدكم الصبح صلى ركعة واحدة توتر له ما قد صلى وكان ﷺ يصلي إحدى عشر في الغالب يسلم من كل ثنتين ويوتر بواحدة، وربما صلى سبعاً، وربما صلى تسعاً، وربما صلى خمساً، ربما صلى ثلاثاً عليه الصلاة والسلام، ربما صلى أكثر صلى ثلاثة عشر، فهكذا المسلم يصلي ما يسر الله له ويسلم من كل ثنتين ويوتر بواحدة، فإن لم يصل إلا واحدة فقط أجزأه ذلك والحمد لله. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8350/عدد-ركعات-صلاة-الوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_308/30811.mp3","categories":["الوتر وقيام الليل"]},{"id":10193,"question":"متى تبدأ وتنتهي صلاة الضحى وصلاة قيام الليل، والوقت بالساعة تقريبًا لو تكرمتم؟","title":"ما وقت كل من صلاة الضحى وقيام الليل؟","answer":"الجواب: الضحى تبتدي بارتفاع الشمس قيد رمح إلى قرب الزوال، ولكن الأفضل أن يصليها عند شدة الضحى لقوله ﷺ: صلاة الأوابين حين ترمض الفصال يعني: حين تشتد الرمضاء على أولاد الإبل، هذا هو الأفضل، وإن صلاها بعد ارتفاع الشمس قيد رمح حصلت السنة، وإذا كان قرب الزوال وقف عن ذلك؛ لأنها حينئذ تقف الشمس يسمى وقت الوقوف، وذكر النبي ﷺ أنها تسجر فيها جهنم، فالحاصل أنه عند قرب الزوال لا يصلي، هذا من أوقات النهي وهو وقت قصير نحو ربع ساعة أو ثلث ساعة تقريبًا قبل الزوال، قبل أن تميل إلى جهة المغرب يقال له: وقت الوقوف، فلا ينبغي له أن يتطوع في هذه الحالة بشيء من الصلاة، بل يمسك حتى تزول الشمس، يعني يمسك عن الصلاة تنفل حتى تزول الشمس عند قرب الزوال. نعم.\nالمقدم: يذكر ويطلب الوقت بالساعة تقريبًا لو تكرمتم.\nالشيخ: هذا يختلف على كل حال، الليل يختلف والنهار يختلف، فإذا كان بعد طلوع الشمس بربع ساعة تقريبًا ارتفعت الشمس، ربع ساعة تقريبًا تكون الشمس مرتفعة..\nالمقدم: هذا بالنسبة لصلاة الضحى.\nالشيخ: وإذا بقي على الظهر نحو نصف ساعة ينبغي التوقف احتياطًا عن الصلاة حتى تزول الشمس، أما في الليل فإذا غاب الشفق دخل وقت العشاء، الشفق الأحمر من المغرب، الشفق الأحمر هذا يكون في جهة المغرب جهة الغرب يعني، فإذا غاب وانتهى دخل وقت العشاء وخرج وقت المغرب، وإذا صلى العشاء دخل وقت التهجد، إذا صلى العشاء ولو مبكرًا ولو مجموعة مع المغرب كالمسافر والمريض، يعني: إذا صلاها جمعًا في السفر والمرض دخل وقت التهجد إلى طلوع الفجر، كله وقت تهجد، وإذا صلاها في الوقت دخل وقت العشاء ..... وقت التهجد بعد صلاة العشاء وبعد السنة الراتبة، يصلي سنتها ثنتين وبذلك يدخل وقت التهجد في أول الليل وفي وسطه وفي آخره، لكن كونه يصلي في آخر الليل في الثلث الأخير يكون أفضل، حتى يوافق النزول الإلهي. نعم.\nالمقدم: وآخر وقت التهجد؟\nالشيخ: طلوع الفجر، لكن من فاته ورده في الليل شرع له أن يصليه من النهار، الضحى من النهار شفعًا لا وترًا، يصلي إذا كان عادته ثلاث يصليها أربعًا تسليمتين، إذا كان عادته خمسًا صلاها ثلاث تسليمات ستًا، يعني يشفع من واحدة؛ لما ثبت عن عائشة رضي الله عنها قالت: كان النبي ﷺ إذا فاته ورده من الليل لمرض أو نوم صلى من النهار ثنتي عشرة ركعة، وكانت عادته في الغالب إحدى عشرة ركعة في الليل، إذا صلى في النهار صلاها ثنتي عشرة ركعة، يعني زاد ركعة شفعها، اللهم صل عليه.\nالمقدم: لأن النهار ليس فيه وتر.\nالشيخ: ليس محل وتر. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8356/ما-وقت-كل-من-صلاة-الضحى-وقيام-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_334/33410.mp3","categories":["صلاة التطوع","الوتر وقيام الليل"]},{"id":10292,"question":"من البحرين مدينة المحرق رسالة بعث بها المستمع (ف. ع. س. س) يقول: أود أن أعرف كم عدد ركعات صلاة التراويح، هل عددها ثمان ركعات أو عشرون ركعة، ذلك أنني أرى بعض المساجد يصلون ثمان والبعض الآخر يصلون عشرين أفيدوني مأجورين جزاكم الله خيراً؟","title":"هل لصلاة التراويح عدد ركعات معين؟","answer":"الجواب: ليس للتراويح عدد محصور بل الأمر فيها واسع والحمد لله، من صلى عشرين أو إحدى عشرة أو ثلاثة عشرة أو صلى أربعين مع الوتر أو خمسين مع الوتر كله لا بأس به؛ لقول النبي ﷺ: صلاة الليل مثنى مثنى فإذا خشي أحدكم الصبح صلى ركعةً واحدة توتر له ما قد صلى ولم يحدد عليه الصلاة والسلام، بل قال: صلاة الليل مثنى مثنى ثم قال: فإذا خشي أحدكم الصبح صلى ركعةً واحدة توتر له ما قد صلى فدل ذلك على أنه لو صلى ثمان وأوتر أو عشراً وأوتر أو عشرين وأوتر أو ثلاثين وأوتر أو أكثر وأوتر لا بأس لا حرج في ذلك، لكن الأفضل أن يفعل فعل النبي ﷺ، الأفضل إحدى عشرة أو ثلاثة عشرة هذا هو الأفضل، وإن صلى أوتر بسبع أو تسع أو خمس أو ثلاث فلا بأس في رمضان أو في غيره، والأفضل في رمضان أن يصلي إحدى عشرة أو ثلاثة عشرة هذا هو الأفضل، وإن صلى عشرين كما فعل الصحابة في عهد عمر رضي الله عنه فإنه في بعض الأحيان صلوا عشرين مع الوتر ثلاثاً الجميع ثلاثة وعشرون لا بأس، فعله أصحاب النبي ﷺ، إذا صلى الناس ثلاثاً وعشرين لا حرج في ذلك طيب، وأفضل من ذلك ثلاثة عشرة أو إحدى عشرة كما فعل عليه الصلاة والسلام، وإن صلوا أكثر صلوا أربعين وأوتروا بثلاث أو بواحدة كل ذلك لا بأس به، فالأمر في هذا واسع والحمد لله ولا ينبغي فيه الإنكار ولا التشديد، من صلى إحدى عشرة فقد أحسن، ومن صلى ثلاثة عشرة فقد أحسن وهو أفضل إحدى عشرة أو ثلاثة عشرة، ومن صلى عشرين وأوتر فلا بأس كما فعل الصحابة في عهد عمر ، كل هذا بحمد الله ميسر. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8468/هل-لصلاة-التراويح-عدد-ركعات-معين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_312/31208.mp3","categories":["الوتر وقيام الليل"]},{"id":10297,"question":"من البحرين مدينة المحرق رسالة بعث بها المستمع (ف. ع. س. س) يقول: أود أن أعرف كم عدد ركعات صلاة التراويح، هل عددها ثمان ركعات أو عشرون ركعة، ذلك أنني أرى بعض المساجد يصلون ثمان والبعض الآخر يصلون عشرين أفيدوني مأجورين جزاكم الله خيراً؟","title":"هل لصلاة التراويح عدد ركعات معين؟","answer":"الجواب: ليس للتراويح عدد محصور بل الأمر فيها واسع والحمد لله، من صلى عشرين أو إحدى عشرة أو ثلاثة عشرة أو صلى أربعين مع الوتر أو خمسين مع الوتر كله لا بأس به؛ لقول النبي ﷺ: صلاة الليل مثنى مثنى فإذا خشي أحدكم الصبح صلى ركعةً واحدة توتر له ما قد صلى ولم يحدد عليه الصلاة والسلام، بل قال: صلاة الليل مثنى مثنى ثم قال: فإذا خشي أحدكم الصبح صلى ركعةً واحدة توتر له ما قد صلى فدل ذلك على أنه لو صلى ثمان وأوتر أو عشراً وأوتر أو عشرين وأوتر أو ثلاثين وأوتر أو أكثر وأوتر لا بأس لا حرج في ذلك، لكن الأفضل أن يفعل فعل النبي ﷺ، الأفضل إحدى عشرة أو ثلاثة عشرة هذا هو الأفضل، وإن صلى أوتر بسبع أو تسع أو خمس أو ثلاث فلا بأس في رمضان أو في غيره، والأفضل في رمضان أن يصلي إحدى عشرة أو ثلاثة عشرة هذا هو الأفضل، وإن صلى عشرين كما فعل الصحابة في عهد عمر رضي الله عنه فإنه في بعض الأحيان صلوا عشرين مع الوتر ثلاثاً الجميع ثلاثة وعشرون لا بأس، فعله أصحاب النبي ﷺ، إذا صلى الناس ثلاثاً وعشرين لا حرج في ذلك طيب، وأفضل من ذلك ثلاثة عشرة أو إحدى عشرة كما فعل عليه الصلاة والسلام، وإن صلوا أكثر صلوا أربعين وأوتروا بثلاث أو بواحدة كل ذلك لا بأس به، فالأمر في هذا واسع والحمد لله ولا ينبغي فيه الإنكار ولا التشديد، من صلى إحدى عشرة فقد أحسن، ومن صلى ثلاثة عشرة فقد أحسن وهو أفضل إحدى عشرة أو ثلاثة عشرة، ومن صلى عشرين وأوتر فلا بأس كما فعل الصحابة في عهد عمر ، كل هذا بحمد الله ميسر. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8468/هل-لصلاة-التراويح-عدد-ركعات-معين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_312/31208.mp3","categories":["الوتر وقيام الليل"]},{"id":10348,"question":"يقول: هل يقرأ في صلاة التراويح من طوال السور أو من قصارها؟","title":"صفة القراءة في صلاة التراويح","answer":"الجواب: الأفضل للإمام أن يراعي المأمومين ولا يطول عليهم، يقرأ من أول القرآن ويستمر حتى يختمه في آخر الشهر، وإن قرأ من السور القصيرة فلا بأس، يقرأ ما يتحملون وما لا يشق عليهم، وإن قرأ تارة بشيء من الطوال ولم يكملها بل فرقها في ركعتين أو أكثر فكل هذا حسن، المقصود أنه يقرأ ما يناسبهم ولا يشق عليهم ويحصل به الفائدة، وإذا قرأ من أول القرآن حتى يختمه كان هذا هو الأفضل، يبدأ بالفاتحة ثم البقرة إلى آخره حتى يختم القرآن في آخر الشهر، يكون هذا هو الأفضل مع مراعاة الترتيل وعدم العجلة وإيضاح القراءة حتى يستفيد المصلون وحتى يتدبروا ويتعقلوا. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8522/صفة-القراءة-في-صلاة-التراويح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_316/31606.mp3","categories":["الوتر وقيام الليل"]},{"id":10349,"question":"يقول: إن بعض الناس يقولون عندما أصلي صلاة العشاء: لا بد أن أصلي ثلاث ركعات، ركعتين ثم أصلي ركعة، ويسمون الأولى الشفع والأخيرة الوتر، هل ما قالوه صحيح وكيف توجهونني؟","title":"ما معنى الشفع والوتر بعد صلاة العشاء؟","answer":"الجواب: هذا مستحب وليس بواجب، ويسمى هذا الوتر، فيستحب للمؤمن والمؤمنة الإيتار كل ليلة، بعد صلاة العشاء ويستمر إلى طلوع الفجر، فإذا صلى المسلم أو المسلمة ركعتي العشاء سنة العشاء ركعتين وأحب أن يوتر قبل النوم أوتر بركعتين ثم ركعة، الشفع والوتر ركعتين ثم ركعة واحدة، وإن أوتر بواحدة فقط أجزأته بعد سنة العشاء، وإن أوتر بخمس أو بسبع أو بأكثر فكله طيب والنبي صلى الله عليه وسلم كان في الغالب يوتر بإحدى عشرة وربما أوتر بثلاث عشرة وربما أوتر بأقل من ذلك، يسلم من كل ثنتين ويوتر بواحدة يقرأ فيها: الحمد و قل هو الله أحد، وقد قال عليه الصلاة والسلام: صلاة الليل مثنى مثنى، فإذا خشي أحدكم الصبح صلى ركعة واحدة توتر له ما قد صلى، هذه هي سنة الوتر وهي مستحبة وليست واجبة، وهي مستحبة لجميع المسلمين ذكورهم وإناثهم، ما بين صلاة العشاء إلى طلوع الفجر، فمن أحب أن يقوم في آخر الليل فهو أفضل ومن خاف أن لا يقوم من آخر الليل أوتر بعد صلاة العشاء وقبل أن ينام، لقوله ﷺ في الحديث الصحيح الذي رواه مسلم في صحيحه : من خاف أن لا يقوم من آخر الليل فليوتر أوله، ومن طمع أن يقوم آخر الليل فليوتر آخر الليل فإن صلاة آخر الليل مشهودة وذلك أفضل، .... ..... ومعنى مشهودة: يعني التي يشهدها ملائكة الليل وملائكة النهار، والله ولي التوفيق. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8517/ما-معنى-الشفع-والوتر-بعد-صلاة-العشاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_316/31603.mp3","categories":["الوتر وقيام الليل"]},{"id":10406,"question":"يقول: إنني أقوم في أيام رمضان عند انتهائي من صلاة التراويح وأعود إلى البيت في قراءة القرآن والصلاة حتى صلاة فجر اليوم الثاني، وأقول: أصلي ركعتين طاعة لله تعالى وأكبر، وهذا طيلة الليل حتى انتهاء رمضان، فهل عملي هذا صحيح؟","title":"فضل العشر الأواخر من رمضان على بقية الليالي؟","answer":"الجواب: أما في العشر الأخيرة فلا بأس كان النبي يحييها عليه الصلاة والسلام في رمضان يحييها بالعبادة، ويوقظ أهله عليه الصلاة والسلام، فأما في العشرين الأول فالأفضل لك أن لا تحييها بل تنام فيها بعض الوقت حتى تستعين بنومتك على قومتك، وعلى أعمالك النهارية، فتصلي ما يسر الله مع المسلمين في المساجد وتنام.\nأما العشر الأخيرة فإنه يستحب إحياؤها بالعبادة بالقراءة والصلاة.\nثم المؤمن لا يتلفظ بالنية يقول: أصلي كذا وكذا ينوي بقلبه ويكفي، سواء التراويح أو صلاة الفريضة أو الراتبة أو غير ذلك لا حاجة للتلفظ، فلا يقول: نويت أن أصلي الظهر أو نويت أن أصلي ركعتي التحية، أو نويت أن أصلي صلاة الضحى، أو نويت أن أصلي صلاة العشاء كل هذا لا أصل له.\nكما أنه لا يقول أيضًا: نويت أن أتوضأ أو أن أطوف أو أسعى كل هذا لا أصل له، القلب هو محل النية، ينوي بقلبه والحمد لله. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8579/فضل-العشر-الاواخر-من-رمضان-على-بقية-الليالي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_340/34013.mp3","categories":["الوتر وقيام الليل"]},{"id":10431,"question":"يقول في سؤال له أيضًا: بعض الأئمة يقرءون قصار السور ويقتصرون على ذلك في صلاة التراويح، ولا يختمون القرآن إطلاقًا ما حكم هذا العمل؟","title":"حكم القراءة في التراويح بقصار السور وعدم الختم","answer":"الجواب: الأمر في هذا واسع والحمد لله، الكل يقرأ بما يسر الله له، سواءً قرأ القرآن كله، أو قرأ من قصار المفصل أو قرأ بعض السور التي يحفظها لا حرج في ذلك، لكن الأفضل أن يقرأ القرآن كله إذا تيسر ولو من المصحف، يجعل حوله كرسي ويقرأ المصحف وإذا أراد الركوع والسجود جعله على الكرسي وإذا قام قرأ، وكان ذكوان مولى عائشة رضي الله عنها يصلي بها في رمضان من المصحف.\nوالصواب: أنه لا حرج في ذلك، هذا هو الصواب، أنه لا حرج في أن يقرأ من المصحف ولو ترك ذلك وقرأ بهم من جزء عم أو غيره فلا حرج في ذلك، الأمر في هذا واسع، ليس من اللازم أن يختم القرآن لو صلى بهم ببعض القرآن في جميع رمضان فلا بأس في ذلك، سواءً كان من قصار المفصل أو من طواله، لكن الأفضل إذا تيسر له أن يختم بهم فهو أفضل. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8604/حكم-القراءة-في-التراويح-بقصار-السور-وعدم-الختم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_341/34107.mp3","categories":["القراءة في الصلاة","الوتر وقيام الليل"]},{"id":10440,"question":"المستمع غانم علي فايز بعث يسأل ويقول: سمعت في برنامجكم عن صلاة التهجد وأن أفضل أوقاتها الثلث الأخير من الليل، أريد معرفة المزيد عن صلاة التهجد جزاكم الله خيراً، وعن عدد ركعاتها؟","title":"ما كيفية صلاة التهجد وعدد ركعاتها؟","answer":"الجواب:  الأفضل آخر الليل إذا تيسر ذلك؛ لقول النبي ﷺ: من خاف أن لا يقوم من آخر الليل فليوتر أوله، ومن طمع أن يقوم آخر الليل فليوتر آخر الليل فإن صلاة آخر الليل مشهودة وذلك أفضل رواه مسلم في الصحيح، ويقول ﷺ في الحديث الصحيح : ينزل ربنا إلى سماء الدنيا كل ليلة حين يبقى ثلث الليل الآخر فيقول: من يدعوني فأستجيب له، من يسألني فأعطيه، من يستغفرني فأغفر له، فهذا التنزل الإلهي فرصة عظيمة للدعاء والعبادة للمؤمن يدعو ربه؛ لأنه يقول سبحانه: من يدعوني فأستجيب له، من يسألني فأعطيه، من يستغفرني فأغفر له، فإذا تيسر للمؤمن والمؤمنة أن يكون التهجد في آخر الليل في الثلث الأخير كان أفضل حتى يوافق هذا النزول الإلهي وهذا الجود من الرب والتفضل منه سبحانه وتعالى. وإذا أوتر في أول الليل كفى ذلك، وهذا النزول يليق بالله لا يشابه خلقه سبحانه وتعالى، من أحاديث الصفات، فهو نزول يليق بالله لا يعلم كيفيته إلا هو كما أن الاستواء يليق بالله لا يعلم كيفيته إلا هو سبحانه وتعالى كما قال تعالى: الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى [طه:5] في آيات أخرى، معناه ارتفع وعلا، وهو استواء يليق به سبحانه لا يشابه خلقه في استوائهم، وهكذا النزول نزوله إلى سماء الدنيا نزول يليق بالله لا يعلم كيفيته إلا هو  ولا يشابه خلقه في شيء من صفاته لا في النزول ولا في الاستواء ولا في السمع ولا في البصر ولا في الكلام ولا في غير ذلك، قال سبحانه: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11]. والتهجد أفضل ما يكون بإحدى عشرة أو ثلاث عشرة هذا أفضل، كان النبي ﷺ في الغالب يوتر بإحدى عشرة أو بثلاث عشرة، وربما أوتر بسبع وبخمس وبثلاث، وأقل شيء ركعة واحدة بعد صلاة العشاء وبعد الراتبة، وإن أوتر بثلاث كفى أو بخمس كفى أو بسبع كفى، ولكن الأفضل إحدى عشرة أو ثلاث عشرة يسلم من كل ثنتين، كما كان النبي يفعل عليه الصلاة والسلام، كان يسلم من كل ثنتين ويوتر بواحدة مفردة، ويقول ﷺ: صلاة الليل مثنى مثنى -يعني: ثنتين ثنتين- فإذا خشي أحدكم الصبح صلى ركعة واحدة توتر له ما قد صلى، يعني: يوتر بواحدة النهاية. ولو صلى أكثر صلى عشرين وأوتر بواحدة أو بثلاث، أو صلى أربعين وأوتر بواحدة أو بثلاث، أو صلى أكثر فلا بأس، كله واسع بحمد الله؛ لأن الرسول ﷺ ما حدد عدداً معلوماً من الركعات، أطلق قال: صلاة الليل مثنى مثنى، ولم يحدد، فدل على التوسعة والحمد لله، لكن أفضل ذلك إحدى عشرة أو ثلاث عشرة تأسياً به ﷺ واقتداءً به عليه الصلاة والسلام، في رمضان وفي غيره. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8617/ما-كيفية-صلاة-التهجد-وعدد-ركعاتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_318/31809.mp3","categories":["الوتر وقيام الليل"]},{"id":10445,"question":"المستمع غانم علي فايز بعث يسأل ويقول: سمعت في برنامجكم عن صلاة التهجد وأن أفضل أوقاتها الثلث الأخير من الليل، أريد معرفة المزيد عن صلاة التهجد جزاكم الله خيراً، وعن عدد ركعاتها؟","title":"ما كيفية صلاة التهجد وعدد ركعاتها؟","answer":"الجواب:  الأفضل آخر الليل إذا تيسر ذلك؛ لقول النبي ﷺ: من خاف أن لا يقوم من آخر الليل فليوتر أوله، ومن طمع أن يقوم آخر الليل فليوتر آخر الليل فإن صلاة آخر الليل مشهودة وذلك أفضل رواه مسلم في الصحيح، ويقول ﷺ في الحديث الصحيح : ينزل ربنا إلى سماء الدنيا كل ليلة حين يبقى ثلث الليل الآخر فيقول: من يدعوني فأستجيب له، من يسألني فأعطيه، من يستغفرني فأغفر له، فهذا التنزل الإلهي فرصة عظيمة للدعاء والعبادة للمؤمن يدعو ربه؛ لأنه يقول سبحانه: من يدعوني فأستجيب له، من يسألني فأعطيه، من يستغفرني فأغفر له، فإذا تيسر للمؤمن والمؤمنة أن يكون التهجد في آخر الليل في الثلث الأخير كان أفضل حتى يوافق هذا النزول الإلهي وهذا الجود من الرب والتفضل منه سبحانه وتعالى. وإذا أوتر في أول الليل كفى ذلك، وهذا النزول يليق بالله لا يشابه خلقه سبحانه وتعالى، من أحاديث الصفات، فهو نزول يليق بالله لا يعلم كيفيته إلا هو كما أن الاستواء يليق بالله لا يعلم كيفيته إلا هو سبحانه وتعالى كما قال تعالى: الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى [طه:5] في آيات أخرى، معناه ارتفع وعلا، وهو استواء يليق به سبحانه لا يشابه خلقه في استوائهم، وهكذا النزول نزوله إلى سماء الدنيا نزول يليق بالله لا يعلم كيفيته إلا هو  ولا يشابه خلقه في شيء من صفاته لا في النزول ولا في الاستواء ولا في السمع ولا في البصر ولا في الكلام ولا في غير ذلك، قال سبحانه: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11]. والتهجد أفضل ما يكون بإحدى عشرة أو ثلاث عشرة هذا أفضل، كان النبي ﷺ في الغالب يوتر بإحدى عشرة أو بثلاث عشرة، وربما أوتر بسبع وبخمس وبثلاث، وأقل شيء ركعة واحدة بعد صلاة العشاء وبعد الراتبة، وإن أوتر بثلاث كفى أو بخمس كفى أو بسبع كفى، ولكن الأفضل إحدى عشرة أو ثلاث عشرة يسلم من كل ثنتين، كما كان النبي يفعل عليه الصلاة والسلام، كان يسلم من كل ثنتين ويوتر بواحدة مفردة، ويقول ﷺ: صلاة الليل مثنى مثنى -يعني: ثنتين ثنتين- فإذا خشي أحدكم الصبح صلى ركعة واحدة توتر له ما قد صلى، يعني: يوتر بواحدة النهاية. ولو صلى أكثر صلى عشرين وأوتر بواحدة أو بثلاث، أو صلى أربعين وأوتر بواحدة أو بثلاث، أو صلى أكثر فلا بأس، كله واسع بحمد الله؛ لأن الرسول ﷺ ما حدد عدداً معلوماً من الركعات، أطلق قال: صلاة الليل مثنى مثنى، ولم يحدد، فدل على التوسعة والحمد لله، لكن أفضل ذلك إحدى عشرة أو ثلاث عشرة تأسياً به ﷺ واقتداءً به عليه الصلاة والسلام، في رمضان وفي غيره. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8617/ما-كيفية-صلاة-التهجد-وعدد-ركعاتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_318/31809.mp3","categories":["الوتر وقيام الليل"]},{"id":10471,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع عبدالودود عبدالله ناجي مجاهد التميمي من اليمن، له جمع من الأسئلة في أحدها يقول: هل صلاة الوتر واجبة؟ وهل أمر الرسول ﷺ أهل القرآن بأن يوتروا؟","title":"هل صلاة الوتر واجبة؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه.\nأما بعد: فصلاة الوتر سنة عند أهل العلم، وهو الذي عليه جمهور أهل العلم أنها سنة، وليست واجبة، ولهذا قال علي : ليس الوتر حتماً كآية مكتوبة، ولكنها سنة سنها رسول الله ﷺ ومن الأدلة على ذلك قوله ﷺ: لما سئل عن ما زاد على الصلوات الخمس قال له السائل: هل علي غيرها؟ قال: لا، إلا أن تطوع لما سأل عن الصلاة، أخبره عن الصلوات الخمس، ثم قال السائل: هل علي غيرها؟ قال: لا، إلا أن تطوع.\nفالوتر سنة مؤكدة ما بين صلاة العشاء إلى طلوع الفجر، وأقله ركعة واحدة، وإن زاد فهو أفضل كثلاث أو خمس أو أكثر من ذلك، وأفضله إحدى عشرة أو ثلاثة عشرة، كما فعله النبي عليه الصلاة والسلام، وإن أوتر بأكثر من ذلك فلا حرج، وقد قال ﷺ: أوتروا يا أهل القرآن، فإن الله وتر يحب الوتر، وهذا الأمر للتأكيد ليس للوجوب بل هو عند أهل العلم للتأكيد. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8649/هل-صلاة-الوتر-واجبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_320/32015.mp3","categories":["الوتر وقيام الليل"]},{"id":10880,"question":"رسالة وصلت إلى البرنامج من سلطنة عمان منطقة الظاهرة، وباعثها المستمع محمد اليعقوبي، يقول في أحد أسئلته: إذا صليت فريضة صلاة العشاء والسنة الراتبة هل أصلي الوتر قبل صلاة قيام الليل، أم بعد صلاة قيام الليل؟","title":"ترتيب صلاة الوتر في قيام الليل","answer":"الجواب: الوتر يكون هو الأخير بعد قيام الليل، النبي ﷺ قال: اجعلوا آخر صلاتكم بالليل وترًا، وقال -عليه الصلاة والسلام-: صلاة الليل مثنى مثنى، فإذا خشي أحدكم الصبح صلى ركعة واحدة توتر له ما قد صلى. فالسنة أن تكون صلاة الوتر هي الأخيرة، يتهجد يصلي ما بدا له مثنى مثنى، ثم يختم بواحدة وهي الوتر، هذا هو السنة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9059/ترتيب-صلاة-الوتر-في-قيام-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_359/35905.mp3","categories":["الوتر وقيام الليل"]},{"id":11116,"question":"له كلام كثير أيضًا، فهمت أنه يسأل عن صلاة التهجد، في أي وقت من الليل يقوم، وهل يقرأ بالسور الطوال، أو ما تيسر، أو يقرأ السور القصار؟ وجهوه جزاكم الله خيرًا.","title":"ما وقت قيام الليل؟ وما السنة في القراءة فيه؟","answer":"الجواب:  التهجد بالليل سنة، قيام الليل سنة، قال الله في عباد الرحمن في وصفهم: وَالَّذِينَ يَبِيتُونَ لِرَبِّهِمْ سُجَّدًا وَقِيَامًا [الفرقان:64]، وقال الله لنبيه -عليه الصلاة والسلام-: يَا أَيُّهَا الْمُزَّمِّلُ ۝ قُمِ اللَّيْلَ إِلَّا قَلِيلًا ۝ نِصْفَهُ أَوِ انْقُصْ مِنْهُ قَلِيلًا [المزمل:1-3] الآيات،. فالمقصود: أن قيام الليل سنة، وفي الحديث الصحيح أفضل الصلاة قيام الليل يعني: بعد الفريضة أفضلها قيام الليل، التهجد بالليل، وهو مخير، إن شاء صلى في أول الليل، وإن شاء صلى في وسطه، وإن شاء صلى في آخره، لكن الأفضل في آخر الليل إذا تيسر، إذا قدر، فإن خاف أن لا يقوم من آخر الليل فالسنة الإيتار في أول الليل كما تقدم في جواب السؤال السابق، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9285/ما-وقت-قيام-الليل-وما-السنة-في-القراءة-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_368/36803.mp3","categories":["الوتر وقيام الليل"]},{"id":11171,"question":"تقول السائلة سماحة الشيخ: ما هو وقت صلاة التهجد، متى يبدأ ومتى ينتهي مأجورين؟","title":"متى يبدأ وقت صلاة التهجد ومتى ينتهي؟","answer":"الجواب:  يبدأ من بعد صلاة العشاء وينتهي بطلوع الفجر، هذا التهجد، إذا صلى الناس العشاء دخل وقت التهجد إلى طلوع الفجر، فإذا أوتر في أول الليل أو في أثناء الليل أو في آخر الليل كله حسن، كما قال جل وعلا: وَمِنَ اللَّيْلِ فَتَهَجَّدْ بِهِ نَافِلَةً لَكَ [الإسراء:79]، قال جل وعلا: يَا أَيُّهَا الْمُزَّمِّلُ ۝ قُمِ اللَّيْلَ إِلَّا قَلِيلًا [المزمل:1-2]، فالسنة قيام الليل من الفراغ من صلاة العشاء إلى طلوع الفجر، ولو بركعة واحدة وبس، لكن إذا صلى ثلاثًا أو خمسًا أو أكثر يسلم من كل ثنتين هذا هو السنة، وهذا فعله ﷺ. نعم.","link":"https://binbaz.org.sa/fatwas/9342/متى-يبدا-وقت-صلاة-التهجد-ومتى-ينتهي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_290/29018.mp3","categories":["الوتر وقيام الليل"]},{"id":11216,"question":"بعد هذا رسالة وصلت إلى البرنامج من المملكة الأردنية الهاشمية باعثتها إحدى الأخوات تقول: أنا أختكم في الله رحمة من الأردن، أختنا تقول عن نفسها: أنا أحب صلاة قيام الليل، لكن أحيانًا يأخذني النوم وأحيانًا أستيقظ لكني لا أقوم إلا متثاقلة نتيجة للنعاس، فبماذا توجهونني حتى أقوم وأنا في نشاط ورغبة للصلاة ولذكر الله؟","title":"الطرق المعينة على قيام الليل وكيفية قضاء صلاة الليل","answer":"الجواب: نوصيك بالصلاة قبل النوم، النبي ﷺ أوصى بعض أصحابه بالوتر قبل النوم، فإذا كان الإنسان يخاف أن لا يقوم، فالأفضل يصلي ما تيسر قبل النوم، ثلاثًا أو خمسًا أو أكثر، يسلم من كل ثنتين، ثم يوتر بواحدة قبل النوم، أما إذا اطمأننت أنك تقومين آخر الليل فهو أفضل، ونوصيك بالنوم المبكر، أن تنامي مبكرة حتى تقومي آخر الليل، أما مع السهر فيعسر قيام الليل في آخر الليل، ولكن نوصيك بالتبكير بالنوم، ووضع الساعة على الوقت المناسب حتى تقومي، إن شاء الله. فإذا لم يتيسر ذلك فصلي في أوصل الليل، تصلي قبل النوم والحمد لله، وإذا فاتك قيام الليل بسبب النوم أو مرض تصلي من النهار، تصلي الضحى ما تيسر، بعدد الركعات التي تفعلينها في الليل، تصليها من النهار وتزيديها ركعة، تشفعيها، إذا كانت العادة خمسًا تصلي ستًا، ثلاث تسليمات، وإذا كانت العادة سبعًا ولم يتيسر فعلها بالليل للنوم أو غيره تصلي من النهار ثمانًا أربع تسليمات. وهكذا. كان النبي ﷺ إذا شغله عن ورده من الليل نوم أو مرض صلى من النهار، وشفع عادته كما قالت عائشة رضي الله عنها، وكان في الغالب يصلي من الليل احد عشرة ركعة عليه الصلاة والسلام، فإذا شغله نوم أو مرض صلى من النهار ثنتي عشرة ركعة، ست تسليمات، هذا هو السنة، وهذا هو المشروع، وفق الله الجميع. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9412/الطرق-المعينة-على-قيام-الليل-وكيفية-قضاء-صلاة-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_373/37311.mp3","categories":["الوتر وقيام الليل"]},{"id":11242,"question":"في سؤالها الأخير تقول يا سماحة الشيخ: ما هي الأسباب المعينة على قيام الليل؟","title":"ما الأسباب المعينة على قيام الليل؟","answer":"الجواب:  الأسباب التي تعين على قيام الليل كثيرة، منها: تذكر الآخرة، وما لأهل الأجر العظيم، وأن الله أثنى عليهم  في قوله جل وعلا عن الصالحين: كَانُوا قَلِيلًا مِنَ اللَّيْلِ مَا يَهْجَعُونَ ۝ وَبِالأَسْحَارِ هُمْ يَسْتَغْفِرُونَ [الذاريات:17-18]، وذكر عن عباد الرحمن، قال في عباد الرحمن -وهم أولياء الله-: وَالَّذِينَ يَبِيتُونَ لِرَبِّهِمْ سُجَّدًا وَقِيَامًا [الفرقان:64]، فإذا تذكر المؤمن والمؤمنة أعمال هؤلاء كان هذا من أسباب نشاطه في قيام الليل وخشوعه في قيام الليل، مع تذكر ما لهم من الثواب عند الله والأجر العظيم، ومضاعفة الحسنات، نعم.","link":"https://binbaz.org.sa/fatwas/9423/ما-الاسباب-المعينة-على-قيام-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_291/29123.mp3","categories":["الوتر وقيام الليل"]},{"id":11315,"question":"المستمع (أ. ب) من القصيم بعث يسأل ويقول: أريد قيام الليل، ولكني أخشى أن أنام ولا أستيقظ، لذلك فإنني لا أنام حتى أصلي فأصلي صلاة الليل بعد العشاء مباشرة، ومنذ زمن طويل أصلي هذه الصلاة، هل تعتبر كقيام الليل؟","title":"هل الصلاة بعد العشاء مباشرة من قيام الليل؟","answer":"الجواب:  نعم هذا من قيام الليل والحمد لله، وهذا من الحزم، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9500/هل-الصلاة-بعد-العشاء-مباشرة-من-قيام-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_377/37711.mp3","categories":["الوتر وقيام الليل"]},{"id":11603,"question":"يقول عن نفسه سماحة الشيخ: أنا أعمل في محل لبيع الملابس، وصاحب هذا المحل يعترض على صلاة التراويح في المسجد، بحجة أن المحل يغلق كل ذلك الوقت، إذ لم يبع شيئًا طوال تلك الفترة، فهل يجوز أن أصلي وحدي -بعد انتهاء العمل- في البيت؟","title":"حكم صلاة التراويح في المنزل","answer":"الجواب:\n\nصلاة الليل موسع فيها، والحمد لله، يصليها في البيت، أو مع الناس، وإذا كان العمل في وقت التراويح يلزمك أن تعمل، في وقت التراويح؛ لأنك تأخذ أجرة على ذلك، والتراويح نافلة.\n\nفالواجب عليك أن تعمل بالعقد الذي بينك وبين صاحبك، فإذا كان العقد يتضمن أنك تباشر العمل بعد صلاة الفريضة، صلاة العشاء؛ فعليك أن تباشر عملك، إلا بإذنه إذا سمح لك، وفي إمكانك أن تصلي التهجد في الليل في بيتك، والحمد لله.\n\nالمقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9784/حكم-صلاة-التراويح-في-المنزل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_387/38710.mp3","categories":["الوتر وقيام الليل"]},{"id":11630,"question":"هل صلاة الليل والقراءة فيها سرية، أم جهرية؟","title":"حكم الجهر والإسرار في صلاة الليل","answer":"الجواب:  صلاة الليل جهرية؛ وإن أسر؛ فلا بأس؛ النبي ﷺ أسر وجهر كما قالت عائشة -رضي الله عنها- فإذا رأى المصلحة في السر أسر، وإذا رأى المصلحة في الجهر جهر، والجهر أفضل إذا تيسر، وإذا كان السر أخشع لقلبه؛ فلا بأس. نعم.","link":"https://binbaz.org.sa/fatwas/9812/حكم-الجهر-والاسرار-في-صلاة-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_388/38823.mp3","categories":["القراءة في الصلاة","الوتر وقيام الليل"]},{"id":11651,"question":"هل من الممكن قيام الليل بعد الوتر إذا أوتر أول الليل؛ لأنني قرأت في أحد الكتب الإسلامية: أنه لا صلاة بعد الوتر واجعلوا آخر صلاتكم بالليل وترًا؟","title":"حكم التنفل بعد الوتر","answer":"الجواب:  لا حرج في ذلك، السنة أن يختم تهجده بالوتر، لكن لو أوتر في أول الليل، أو قام في آخر الليل، وأوتر، ثم بان له أنه قد بقي ليل؛ فلا بأس أن يصلي، ولا حرج والحمد لله، أن يصلي ما تيسر له بعد الوتر، فالليل كله محل عبادة، ومحل تقرب إلى الله  والنبي ﷺ صلى بعد الوتر، ثبت عنه أنه صلى ركعتين بعد الوتر؛ ليبين للناس جواز ذلك، وأنه لا حرج في ذلك، نعم. \nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/9822/حكم-التنفل-بعد-الوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_389/38909.mp3","categories":["الوتر وقيام الليل"]},{"id":11689,"question":"هل يجوز للإنسان أن يصلي صلاة الليل إذا قام بعد أن صلى الوتر؛ وذلك لخوفه أن ينام فلا يصلي الوتر؟","title":"حكم التهجد آخر الليل لمن صلى الوتر في أوله","answer":"الجواب:  هذا من الحزم كونه يوتر في أول الليل، وإذا قام في آخر الليل؛ صلى ما يسر الله له ركعتين، أو أربع ركعات، أو ست ركعات أو أكثر، كل هذا طيب، لكن يسلم من كل ثنتين؛ لقول النبي ﷺ صلاة الليل مثنى مثنى وقد أوصى النبي ﷺ أبا هريرة، وأبا الدرداء بالوتر قبل النوم، وقال: اجعلوا آخر صلاتكم بالليل وترًا والجمع بين الأحاديث: أن الأفضل لمن استطاع آخر الليل أن يؤخر إلى آخر الليل، ومن خاف ألا يقوم آخر الليل؛ صلى في أول الليل، أخذًا بالحزم، ويدل على هذا حديث صحيح رواه مسلم في صحيحه، عن جابر  عن النبي ﷺ أنه قال: من خاف ألا يقوم من آخر الليل؛ فليوتر أوله، ومن طمع أن يقوم آخر الليل؛ فليوتر آخر الليل، فإن صلاة آخر الليل مشهودة، وذلك أفضل فهذا صريح في التفصيل. فصلاة أول الليل أفضل لمن خاف ألا يقوم من آخر الليل، أما من غلب على ظنه أنه يقوم، واعتاد ذلك؛ فهذا هو الأفضل أن يكون في آخر الليل. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9876/حكم-التهجد-اخر-الليل-لمن-صلى-الوتر-في-اوله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_391/39106.mp3","categories":["الوتر وقيام الليل"]},{"id":11714,"question":"يقول: توجد بعض القرى الصغيرة في صلاة التراويح في شهر رمضان يقوم الإمام بقراءة آية، أو آيتين على الأكثر في كل ركعة، وهناك من يقرأ في كل ركعة قل هو الله أحد في جميع الركعات، فهل صحيحة الصلاة، والحال ما ذكر؟","title":"حكم من يقرأ في التراويح بآية أو آيتين في الركعة","answer":"الجواب: الصلاة صحيحة، لكن الأفضل أنه يقرأ بهم من أول القرآن ما تيسر، وإذا تيسر أنه يختم في رمضان؛ فهو أفضل وأكمل، وأما الإجزاء يجزي إذا قرأ آية، أو آيتين، أو قرأ بعض السور، كل ذلك لا بأس به فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] والله يقول سبحانه: فَاقْرَءُوا مَا تَيَسَّرَ مِنْهُ [المزمل:20] فليس في صلاة التراويح حد محدود في القراءة، بل يقرأ ما تيسر مع الفاتحة. نعم. المقدم: جزاكم الله خيرًا، كونه يقرأ سورة الإخلاص في كل ركعة سماحة الشيخ؟ الشيخ: إذا كان ما عنده غيرها؛ لا حرج، أما إن كان عنده غيرها؛ فالأفضل يقرأ من السور الأخرى، وتكون قُلْ هُوَ اللَّهُ أَحَدٌ في الوتر خاصة تقرأ في الركعة الأخيرة، هذا هو الأفضل. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9890/حكم-من-يقرا-في-التراويح-باية-او-ايتين-في-الركعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_392/39203.mp3","categories":["الوتر وقيام الليل"]},{"id":11716,"question":"سماحة الشيخ! يلجأ بعض الأئمة إلى هذه الطريقة لكونهم لم يحفظوا القرآن الكريم، فهل يجوز أن يقرؤوا من المصحف، ويصلوا بالناس التراويح؟","title":"حكم القراءة من المصحف في صلاة التراويح","answer":"الجواب:  نعم يقرؤون من المصحف، الذي لا يحفظ؛ يقرأ من المصحف، والحمد لله، كان مولى عائشة -رضي الله عنها- يصلي بها من المصحف. المقدم: جزاكم الله خيرًا، إذًا ليس هذا الأمر مبتدعًا، ولا يؤثر في الصلاة. الشيخ: لا حرج في ذلك. المقدم: بارك الله فيكم، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9891/حكم-القراءة-من-المصحف-في-صلاة-التراويح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_392/39204.mp3","categories":["الوتر وقيام الليل","القراءة في الصلاة"]},{"id":11755,"question":"أيهما أفضل تكون صلاة القيام جهرًا، أم سرًا؟","title":"هل الجهر أفضل في صلاة الليل للرجال والنساء؟","answer":"الجواب:  في الليل جهرًا، هذا الأفضل، وإن أسر؛ فلا حرج في ذلك. نعم. المقدم: إذًا صلاة القيام في الليل.. الشيخ: جهرًا، هذا الأفضل، كان النبي ﷺ يجهر وربما أسر كما قالت عائشة -رضي الله عنها- نعم. المقدم: هذا إذا كان في البيت. الشيخ: في البيت، أو في البر في السفر، أو في المسجد يتهجد، أو في التراويح، أو في قيام رمضان في العشر السنة الجهر. المقدم: ما شاء الله، جزاكم الله خيرًا، وأحسن إليكم، هل الحكم شامل للرجال والنساء سماحة الشيخ؟ الشيخ: للجميع النساء والرجال نعم، في البيت والمسجد، لكن المرأة إذا كان عندها أجانب؛ الأفضل السر؛ لأن صوتها قد يفتن بعض الناس؛ فالأفضل السر، وهكذا التلبية إذا كان حولها أجانب الأفضل السر. نعم. المقدم: بارك الله فيكم، بالنسبة للصلوات المفروضة الجهرية هل تجهر المرأة أيضًا؟  الشيخ: في بيتها؟ المقدم: في بيتها نعم. الشيخ: الأفضل تجهر، أما إذا كانت مع الإمام تنصت. المقدم: نعم نعم، أحسن الله إليكم، وجزاكم خير الجزاء.","link":"https://binbaz.org.sa/fatwas/9937/هل-الجهر-افضل-في-صلاة-الليل-للرجال-والنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_393/39318.mp3","categories":["القراءة في الصلاة","الوتر وقيام الليل"]},{"id":11774,"question":"هل صلاة الليل جماعة مشروعة، وما حكم المداومة على ذلك؟ وفقكم الله.","title":"حكم صلاة الليل جماعة والمداومة على ذلك","answer":"الجواب:  صلاة الليل جماعة لا بأس بها، لكن ليست مشروعة يداوم عليها، إلا في التراويح، في رمضان، وأما بقية السنة إذا صادف بعض الأحيان من غير اتخاذ ذلك عادة؛ فلا بأس، كأن يصلي بأهله، أو يزور قومًا، فيصلي معهم جماعة؛ فهذا لا بأس، أما أن يتخذوا ذلك عادة، وسُنة؛ فلا أصل لذلك، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9955/حكم-صلاة-الليل-جماعة-والمداومة-على-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_394/39417.mp3","categories":["الوتر وقيام الليل","صلاة الجماعة"]},{"id":11821,"question":"يسأل سماحتكم -يحفظكم الله- عن صلاة القنوت وكم عدد ركعاتها؟ وما هو وقتها؟الشيخ: نعم.المقدم: عن صلاة القنوت، وعن عدد ركعاتها وما هو وقتها؟الشيخ: أي قنوت؟المقدم: لعله يقصد الوتر سماحة الشيخ.","title":"صلاة الوتر وعدد ركعاتها","answer":"الجواب:  سبحان الله ما يقال: صلاة القنوت، صلاة الليل، صلاة التراويح ما يقال: صلاة القنوت دعاء ... يكون في الركعة الأخيرة هذا يسمى قنوت، الدعاء بعد الركوع في الركعة الأخيرة في الوتر يسمى قنوت، ولا يقال: صلاة القنوت، يقال: صلاة الليل، صلاة التراويح. فالمقصود: صلاة الليل ليس لها حد محدود، إن أوتر بواحدة، أو بثلاث، أو بخمس، أو بأكثر، لكن السنة أنه يسلم من كل ثنتين، ثم يختم بواحدة، يوتر بواحدة، لقول النبي ﷺ: صلاة الليل مثنى مثنى يعني: ثنتين ثنتين فإذا خشي أحدكم الصبح صلى ركعة واحدة توتر له ما قد صلى نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10016/صلاة-الوتر-وعدد-ركعاتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_395/39519.mp3","categories":["الوتر وقيام الليل"]},{"id":11836,"question":"يسأل سماحتكم -يحفظكم الله- عن صلاة القنوت وكم عدد ركعاتها؟ وما هو وقتها؟الشيخ: نعم.المقدم: عن صلاة القنوت، وعن عدد ركعاتها وما هو وقتها؟الشيخ: أي قنوت؟المقدم: لعله يقصد الوتر سماحة الشيخ.","title":"صلاة الوتر وعدد ركعاتها","answer":"الجواب:  سبحان الله ما يقال: صلاة القنوت، صلاة الليل، صلاة التراويح ما يقال: صلاة القنوت دعاء ... يكون في الركعة الأخيرة هذا يسمى قنوت، الدعاء بعد الركوع في الركعة الأخيرة في الوتر يسمى قنوت، ولا يقال: صلاة القنوت، يقال: صلاة الليل، صلاة التراويح. فالمقصود: صلاة الليل ليس لها حد محدود، إن أوتر بواحدة، أو بثلاث، أو بخمس، أو بأكثر، لكن السنة أنه يسلم من كل ثنتين، ثم يختم بواحدة، يوتر بواحدة، لقول النبي ﷺ: صلاة الليل مثنى مثنى يعني: ثنتين ثنتين فإذا خشي أحدكم الصبح صلى ركعة واحدة توتر له ما قد صلى نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10016/صلاة-الوتر-وعدد-ركعاتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_395/39519.mp3","categories":["الوتر وقيام الليل"]},{"id":11858,"question":"بعد هذا رسالة بعثت بها إحدى الأخوات، رمزت إلى اسمها بالحروف (هـ. أ. م) من الرياض، أختنا تسأل عن صلاة الليل، وتسأل هل يجب الملازمة لها، أو لا يجب؟ جزاكم الله خيرًا.","title":"فضائل قيام الليل وبيان بعض أحكامه","answer":"الجواب:  صلاة الليل سنة مؤكدة، ومن فعل النبي ﷺ، قال الله -جل وعلا-: وَمِنَ اللَّيْلِ فَتَهَجَّدْ بِهِ نَافِلَةً لَكَ عَسَى أَنْ يَبْعَثَكَ رَبُّكَ مَقَامًا مَحْمُودًا [الإسراء:79]، وقال في وصف الصالحين من عباد الله: كَانُوا قَلِيلًا مِنَ اللَّيْلِ مَا يَهْجَعُونَ ۝ وَبِالأَسْحَارِ هُمْ يَسْتَغْفِرُونَ [الذاريات:17-18] وقال في صفة عباد الرحمن : وَالَّذِينَ يَبِيتُونَ لِرَبِّهِمْ سُجَّدًا وَقِيَامًا [الفرقان:64].  فالتهجد بالليل سنة وقربة عظيمة، لكن حسب الطاقة، يفعلها الإنسان ..... في أول الليل في أثناء الليل في آخر الليل حسب التيسير، وأقلها واحدة، ركعة واحدة يوتر بها، ويستحب له الزيادة، يصلي ثلاثًا خمسًا سبعًا تسعًا، حسب التيسير، وإذا كان يشق عليه قيام الليل في آخر الليل؛ صلاها قبل أن ينام، كما أوصى النبي ﷺ أبا هريرة، وأبا الدرداء أن يوترا قبل النوم، وإذا تيسر له أن يقوم من آخر الليل؛ فهو أفضل، لقول النبي ﷺ: من خاف ألا يقوم من آخر الليل؛ فليوتر أوله، ومن طمع أن يقوم آخر الليل؛ فليوتر آخر الليل، فإن صلاة آخر الليل مشهودة، وذلك أفضل. والسنة ثنتين ثنتين، ثم يوتر بواحدة، لقوله ﷺ: صلاة الليل مثنى مثنى، وإذا خشي أحدكم الصبح؛ صلى ركعة واحدة توتر له ما قد صلى نعم. المقدم: جزاكم الله خيرًا، إذًا لا يأثم من ترك صلاة الليل؟ الشيخ: لا، لا يأثم سنة. المقدم: سنة، الحمد لله. الشيخ: لو تركها؛ لا شيء عليه، لكن سنة، السنة المحافظة عليها، الله لم يوجب علينا إلا الصلوات الخمس، الظهر والعصر والمغرب والعشاء والفجر والجمعة هذه الفريضة، وما زاد عليها صلاة الضحى التهجد بالليل الرواتب الوتر كلها نافلة. المقدم: بارك الله فيكم، لكنكم تدعون المسلمين.... الشيخ: لكنه ينبغي للمؤمن، يشرع له أن يحافظ على الرواتب، والفضائل، وأن يسارع إلى كل خير، ولا سيما التهجد بالليل والوتر، صلاة متأكدة، وهكذا الرواتب سنة الظهر قبلها أربع، بعدها ثنتين، وإن صلى بعدها أربعًا؛ كان أفضل أيضًا، قبل العصر يستحب له أن يصلي أربعًا، يسلم من كل ثنتين، كذلك بعد المغرب ثنتين، بعد العشاء ثنتين، قبل صلاة الفجر ثنتين كل هذه رواتب، وإذا صلى قبل العشاء ركعتين، قبل المغرب ركعتين؛ كان أفضل أيضًا، بين الأذانين، كل هذه النوافل مستحبة، ينبغي للمؤمن أن يحافظ عليها، وأن يكون حريصًا عليها، يرجو ثواب الله وفضله . المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10053/فضاىل-قيام-الليل-وبيان-بعض-احكامه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_397/39716.mp3","categories":["الوتر وقيام الليل"]},{"id":12011,"question":"يقول: إذا قمت في يوم متأخرًا بعد أذان الصبح، وأنا لم أصل الوتر، هل أصلي السنة، أم الوتر؟","title":"حكم من نام عن الوتر إلى أذان الفجر","answer":"الجواب:  الوتر فات، صل من النهار ما يسّر الله لك، فإذا كنت توتر بثلاث؛ صل في النهار تسليمتين، وإذا كانت عادتك خمس ركعات تصلي في النهار ثلاث تسليمات ست ركعات وهكذا، كان النبي ﷺ إذا فاته وتره من الليل لمرض، أو نوم؛ صلى من النهار ثنتي عشرة ركعة، كما قالت عائشة -رضي الله عنها- وكان وتره في الغالب إحدى عشرة، فإذا فاته ذلك الوتر إما لمرض، أو لنوم؛ صلى من النهار ثنتي عشرة ركعة، يعني: زاد ركعة ست تسليمات، وهكذا السنة لمن فاته ورده من الليل يصليه من النهار، والحمد لله، وإذا قمت بعد طلوع الفجر تصلي سنة الفجر، ثم الفجر، والحمد لله، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10196/حكم-من-نام-عن-الوتر-الى-اذان-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_432/43202.mp3","categories":["الوتر وقيام الليل"]},{"id":12040,"question":"هناك معنى لحديث شريف: من صلى العشاء والقيام وراء الإمام حتى ينصرف؛ كتب له قيام ليلة هل يعني ذلك في رمضان، أو في غيره أيضًا؟ جزاكم الله خيرًا؟","title":"هل يختص رمضان بفضل القيام مع الإمام حتى ينصرف؟","answer":"الجواب:  إذا صلى خلف الإمام في رمضان، لأن هذا ورد في رمضان؛ كتب الله له قيام ليلته، إذا صلى معه حتى ينصرف، فإنه يكتب له قيام ليلته، وهذا فيه تحريض على الجماعة، وترغيب في الجماعة كصلاة التراويح، وصلاة القيام في العشر الأخيرة مع الإمام. أما في بقية الليالي؛ فلا أعلم ما يدل على ذلك، ولكن يرجى لمن صلى مع أخيه في بعض الليالي، أو مع إخيه له صلى معهم جماعة، وأمهم بعضهم، يرجى لهم في ذلك الخير العظيم؛ لأن هذا فيه التعاون على البر والتقوى، فيرجى أن يعمهم الحديث كما لو كان ذلك في رمضان. أما الفريضة كفريضة العشاء هذا فيه نفس الحديث: من صلى العشاء في جماعة؛ كان كمن قام نصف الليل، ومن صلى العشاء والفجر في جماعة؛ فكأنما قام الليل هذا في فضل الجماعة مع وجوبها في فضلها، الجماعة واجبة وفيها فضل عظيم أيضًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10225/هل-يختص-رمضان-بفضل-القيام-مع-الامام-حتى-ينصرف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_433/43309.mp3","categories":["الوتر وقيام الليل"]},{"id":12382,"question":"أحد الإخوة المستمعين بعث يسأل سماحتكم ويقول: كم عدد ركعات صلاة الليل، وهل تكفي الفاتحة في كل ركعة، أم لابد من قراءة شيء من القرآن، وأيضًا هل تصلى جماعة، أم يصلي الواحد بمفرده؟  جزاكم الله خيرًا.","title":"عدد ركعات قيام الليل وصفته","answer":"الجواب:  ليس في صلاة الليل حد محدود، والحمد لله، أقلها ركعة، لو أوتر بواحدة بعد سنة العشاء؛ كفى ذلك، والحمد لله، والأفضل أن يصلي كما صلى النبي ﷺ إحدى عشرة، أو ثلاثة عشرة، يسلم من كل ثنتين إذا تيسر له ذلك، فإن لم يتيسر؛ أوتر بثلاث، أو بخمس، أو بأكثر من ذلك، يسلم من كل ثنتين، هذا هو الأفضل، وإن صلى وحده، أو صلى جماعة مع أهل بيته؛ كله حسن، ولا حرج في ذلك، والحمد لله، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10583/عدد-ركعات-قيام-الليل-وصفته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_401/40102.mp3","categories":["الوتر وقيام الليل"]},{"id":12445,"question":"أيضًا يسأل: هل تكون قراءة القرآن في صلاة التهجد سرًا، أم جهرًا؟","title":"هل الأفضل الجهر أم الإسرار في صلاة التهجد؟","answer":"الجواب:  السنة الجهر، وإن أسر؛ فلا حرج، لكن الأفضل الجهر، جهرًا، لا يؤذي أحدًا، لا يؤذي نوامًا، ولا مصلين، جهرًا خفيفًا، لا يتأذى به أحد، وإن قرأ سرًا لأنه أرفق به؛ فلا بأس، أخبرت به عائشة -رضي الله عنها-: أن النبي ﷺ في صلاة الليل أسر وجهر، عليه الصلاة والسلام. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10652/هل-الافضل-الجهر-ام-الاسرار-في-صلاة-التهجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_403/40317.mp3","categories":["الوتر وقيام الليل","القراءة في الصلاة"]},{"id":12446,"question":"سؤاله الأخير يقول: أرجو أن توجهوني إلى الفرق بين الشفع والوتر في صلاة الليل، وهل يجب لكل نية؟ جزاكم الله خيرًا.","title":"الفرق بين الشفع والوتر في صلاة الليل","answer":"الجواب:  الشفع كونه يصلي ركعتين، والوتر كونه يصلي واحدة، أو ثلاثًا، أو خمسًا، أو سبعًا، جميع هذه يقال لها: وترًا، والشفع كونه يصلي ثنتين تسمى الثنتين شفعًا، وتسمى الأربع: شفعًا، والست شفعًا، لكن السنة أن يسلم من كل ثنتين، ولا يجوز له أن يجمع الأربع والست والثمان بسلام واحد، لكن يسلم من كل ثنتين؛ لقول النبي ﷺ: صلاة الليل مثنى مثنى معناه: تصلي مثنى مثنى، لكن لو سرد ثلاثًا، وترًا، أو خمسًا وترًا؛ فلا بأس يستثنى هذا، وهكذا في النهار تصلي ثنتين ثنتين عنه في الرواية الأخرى : صلاة الليل والنهار مثنى مثنى نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10653/الفرق-بين-الشفع-والوتر-في-صلاة-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_403/40318.mp3","categories":["الوتر وقيام الليل"]},{"id":12481,"question":"المستمع نفسه يسأل ويقول: شيخ عبدالعزيز كيف أقوم الليل؟ وفي أي ساعة بالتحديد؟ علمًا بأنني أنتهي من عملي الساعة العاشرة والنصف في الليل، ثم كم عدد الركعات التي أصليها لقيام الليل بالتفصيل؟ جزاكم الله خيرًا.","title":"ما وقت قيام الليل والأفضل فيه؟","answer":"الجواب:  تقوم من الليل حسب التيسير، ما يسر الله لك تقوم، الأفضل في آخر الليل الثلث الأخيرـ وإذا صليت في وسط الليل، أو في أول الليل كله طيب، وتصلي ثنتين ثنتين، ثم تختم بواحدة، تقرأ فيها الْحَمْدُ [الفاتحة:2] وقُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص:1] وليس في هذا حد محدود، صل ما تيسر لك من ثلاث، خمس، سبع، تسع، إحدى عشر، ثلاثة عشر، هذا أكثر ما فعله النبي ﷺ ثلاثة عشر، وإن صليت أكثر من ذلك عشرين أكثر، وتوتر بواحدة كله طيب. فالمقصود: مثلما قال ﷺ: اكلفوا من العمل ما تطيقون، فإن الله لا يمل حتى تملوا ويقول ﷺ: أحب الأعمال إلى الله ما دام عليه صاحبه، وإن قل ولو قليلًا، بعد صلاة العشاء تصلي واحدة، ركعة واحدة وترًا بعد الراتبة، أو تصلي ثلاثًا، تسلم من ثنتين، ثم تصلي واحدة وترًا، أو تصلي خمسًا، تسلم من كل ثنتين، أو تسردها جميعًا، كله لا بأس، على حسب التيسير، لا تكلف، اتق الله ما استطعت، وهي نافلة، ليست واجبة. والأفضل إذا تيسر لك أن تكون الصلاة في آخر الليل، في الثلث الأخير؛ فهذا أفضل؛ لقوله ﷺ: ينزل ربنا إلى سماء الدنيا كل ليلة حين يبقى ثلث الليل الآخر، فيقول سبحانه: من يدعوني؛ فأستجيب له؟ من يسألني؛ فأعطيه؟ من يستغفرني؛ فأغفر له؟ حتى ينفجر الفجر فإذا تيسر لك آخر الليل؛ فهذا أفضل، ويقول ﷺ: من خاف ألا يقوم في آخر الليل؛ فليوتر أوله، ومن طمع أن يقوم آخر الليل؛ فليوتر آخر الليل، فإن صلاة آخر الليل مشهودة، وذلك أفضل ويقول أبو هريرة : أوصاني رسول الله ﷺ بثلاث: بصلاة ركعتي الضحى، وصيام ثلاثة أيام من كل شهر، وأن أوتر قبل النوم. وهكذا أوصى أبا الدرداء، والسبب -والله أعلم- أنهما كانا يدرسان الحديث في أول الليل، ويخشيان ألا يقوما من آخر الليل، فأوصاهما بالقيام والوتر في أول الليل، أما الذي يطمع في آخر الليل، ويستطيع؛ فهو أفضل، كما تقدم، وفق الله الجميع. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10689/ما-وقت-قيام-الليل-والافضل-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_405/40510.mp3","categories":["الوتر وقيام الليل"]},{"id":12635,"question":"رسالة وصلت إلى البرنامج من ليبيا بعثت بها إحدى الأخوات من هناك، رمزت إلى اسمها بالحروف: (ت. ع. ف) تقول في مقدمة رسالتها: أبعث رسالتي هذه لأحسن برنامج استمعت إليه حتى الآن؛ لما فيه من فائدة عظيمة لي، ولجميع المسلمين في شتى بقاع الأرض، وإنني والله لأدعوه تعالى دائمًا أن ينور قلوبكم، كما تنوروا بعلمكم عقول المسلمين، لدي بعض الأسئلة تقول في أحدها -عن صلاة الوتر-: أنا أصلي ركعات الوتر، وأنام، ثم أقوم في ثلث الليل، وأصلي ركعتين نفلًا، فهل يجوز مثل هذا العمل، أو تنصحونني بتأخير الوتر إلى آخر الليل؟","title":"أفضل أوقات صلاة الوتر","answer":"الجواب:  هذا عمل طيب، إذا كنت يشق عليك القيام من آخر الليل، فقد فعلت أمرًا حسنًا، وهو الإيتار في أول الليل، ثم إذا قمت في آخر من الليل تصلي ركعتين، أو أكثر من ذلك؛ كله طيب، يقول النبي ﷺ في الحديث الصحيح: من خاف ألا يقوم من آخر الليل؛ فليوتر أوله، فإن طمع أن يقوم آخر الليل؛ فليوتر آخر الليل، فإن صلاة آخر الليل مشهودة، وذلك أفضل. فالذي يستطيع الصلاة في آخر الليل؛ يؤخر إلى آخر الليل وهو أفضل؛ لأن الصلاة آخر الليل مشهودة، يشهدها الله وملائكته، أما إن كان لا يستطيع؛ فإنه يوتر أول الليل، وإذا يسر الله له القيام في آخر الليل؛ صلى ما تيسر من دون وتر، كفاه الوتر الأول، صلى ركعتين، أو صلى أربع ركعات بتسليمتين، أو أكثر من ذلك، يسلم من كل ثنتين، ولكن لا يعيد الوتر، يكفيه الوتر الأول، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10845/افضل-اوقات-صلاة-الوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_415/41509.mp3","categories":["الوتر وقيام الليل"]},{"id":12647,"question":"المستمع صبري عبدالله حبيب الجوري فيما يبدو بعث برسالة يسأل فيها عن صلاة الوتر، ويقول: هل يشترط لها تسليمتان، أم تسليمة واحدة تكفي؟","title":"كيفية التسليم بعد صلاة الوتر","answer":"الجواب:  بل تسليمتان مثل بقية الصلوات، نعم، تسليمتان كان النبي ﷺ يسلم تسليمتين في النافلة والفريضة، عليه الصلاة والسلام.  المقدم: إذًا يصلي ركعتين، ويسلم، ثم يأتي بواحدة؟ الشيخ: نعم هذا السنة، هذا الأفضل، وإن سرد الثلاث؛ فلا بأس. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10857/كيفية-التسليم-بعد-صلاة-الوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_457/45717.mp3","categories":["الوتر وقيام الليل"]},{"id":12648,"question":"يسأل عن قضاء صلاة الوتر في النهار، وكيف يكون ذلك؟","title":"كيفية قضاء الوتر في النهار لمن فاته في الليل","answer":"إذا نام الإنسان عن صلاة الوتر، أو نسيها، أو أصابه مرض شغله عنها يصلي من النهار ما تيسر، والأفضل أن يصلي بعددها، لكن لا يوتر، بل يشفع، فإذا كان عادته خمس؛ صلى ست ركعات، يسلم من كل ثنتين، وإذا كان عادته في الليل سبعًا؛ صلى من النهار ثمانًا، يسلم من كل ثنتين، وهكذا.  تقول عائشة -رضي الله عنها-: كان النبي ﷺ إذا شغله نوم، أو مرض عن وتره؛ صلى من النهار ثنتي عشرة ركعة وكانت عادته ﷺ يصلي إحدى عشرة في الليل، فإذا شغل عنها بنوم، أو مرض؛ زاد ركعة، وصلى ثنتي عشرة، يسلم من كل ثنتين -عليه الصلاة والسلام- نعم.","link":"https://binbaz.org.sa/fatwas/10858/كيفية-قضاء-الوتر-في-النهار-لمن-فاته-في-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_457/45718.mp3","categories":["الوتر وقيام الليل"]},{"id":12683,"question":"السؤاليقول: أقدم صلاة آخر الليل إلى بعد صلاة العشاء، أو أؤديها في الحادية عشرة على الأكثر؛ خوفًا أن يغلبني النوم، فهل تعتبر صلاتي صحيحة؟","title":"ما أفضل وقت للتهجد لمن خاف ألا يقوم آخر الليل؟","answer":"الجواب:  نعم نعم، الأفضل أن تؤديها في أول الليل إذا كنت تخشى أن لا تقوم آخر الليل، والنبي ﷺ قال: من خاف ألا يقوم من آخر الليل فليوتر أوله، فإن طمع أن يقوم آخر الليل فليوتر آخر الليل، فإن صلاة آخر الليل مشهودة، وذلك أفضل وأوصى النبي ﷺ أبا هريرة وأبا الدرداء بالوتر أول الليل، وذلك أنهما لا يتيسر لهما القيام في آخر الليل إما لمدارسة الحديث، وإما لأسباب أخرى. فالمقصود: أنك إذا كنت تخشى ألا تقوم من آخر الليل؛ فالوتر لك في أول الليل وهو السنة وهو الأفضل، أما إن طمعت أن تقوم آخر الليل، وتيسر لك ذلك؛ فالتهجد في آخر الليل أفضل، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10893/ما-افضل-وقت-للتهجد-لمن-خاف-الا-يقوم-اخر-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_417/41711.mp3","categories":["الوتر وقيام الليل"]},{"id":12721,"question":"يقول: في شهر رمضان المبارك يصلي إمام مسجدنا صلاة التراويح عشر ركعات طوال شهر رمضان، هل يعتبر صلى النصف، أو أكمل؟","title":"هل لركعات صلاة التراويح عدد محدد؟","answer":"الجواب:  هذا أفضل؛ لأن الرسول ﷺ كان يصلي عشرًا، ويوتر واحدة، في رمضان وفي غيره -عليه الصلاة والسلام- وربما صلى ثلاثة عشر -عليه الصلاة والسلام- وهذا هو الأفضل، إحدى عشرة، أو ثلاث عشرة في رمضان، أو في غيره، وإن صلى أقل أو أكثر؛ فلا حرج. وإن صلوا -كما جاء عن عمر والصحابة- ثلاثًا وعشرين؛ فلا بأس، وإن صلوا أكثر من ذلك؛ فلا بأس، الأمر في هذا واسع، والحمد لله؛ لأن الرسول ﷺ لم يحدد ركعات معلومة -عليه الصلاة والسلام- بل لما سئل عن صلاة الليل قال: مثنى مثنى، فإذا خشي أحدكم الصبح؛ صلى ركعة واحدة توتر له ما قد صلى.  فلم يحدد عشرًا، ولا عشرين؛ فدل ذلك على أن الأمر فيه سعة والحمد لله، فمن صلى عشرًا، وأوتر بواحدة؛ فقد أحسن، ومن أوتر بثلاثة عشر؛ فقد أحسن، ومن أوتر بثلاثة وعشرين؛ فقد أحسن، ومن صلى بأكثر؛ فلا بأس، ولكن أفضلها إحدى عشرة، أو ثلاث عشرة؛ لأن هذا هو الموافق لفعله، عليه الصلاة والسلام. وإن أوتر أحد بأقل من ذلك؛ فلا بأس؛ لأنه ثبت عنه ﷺ أنه ربما أوتر بتسع، ربما أوتر بسبع، ربما أوتر بأقل من ذلك، فهذا كله يدلنا على أن الأمر فيه سعة والحمد لله. أما من يشدد فيقول: لابد أن يتم إحدى عشرة، أو ثلاث عشرة، أو ثلاثة وعشرين، هذا غلط، لا يجوز التشديد في هذا، ولا يحل التشديد في هذا، والله قد وسع فيه . فمن صلى إحدى عشرة، أو ثلاث عشرة؛ تأسيًا بالنبي ﷺ فهذا أفضل، ومن صلى ثلاثة وعشرين؛ لأن جماعته ....... فلا بأس، ومن صلى ثلاثًا وثلاثين، أو تسعة وثلاثين، أو إحدى وأربعين فلا بأس، السلف فعلوا هذا وهذا، فلا حرج في هذا كله، والحمد لله، وإذا وسع الله؛ فوسعوا، ولا ينبغي لأحد أن يشدد في أمر وسع الله فيه. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10934/هل-لركعات-صلاة-التراويح-عدد-محدد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_460/46009.mp3","categories":["الوتر وقيام الليل"]},{"id":12876,"question":"المستمع: فضلي أصيل محمد فضل بعث يسأل ويقول: هل تجوز صلاة الشفع والوتر مع بعض بدون فرق بينهما يعني: كأن أصليها كصلاة المغرب مثلًا؟","title":"هل تجوز صلاة الشفع والوتر كصلاة المغرب؟","answer":"الجواب:\nيكره أن تصلى كصلاة المغرب؛ لأنه جاء في بعض الأحاديث النهي عن ذلك، ولكن يصلي ثنتين ثم يسلم، ثم يصلي الوتر واحدة، هذا هو الأفضل تسليمتين، يصلي ثنتين، أو أكثر، ثم يوتر بواحدة. وإن صلى ثلاثًا جميعًا سردها سردًا، ولم يجلس إلا في آخرها، فلا بأس بذلك فعله النبي ﷺ، يسرد الثلاث سردًا لا يجلس في الثانية، كالمغرب، لا، ولكن يسرد الثلاث سردًا، ثم يجلس في الأخيرة، ويقرأ التحيات، ويصلي على النبي ﷺ ثم يدعو ما يسر الله، ثم يسلم، هذا لا بأس به. ولكن الأفضل أن يسلم من الثنتين ثم يقوم ويأتي بالواحدة وحدها، هذا هو الأفضل، ولو أوتر بخمس، أو بسبع، أو بأكثر كذلك، يسلم من كل ثنتين، ثم يوتر بواحدة، هكذا كان النبي يفعل ﷺ في الغالب كان يسلم من كل ثنتين ثم يوتر بواحدة، وكان في الغالب يصلي إحدى عشرة، وربما صلى ثلاث عشرة ﷺ، وربما صلى ثلاثًا جميعًا سردها سردًا حتى يجلس في آخرها، وربما صلى خمسًا جميعًا، يسردها حتى يجلس في آخرها، كل هذا لا بأس به.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11091/هل-تجوز-صلاة-الشفع-والوتر-كصلاة-المغرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_466/46608.mp3","categories":["الوتر وقيام الليل"]},{"id":12918,"question":"يسأل سؤالًا آخر ويقول: ما هو أفضل وقت لصلاة الوتر، وبماذا تنصحونني؛ لكي أواظب عليها في منتصف الليل؛ لأنني أصبحت لا أؤديها إلا بعد صلاة العشاء؟","title":"أفضل وقت لصلاة الوتر","answer":"الجواب: الأفضل لمن قدر أن يكون ذلك آخر الليل هذا هو الأفضل، أن يصلي صلاة الوتر، والتهجد في آخر الليل في الثلث الأخير؛ لما ثبت عن رسول الله -عليه الصلاة والسلام- أنه قال: ينزل ربنا إلى سماء الدنيا كل ليلة حين يبقى ثلث الليل الآخر، فيقول: من يدعوني فأستجيب له؟ من يسألني فأعطيه؟ من يستغفرني فأغفر له حتى ينفجر الفجر متفق على صحته، وهو حديث عظيم يدل على أنه -جل وعلا- ينزل إلى سماء الدنيا كل ليلة حين يبقى الثلث الأخير في كل جهة من الجهات على حسب أوقاتهم، فيقول : من يدعوني فأستجيب له؟ من يسألني فأعطيه؟ من يستغفرني فأغفر له؟ فإذا استطاع المؤمن والمؤمنة أن يكونا في هذا الوقت من المصلين، والداعين فهذا هو الأفضل. ونزول الرب -جل وعلا- لا يشابه نزول المخلوقين، بل هو نزول يليق بالله  لا يعلم كيفيته إلا هو -جل وعلا- ولا يلزم منه خلو العرش، فهو فوق العرش  فوق جميع الخلق، وينزل نزولًا يليق بجلاله، لا ينافي علوه وفوقيته  فهو نزول يليق به -جل وعلا- وهو الذي يعلم كيفيته  فعلينا أن نؤمن بذلك، وأن نصدق بذلك، ونقول لا يعلم كيفية هذا إلا هو .  وهكذا بقية الصفات نعلمها ونمرها كما جاءت، ولكن لا يعلم كيفيتها إلا هو  كالاستواء على العرش، النزول، والمجيء يوم القيامة لفصل القضاء بين عباده، وكذلك رحمته وغضبه، كيف يرحم؟ وكيف يغضب؟ كيف سمعه؟ كيف بصره؟ كيف يده؟ كيف قدمه؟ كلها صفات لله، لا نعلم كيفيتها، بل لا يعلم كيفيتها إلا هو . ولهذا لما سئل الإمام مالك بن أنس -رحمه الله- إمام المدينة في زمانه في القرن الثاني، سئل -رحمه الله- قال له السائل: يا أبا عبدالله: الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى [طه:5] كيف استوى؟ فأطرق طويلًا، وعلته الرحضاء تعظيمًا لهذا السؤال لخطورته -والرحضاء: العرق- ثم قال: الاستواء معلوم، والكيف مجهول، والإيمان به واجب، والسؤال عنه بدعة، وما أراك إلا رجل سوء، ثم أمر به فأخرج.  فالمقصود: أنه قال: الاستواء معلوم، والكيف مجهول، وهذا هو قول أهل السنة والجماعة جميعًا، كما قال مالك -رحمه الله- قاله الأئمة غيره: كـأبي حنيفة، والشافعي، والأوزاعي، والثوري، وابن عيينة، وأحمد بن حنبل، وإسحاق بن راهويه، وغيرهم من أئمة الإسلام، وهو مروي عن أم سلمة -رضي الله عنها- أم المؤمنين، وهو أيضًا قول ربيعة بن أبي عبدالرحمن شيخ مالك، فإنه قال معنى هذا الكلام، وهو قول الأئمة جميعًا من أهل السنة والجماعة. الاستواء معلوم، والكيف مجهول، والإيمان به واجب، والسؤال عن الكيفية بدعة، وهكذا القول في بقية الصفات، كالنزول والرحمة، والغضب، والسمع، والبصر، واليد، والقدم، والأصابع، وغير هذا، كلها يقال فيها: إنها معلومة من جهة المعنى، ومن جهة اللغة العربية، ولكن كيفيتها لا يعلمها إلا هو .  وفي هذا الحديث الدلالة على شرعية التهجد في آخر الليل، والدعاء في آخر الليل، لكن من لم يستطع؛ فإنه يوتر في أول الليل، من لم يستطع ذلك؛ فالسنة له أن يوتر في أول الليل، أو في وسط الليل حسب طاقته؛ لما ثبت عن رسول الله -عليه الصلاة والسلام- أنه قال: من خاف ألا يقوم من آخر الليل؛ فليوتر أوله، ومن طمع أن يقوم آخر الليل؛ فليوتر آخر الليل؛ فإن صلاة آخر الليل مشهودة، وذلك أفضل. فصل في هذا -عليه الصلاة والسلام- فمن طمع أن يقوم آخر الليل؛ فهو أفضل، ومن خاف؛ أوتر في أول الليل. وقد فعل ﷺ هذا وهذا وهذا، قالت عائشة -رضي الله عنها-: من كل الليل قد أوتر الرسول ﷺ من أوله، وأوسطه، وآخره، ثم انتهى وتره إلى السحر يعني: استقر وتره في الثلث الأخير -عليه الصلاة والسلام- نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11133/افضل-وقت-لصلاة-الوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_469/46903.mp3","categories":["الوتر وقيام الليل"]},{"id":13058,"question":"تقول: حدثونا -يا سماحة الشيخ- عن فضل قيام الليل، ومتى يكون نزول الله  إلى السماء الدنيا بالساعة تقريبًا؟","title":"فضل قيام الليل","answer":"الجواب: التهجد بالليل سنة، وقربة، وأفضله آخر الليل، أفضله السدس الرابع والخامس، يقول النبي ﷺ: أفضل الصلاة صلاة داود، كان ينام نصف الليل، ويقوم ثلثه، وينام سدسه ويقول -عليه الصلاة والسلام-: ينزل ربنا إلى السماء الدنيا كل ليلة حين يبقى ثلث الليل الآخر، فيقول: من يدعوني؛ فأستجيب له، من يسألني؛ فأعطيه، من يستغفرني؛ فأغفر له. فالسنة للمؤمن أن يتحرى هذين الوقتين: الربع الخامس والربع السادس، في الربع الرابع، والربع الخامس الذي هو صلاة داود: ينام نصف الليل، ويقوم ثلثه يعني: السدس الرابع، والسدس الخامس، وينام السدس الأخير، يتقوى على أعمال النهار، وإن تعبد في الثلث الأخير وقت التنزل، يعني: السدس الخامس والسادس كذلك، كله طيب. والنصف يبدأ بالساعة، يمضي نصف الساعة التي يوافي الليل، الليل يختلف على حسب ساعات الليل، فإذا كان الليل اثنا عشر؛ بدأ النصف في أول الساعة السابعة بعد غروب الشمس، وإذا كان الليل إحدى عشر؛ بدأ بعد مضي خمس ساعات ونصف من غروب الشمس، بدأ النصف وهكذا. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11275/فضل-قيام-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_505/50518.mp3","categories":["الوتر وقيام الليل"]},{"id":13079,"question":"سماحة الشيخ! إذا نوى الشخص، سواء كان الرجل، أو المرأة أن يقوم الليل، ولم يقم، فهل يكتب له أجر ما نوى؟","title":"حكم من نوى قيام الليل ثم عجز عن ذلك","answer":"الجواب:  نعم، يقول النبي ﷺ: إذا مرض العبد، أو سافر كتب الله له ما كان يعمل وهو صحيح مقيم كذلك إذا نام ما فرط، له أجر قيام الليل، لكن يصلي من النهار، يصلي ما فاته، كان النبي ﷺ إذا منعه من ورده بالليل نوم أو مرض؛ صلى من النهار مقابل ما يفعله بالليل، هذا هو السنة، فإذا شغله المرض أو النوم عن وتره بالليل، وعن حزبه بالليل من القراءة فعله بالنهار قبل الظهر هذا هو الأفضل، ويكون أجره كاملًا. ويقول ﷺ -أيضًا- في غزوة تبوك: إن في المدينة أقوامًا  يقول لأصحابه في تبوك: إن في المدينة أقوامًا ما سرتم مسيرًا، ولا قطعتم واديًا إلا وهم معكم وفي لفظ: إلا شركوكم في الأجر قالوا: يا رسول الله! وهم في المدينة؟ قال: وهم في المدينة حبسهم المرض وفي اللفظ الآخر: حبسهم العذر. فالمقصود: أن الذي يحبسه العذر عن عمل صالح وهو ينويه، أو من عادته فعله يكون له أجر. المقدم: جزاكم الله خيرًا يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11296/حكم-من-نوى-قيام-الليل-ثم-عجز-عن-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_507/50711.mp3","categories":["الوتر وقيام الليل"]},{"id":13323,"question":"السائل في آخر أسئلته يقول: هل تصح صلاة الوتر بتشهد واحد؟ أم لازم علي أن آتي بالتشهد بعد الركعتين الأوليين، ثم أكمل بعد الثالثة؟","title":"حكم صلاة الوتر ثلاث ركعات بتشهد واحد","answer":"الجواب: السنة في التهجد بالليل السلام من كل ثنتين، هذا هو السنة؛ لقوله ﷺ: صلاة الليل مثنى مثنى رواه الشيخان البخاري ومسلم في الصحيحين، فإذا أراد الوتر؛ أوتر بواحدة مفردة قبل الفجر، يقرأ فيها بالفاتحة وقُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص:1] هذا هو السنة، وإن أوتر بثلاث سردها هذا هو السنة، لا يجلس في الثانية، بل يسردها كما جاء عن النبي ﷺ ونهى النبي ﷺ عن تشبيهها بالمغرب، تشبيه الوتر بالمغرب؛ لكن يسردها لا يجلس بعد الثانية، بل يسرد الثلاث ويجلس في الأخيرة، ويتشهد في الأخيرة إذا أوتر بثلاث، ولكن كونه يسلم من الثنتين، ويوتر بواحدة مفردة يكون هذا هو الأفضل، والأكمل؛ لأن هذا هو الغالب من فعل النبي ﷺ. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/11609/حكم-صلاة-الوتر-ثلاث-ركعات-بتشهد-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_541/54105.mp3","categories":["الوتر وقيام الليل"]},{"id":13362,"question":"يقول: ما حكم صلاة التراويح في رمضان بالنسبة للرجل المنفرد في بيته؟ وما عدد ركعاتها؟ جزاكم الله خيرًا.","title":"حكم صلاة التراويح في البيت وعدد ركعاتها","answer":"الجواب: قيام رمضان سنة في المساجد، يقول ﷺ: من قام رمضان إيمانًا واحتسابًا؛ غفر له ما تقدم من ذنبه كونه يقوم رمضان مع إخوانه في المساجد أفضل، وإن صلى في البيت؛ فلا حرج.  وليس لها حد محدود، لكن الأفضل إحدى عشرة أو ثلاثة عشرة، هذا الأفضل، وإن صلى أكثر؛ عشرين والوتر، ثلاثين والوتر، أربعين والوتر، ما في حرج الحمد لله، لكن أفضلها هو ما فعله النبي ﷺ إحدى عشرة، أو ثلاث عشرة، هذا أكثر ما ورد عنه ﷺ يسلم من كل ثنتين ويوتر بواحدة، هذا هو الأفضل، سواء صلاها في أول الليل، أو في وسط الليل، أو في آخر الليل، أو فرقها صلى بعضها في أوله وبعضها في وسطه، أو بعضها في أوله وبعضها في آخره، كل هذا لا حرج فيه. وهكذا في المساجد إذا صلوها جميعًا في أول الليل، أو صلوها في آخر الليل، أو بعضها في أول الليل، وبعضها في آخر الليل، كل هذا -بحمد الله- لا حرج فيه، الأمر موسع؛ لأن الرسول ﷺ ما شرط شيئًا قال: من قام رمضان ولما دخلت العشر أحياها كلها -عليه الصلاة والسلام- فالأمر في هذا واسع، إذا أحيا العشر كلها إحياء من أولها إلى آخرها؛ فهذا أفضل، وإن استراح بينها؛ فلا بأس، وإذا صلى التراويح في أول الليل، أو اتفقوا على أن يصلوها في آخر الليل، كل ذلك لا بأس به، الحمد لله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11649/حكم-صلاة-التراويح-في-البيت-وعدد-ركعاتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_524/52405.mp3","categories":["الوتر وقيام الليل"]},{"id":13384,"question":"هل صلاة الوتر.. هل القراءة فيها جهرية، أم سرية؟","title":"هل القراءة في صلاة الوتر جهرية؟","answer":"الجواب: جهرية، إلا إذا صلاها في النهار، إذا فاته في الليل، وصلى في النهار بدلًا من صلاة الليل؛ يسر؛ لأن صلاة النهار سرية، إلا صلاة الفجر فإنها جهرية، وصلاة الجمعة جهرية، وصلاة الكسوف والاستسقاء جهرية، أما صلاة الوتر إذا قضاها؛ فإنه يقضيها غير جهرية، كما يصلي صلاة الضحى غير جهرية، والرواتب مثل الظهر غير جهرية، السنة قبل العصر غير جهرية، لكن لا يصلي وترًا، إذا فاته وتره من الليل؛ يصلي شفعًا، هذا السنة، فإذا كان يصلي خمسًا بالليل، وفاته بسبب النوم، يصلي ستًا في النهار ثلاث تسليمات، وإذا كان وتره سبعًا، صلى أربع تسليمات وهكذا. نعم. المقدم: جزاكم الله خيرًا، والحكم واحد بالنسبة للرجال والنساء؟ الشيخ: الحكم واحد للرجال والنساء، تقول عائشة -رضي الله عنها-: \"كان النبي ﷺ إذا نام عن ورده من الليل، أو شغله عنه مرض؛ صلى من النهار ثنتي عشرة ركعة، وكان وتره في الغالب إحدى عشر -عليه الصلاة والسلام-\" إحدى عشرة، نعم. المقدم: من حيث الجهرية والسرية بالنسبة....؟ الشيخ: نعم، نعم، للرجال والنساء. نعم. المقدم: للرجال والنساء؟ الشيخ: نعم. المقدم: أيضًا المرأة لها أن تجهر؟ الشيخ: تجهر في المغرب والعشاء والفجر. المقدم: تجهر. الشيخ: تجهر في الأولى والثانية من المغرب، والأولى والثانية من العشاء كالرجل.. وتجهر في الفجر كذلك، نعم. المقدم: هل لذلك من شرط معين؟ الشيخ: ما فيه شرط إلا إذا كان هناك رجال أجانب تخفض صوتها. المقدم: تخفض صوتها. الشيخ: نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11673/هل-القراءة-في-صلاة-الوتر-جهرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_477/47705.mp3","categories":["الوتر وقيام الليل","القراءة في الصلاة"]},{"id":13427,"question":"من قام مع إمامه في صلاة التراويح، ولم يقم معه في التهجد آخر الليل، هل يعتبر له قيام ليلة كاملة؟","title":"من اكتفى بالتراويح مع الإمام هل يكتب له قيام ليلة؟","answer":"الجواب: من قام مع الإمام حتى ينصرف؛ كتب الله له قيام ليلة، إذا كان إمامه أوتر بهم، صلى بهم في أول الليل، وأوتر بهم له قيام الليل، وإن صلى مع من يصلي في آخر الليل زيادة؛ فلا بأس، لكن لا يوتر وترين، إذا أوتر مع الأول لا يوتر مع الثاني، يصلي ما تيسر، ولكن لا يوتر، إذا أوتر الثاني؛ يصلي معه، ويأتي بشفع يشفعها بركعة؛ لقوله ﷺ: لا وتران في ليلة هكذا قال ﷺ.  فإذا أوتر مثلًا في الحرم، أو في غير الحرم مع الذي صلى في الأول فإنه إذا أوتر مع الأول إن كان الأول أوتر، وإن كان ما أوتر الحمد لله، لكن إذا أوتر الأول، وأوتر معه؛ فلا يوتر مع الثاني، لكن يصلي مع الثاني ما تيسر، ولا يوتر معه، فإن أوتر معه الركعة الأخيرة؛ شفعها بركعة؛ لقول النبي ﷺ: لا وتران في ليلة.  المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11721/من-اكتفى-بالتراويح-مع-الامام-هل-يكتب-له-قيام-ليلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_527/52704.mp3","categories":["الوتر وقيام الليل"]},{"id":13517,"question":"تقول السائلة: في صلاة التراويح، وبعد أن يصلي الإمام الوتر، وعند السلام لا نسلم معه، بل نقوم ونصلي ركعة إضافية حتى لا يكون وترًا؛ لأننا نرغب في تأخير الوتر إلى بعد النوم، فأيهما أفضل متابعة الإمام، أو تأخير الوتر؟","title":"هل الأفضل السلام مع الإمام حتى ينصرف في قيام رمضان","answer":"الجواب: الأمر واسع في هذا، من تابع فهو أفضل، صلى معه حتى يكون له أجر ما فعل مع الإمام حتى ينصرف، ومن أتى بركعة، وشفع بها وتره، وأوتر في آخر الليل؛ فالأمر واسع -بحمد الله- وإن سلم معه فلعله أفضل، إن شاء الله. ثم هو يصلي بعد ذلك ما تيسر من دون وتر، يصلي ركعتين .. يصلي أربعًا .. ثمانًا أكثر أقل يسلم من كل ركعتين، وليس هناك حاجة للوتر؛ لقول النبي ﷺ: لا وتران في ليلة لكن يصلي ما تيسر، يسلم من كل ثنتين، والحمد لله، وأما سلامه فيكون مع الإمام يكون أفضل، وأبعد عن الرياء. المقدم: طيب جزاكم الله خيرًا سماحة الشيخ عبد العزيز .","link":"https://binbaz.org.sa/fatwas/11834/هل-الافضل-السلام-مع-الامام-حتى-ينصرف-في-قيام-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_531/53111.mp3","categories":["الوتر وقيام الليل"]},{"id":13520,"question":"تقول السائلة: في صلاة التراويح، وبعد أن يصلي الإمام الوتر، وعند السلام لا نسلم معه، بل نقوم ونصلي ركعة إضافية حتى لا يكون وترًا؛ لأننا نرغب في تأخير الوتر إلى بعد النوم، فأيهما أفضل متابعة الإمام، أو تأخير الوتر؟","title":"هل الأفضل السلام مع الإمام حتى ينصرف في قيام رمضان","answer":"الجواب: الأمر واسع في هذا، من تابع فهو أفضل، صلى معه حتى يكون له أجر ما فعل مع الإمام حتى ينصرف، ومن أتى بركعة، وشفع بها وتره، وأوتر في آخر الليل؛ فالأمر واسع -بحمد الله- وإن سلم معه فلعله أفضل، إن شاء الله. ثم هو يصلي بعد ذلك ما تيسر من دون وتر، يصلي ركعتين .. يصلي أربعًا .. ثمانًا أكثر أقل يسلم من كل ركعتين، وليس هناك حاجة للوتر؛ لقول النبي ﷺ: لا وتران في ليلة لكن يصلي ما تيسر، يسلم من كل ثنتين، والحمد لله، وأما سلامه فيكون مع الإمام يكون أفضل، وأبعد عن الرياء. المقدم: طيب جزاكم الله خيرًا سماحة الشيخ عبد العزيز .","link":"https://binbaz.org.sa/fatwas/11834/هل-الافضل-السلام-مع-الامام-حتى-ينصرف-في-قيام-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_531/53111.mp3","categories":["الوتر وقيام الليل"]},{"id":13557,"question":"يقول: هل يأثم من ترك ركعتين قبل الفجر؟ وصلاة الوتر؟ جزاكم الله خيرًا.","title":"هل يأثم من ترك الرواتب وصلاة الوتر؟","answer":"الجواب: جميع السنن لا يأثم فيها، سنة الفجر، وسنة الظهر والمغرب والعشاء، وسنة الجمعة كلها نوافل، لكن ترك الأفضل، فوت أجرًا كبيرًا، وإلا لا إثم عليه في جميع النوافل الرواتب وغيرها. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11895/هل-ياثم-من-ترك-الرواتب-وصلاة-الوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_532/53217.mp3","categories":["صلاة التطوع","الوتر وقيام الليل"]},{"id":13558,"question":"يقول: هل يجوز الوتر في جماعة؟","title":"هل يجوز صلاة الوتر جماعة؟","answer":"الجواب: إذا تيسر لا بأس، لكن من غير ترتيب، إذا تيسر زارهم، فصلوا جماعة وترًا، أو زاروه لا بأس، فقد زار سلمان  أبا الدرداء  في بعض الليالي وصلوا جماعة، زار النبي ﷺ بيت عتبان بن مالك في بعض الأيام وصلوا جماعة، وزار جدة أنس بن مالك وصلوا جماعة. فإذا كان لشيء عارض عند الزيارات؛ فلا بأس، أو اجتمعوا فرأوا أن يصلوا ركعتين لا بأس، أما اتخاذ هذا راتبًا؛ فهذا غير مشروع إلا في رمضان.. إلا قيام رمضان. نعم.. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/11902/هل-يجوز-صلاة-الوتر-جماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_532/53219.mp3","categories":["الوتر وقيام الليل","صلاة الجماعة"]},{"id":13609,"question":"في سؤاله الثاني يقول سماحة الشيخ: عندما نصلي المغرب والعشاء جمعًا، هل نصلي الوتر مباشرة، أم لا؟","title":"هل يصلى الوتر بعد العشاء إذا جُمعت مع المغرب؟","answer":"الجواب: نعم، إذا صلى المسلمون العشاء مع المغرب جمعًا للمطر، أو الوحل، أو صلى المسلم العشاء مع المغرب للمرض، أو للسفر؛ فإنه يصلي بعدها الوتر، يصلي سنة المغرب، ثم يصلي سنة العشاء، ثم يصلي الوتر ويتهجد، وإن كان في البلد يصلي التراويح إذا جمعوا لأجل مشقة المطر، أو الوحل والطين، إذا صلوا العشاء مع المغرب مقدمًا صلوا بعدها التراويح، والحمد لله. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11948/هل-يصلى-الوتر-بعد-العشاء-اذا-جمعت-مع-المغرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_528/52803.mp3","categories":["الوتر وقيام الليل"]},{"id":13785,"question":"أعرض عليكم عملي هذا وأرجو أن توجهوني: إنني أصلي العشاء ثم أصلي بعده ركعتين، ثم أصلي ركعتين بتسليمة واحدة، ثم أصلي ركعة وأرفع يدي وأدعو بصوت مرتفع قليلًا، هل ما أفعله صحيح؟","title":"حكم رفع المرأة صوتها في دعاء الوتر","answer":"","link":"https://binbaz.org.sa/fatwas/12139/حكم-رفع-المراة-صوتها-في-دعاء-الوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_481/48122.mp3","categories":["القنوت في الصلاة","الوتر وقيام الليل"]},{"id":13845,"question":"يسأل أخونا ويقول: نهى النبي ﷺ عن تخصيص ليلة أو يوم بعبادة خاصة، ونحن الشباب نريد أن نجتمع ليلة الجمعة أو ليلة من ليالي الأسبوع فنحييها بقيام الليل لا اعتقادًا بسنية هذا العمل بل لتشجيع الشباب على قيام الليل، فما حكم الصلاة؟","title":"حكم الاجتماع لصلاة الليل","answer":"الجواب: لا حرج في ذلك لكن لا تخصوا ليلة، تارة ليلة الجمعة، وتارة ليلة الخميس حسب التيسير متى تيسر ذلك، أما تخصيص ليلة فلا يجوز؛ لأنه بدعة، فخصوص ليلة الجمعة الرسول ﷺ نهى عن تخصيصها بالقيام كما نهى عن تخصيص نهارها بالصيام، ولكن إذا صادف أحدكم زيارة إخوانه أو زاروه وصلوا جميعًا لا بأس، مثلما فعل النبي ﷺ لما زار عتبان صلى بهم ركعتين، ولما زار أنس صلى بهم ركعتين، وهكذا سلمان لما زار أبا الدرداء صلى معه في الليل لا بأس، أما تخصيص ليلة تجتمعون فيها للصلاة هذا لا أصل له، إنما لا مانع من الصلاة عند الاجتماع إذا اجتمعتم من غير تحديد وقت معين يدوم فلا بأس، إذا زار أحدكم أخاه أو اجتمعتم في مجلس من غير أن يكون ذلك معتادًا، ثم صلى أحدكم بالحاضرين للتعليم هذا كله لا بأس به. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12216/حكم-الاجتماع-لصلاة-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_602/60214.mp3","categories":["الوتر وقيام الليل"]},{"id":13852,"question":"في ثاني أسئلة هذا السائل يقول: ما حكم القنوت في صلاة الوتر؟ وهل يجب علي شيء إذا تركته؟","title":"حكم القنوت في الوتر وهل على من تركه شيء؟","answer":"الجواب:","link":"https://binbaz.org.sa/fatwas/12229/حكم-القنوت-في-الوتر-وهل-على-من-تركه-شيء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_537/53724.mp3","categories":["الوتر وقيام الليل","القنوت في الصلاة"]},{"id":13907,"question":"هذا سائل أرسل بمجموعة من الأسئلة السائلة أختكم في الله سمية علي من السودان تقول في هذا  ما هي الأسباب التي تعين الإنسان على قيام الليل؟ جزاكم الله خيرًا.","title":"ما الأسباب التي تعين الإنسان على قيام الليل؟","answer":"الجواب: الأسباب التي تعين الإنسان على قيام الليل كثيرة منها: فإذا اتخذ الأسباب يسر الله أمره، وأهمها الصدق مع الله والإخلاص في هذا وعدم السهر. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12302/ما-الاسباب-التي-تعين-الانسان-على-قيام-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_538/53819.mp3","categories":["نصائح وتوجيهات","الوتر وقيام الليل"]},{"id":13910,"question":"هذا سائل أرسل بمجموعة من الأسئلة السائلة أختكم في الله سمية علي من السودان تقول في هذا  ما هي الأسباب التي تعين الإنسان على قيام الليل؟ جزاكم الله خيرًا.","title":"ما الأسباب التي تعين الإنسان على قيام الليل؟","answer":"الجواب: الأسباب التي تعين الإنسان على قيام الليل كثيرة منها: فإذا اتخذ الأسباب يسر الله أمره، وأهمها الصدق مع الله والإخلاص في هذا وعدم السهر. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12302/ما-الاسباب-التي-تعين-الانسان-على-قيام-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_538/53819.mp3","categories":["نصائح وتوجيهات","الوتر وقيام الليل"]},{"id":13917,"question":"هذه رسالة وصلت من مستمع للبرنامج يقول: من نام عن صلاة الوتر ولم يذكر ذلك إلا بعد صلاة الظهر كيف يقضيها؟","title":"كيفية قضاء صلاة الوتر","answer":"الجواب: يقضيها شفعًا، كان النبي ﷺ إذا فاته ورده من الليل لمرض أو نوم قضاه من النهار شفعًا، كما قالت عائشة رضي الله عنها، يعني إذا كانت عادته ثلاثًا يصلي من النهار أربع تسليمتين، وإذا كان عادته في الليل يوتر بخمس صلى من النهار ست ركعات، يسلم من كل ثنتين، وإذا كان عادته إحدى عشر كالنبي ﷺ صلى من النهار اثنا عشر، ست تسليمات كما كان النبي يفعل عليه الصلاة والسلام، هذا هو الأفضل، وإذا لم يتيسر الضحى وصلاه بعد الظهر فلا بأس، لكن الأفضل أن يكون قبل الظهر. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12327/كيفية-قضاء-صلاة-الوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_544/54413.mp3","categories":["الوتر وقيام الليل","قضاء الفوائت"]},{"id":13922,"question":"من الأردن أخوكم في الله (م. ر. ع) يقول: سماحة الشيخ! الصلاة بعد أذان الفجر الأول هل تعتبر صلاة قيام ليل؟ وهل هناك أذان أول وأذان ثاني لصلاة الفجر؟ وهل قيام الليل يبدأ من بعد صلاة العشاء إلى أذان الفجر أو من منتصف الليل، مأجورين؟","title":"وقت قيام الليل","answer":"الجواب: قيام الليل يبتدي من نهاية صلاة العشاء، ما بين صلاة العشاء إلى طلوع الفجر هذا قيام الليل، وإذا كان في آخر الليل في النصف الأخير أو في الثلث الأخير يكون أفضل، مثلما جاء في الحديث الصحيح يقول النبي ﷺ: أفضل الصيام صيام داود؛ كان يصوم يومًا ويفطر يومًا، وأفضل الصلاة صلاة داود؛ كان ينام نصف الليل ويقوم ثلثه وينام سدسه يعني يصلي السدس الرابع والسدس الخامس، ينام نصف الليل ويقوم ثلثه السدس الرابع والسدس الخامس.\nوإذا قام في الثلث الأخير كان ذلك فيه فضل عظيم، لقوله ﷺ في الحديث الصحيح: ينزل ربنا إلى السماء الدنيا كل ليلة حين يبقى ثلث الليل الآخر، فيقول: من يدعوني فأستجيب له، من يسألني فأعطيه، من يستغفرني فأغفر له.. حتى ينفجر الفجر وهذا نزول يليق بالله، لا يشابه خلقه في نزولهم، بل هو نزول يليق بالله لا يعلم كيفيته إلا هو ، كالاستواء على العرش وهو الارتفاع فوق العرش استواء يليق بجلال الله لا يشابه خلقه في شيء من صفاته، ولهذا يقول أهل العلم: استوى بلا كيف.\nفالمؤمن يؤمن بصفات الله وأسمائه على الوجه اللائق بالله جل وعلا، من غير تحريف ولا تعطيل ولا تكييف ولا تمثيل، ولهذا يقول مالك وغيره من السلف كـالشافعي والإمام أحمد بن حنبل والثوري والأوزاعي وغيرهم يقولون: نؤمن بأن ربنا فوق سماواته على عرشه قد استوى عليه بلا كيف .\nفالإنسان يقوم مما تيسر من الليل في أوله أو في وسطه أو في آخره يتهجد.. يصلي ما تيسر.. يدعو ربه.. يلجأ إليه.. يضرع إليه، ويسلم من كل ثنتين، لقوله ﷺ: صلاة الليل مثنى مثنى، فإذا خشي أحدكم الصبح صلى ركعة واحدة توتر له ما قد صلى.\nوالأفضل إحدى عشرة أو ثلاثة عشرة، هذا أكثر ما ورد عن النبي ﷺ في صلاة الليل، إحدى عشر ركعة أو ثلاثة عشر ركعة، يسلم من كل ثنتين ويوتر بواحدة قبل طلوع الفجر.\nوإن صلى أكثر من ذلك فلا بأس أو أقل بأن صلى ثلاثًا أو خمسًا أو سبعًا كل ذلك لا بأس، لكن السنة أن يسلم من كل ثنيتن ويوتر بواحدة، وإن سرد ثلاثًا بسلام واحد ولم يجلس إلا في آخرها فلا بأس، أو سرد خمسًا بسلام واحد ولم يجلس إلا في آخرها فلا بأس، لكن الأفضل أن يسلم من كل ثنتين، سواء في أول الليل أو في وسطه أو في آخره.\nوإذا كان له شغل في أول الليل.. دراسة العلم ونحو ذلك فإنه يوتر في أول الليل حتى لا ينام عن وتره، كما كان أبو هريرة  أوصاه النبي ﷺ بأن يوتر في أول الليل؛ لأنه كان يدرس العلم في أول الليل.\nالمقصود أن الإنسان اللي يخشى أن لا يقوم من آخر الليل يوتر أول الليل؛ لقول النبي ﷺ: من خاف أن لا يقوم من آخر الليل فليوتر أول الليل، ومن طمع أن يقوم آخر الليل فليوتر آخر الليل، فإن صلاة آخر الليل مشهودة وذلك أفضل أخرجه مسلم في صحيحه، فالتهجد في أول الليل أو في وسطه أو في آخره كله طيب، ولكن الأفضل في آخر الليل إذا تيسر ذلك. نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12314/وقت-قيام-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_544/54406.mp3","categories":["الوتر وقيام الليل"]},{"id":13925,"question":"هذه رسالة وصلت من مستمع للبرنامج يقول: من نام عن صلاة الوتر ولم يذكر ذلك إلا بعد صلاة الظهر كيف يقضيها؟","title":"كيفية قضاء صلاة الوتر","answer":"الجواب: يقضيها شفعًا، كان النبي ﷺ إذا فاته ورده من الليل لمرض أو نوم قضاه من النهار شفعًا، كما قالت عائشة رضي الله عنها، يعني إذا كانت عادته ثلاثًا يصلي من النهار أربع تسليمتين، وإذا كان عادته في الليل يوتر بخمس صلى من النهار ست ركعات، يسلم من كل ثنتين، وإذا كان عادته إحدى عشر كالنبي ﷺ صلى من النهار اثنا عشر، ست تسليمات كما كان النبي يفعل عليه الصلاة والسلام، هذا هو الأفضل، وإذا لم يتيسر الضحى وصلاه بعد الظهر فلا بأس، لكن الأفضل أن يكون قبل الظهر. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12327/كيفية-قضاء-صلاة-الوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_544/54413.mp3","categories":["الوتر وقيام الليل","قضاء الفوائت"]},{"id":13958,"question":"نويت إن استيقظت في منتصف الليل لأصلي الوتر، وعندما استيقظت مبكرًا صليت قبل أن أصلي الوتر لكن أخذني الوقت قبل أن أصلي الوتر فأذن الفجر، فهل أصلي الوتر بعد دخول صلاة الفجر؟ أو أصلي الفجر وأترك الوتر لما بعد الصلاة؟","title":"ما وقت قضاء الوتر؟","answer":"الجواب:\n\nإذا أذن الفجر ولم يوتر الإنسان أخره إلى الضحى، والضحى بعد ارتفاع الشمس يصلي ما تيسر، يصلي ثنتين أو أربع ثنتين ثنتين.\n\nفإذا كانت عادته ثلاثًا ولم يصلها صلها الضحى أربعًا تسليمتين، فإذا كان عادته خمسًا فلم يتيسر فعلها في الليل صلاها الضحى ستًا بثلاث تسليمات، وهكذا، كان ﷺ في الغالب يوتر بإحدى عشر، فإذا شغله مرض أو نوم صلاها من النهار ثنتين عشر ركعة، هكذا قالت عائشة -رضي الله عنها-، صلاها اثنتي عشر ركعة يعني ست تسليمات، يسلم من كل ثنتين ﷺ فهذا هو المشروع للأمة اقتداءً به ﷺ.","link":"https://binbaz.org.sa/fatwas/12370/ما-وقت-قضاء-الوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_604/60415.mp3","categories":["قضاء الفوائت","الوتر وقيام الليل"]},{"id":14116,"question":"نعود إلى رسالة المستمع محمد فضل المولى من السودان حيث عرضنا بعض أسئلته، وهنا يسأل ويقول: هل في صلاة الشفع والوتر يجب أن تقرأ سورًا معينة بعد سورة الفاتحة؟ أم أنه يجب ما تيسر من القرآن فقط؟","title":"هل تُشرع قراءة سور معينة في الوتر؟","answer":"الجواب: يشرع أن تقرأ ما تيسر ولا يجب، الواجب الفاتحة فقط أما ما زاد على الفاتحة فهو مستحب، تقرأ ما تيسر آيات أو سورًا قصيرة أو طويلة حسب ما تيسر لك في تهجدك في الليل وفي النوافل في النهار، ليس في هذا شيء متعين، المتعين الفاتحة الحمد لله رب العالمين أما ما زاد عليها فهو مستحب وليس بمتعين والحمد لله، سواء كان سورة تقرأها أو تقرؤها بعض الآيات. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12566/هل-تشرع-قراءة-سور-معينة-في-الوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_615/61504.mp3","categories":["الوتر وقيام الليل"]},{"id":14120,"question":"نعود إلى رسالة المستمع محمد فضل المولى من السودان حيث عرضنا بعض أسئلته، وهنا يسأل ويقول: هل في صلاة الشفع والوتر يجب أن تقرأ سورًا معينة بعد سورة الفاتحة؟ أم أنه يجب ما تيسر من القرآن فقط؟","title":"هل تُشرع قراءة سور معينة في الوتر؟","answer":"الجواب: يشرع أن تقرأ ما تيسر ولا يجب، الواجب الفاتحة فقط أما ما زاد على الفاتحة فهو مستحب، تقرأ ما تيسر آيات أو سورًا قصيرة أو طويلة حسب ما تيسر لك في تهجدك في الليل وفي النوافل في النهار، ليس في هذا شيء متعين، المتعين الفاتحة الحمد لله رب العالمين أما ما زاد عليها فهو مستحب وليس بمتعين والحمد لله، سواء كان سورة تقرأها أو تقرؤها بعض الآيات. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12566/هل-تشرع-قراءة-سور-معينة-في-الوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_615/61504.mp3","categories":["الوتر وقيام الليل"]},{"id":14128,"question":"هل للقنوت في الوتر على الطريقة المعروفة أصل؟ وما هو الدليل؟","title":"ما دليل القنوت في الوتر؟","answer":"الجواب: نعم، القنوت سنة في الوتر من الليل، علمه النبي ﷺ الحسن بن علي، وتعليم النبي ﷺ لشخص من الصحابة تعليم الأمة كلها عليه الصلاة والسلام، فالقنوت سنة، فينبغي للمؤمن إذا صلى الركعة الأخيرة الواحدة إذا رفع رأسه من الركوع أن يرفع يديه ويقنت، يدعو: اللهم اهدني فيمن هديت.. وما تيسر معه من الدعاء، ثم يسجد كما فعله النبي ﷺ وكما فعله الصحابة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12573/ما-دليل-القنوت-في-الوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_615/61509.mp3","categories":["القنوت في الصلاة","الوتر وقيام الليل"]},{"id":14448,"question":"هذا السائل بلال أحمد من السودان، يقول في هذا  سماحة الشيخ، البعض من الناس يدعون بعد كل ركعتين من صلاة التراويح بهذه الصيغة: نسأل الله الهدى والرضا والعفو عما مضى؟","title":"حكم تخصيص دعاء معين بين ركعات التراويح","answer":"الجواب: ما لها أصل، ليس لهذا أصل، ومن دعا فلا بأس بما يسر الله من الدعاء، وإنما ليس هناك دعاء خاص بين التسليمتين، ولكن من دعا فلا حرج، أما شيء خاص، هذا الدعاء ولا غيره، نعم.","link":"https://binbaz.org.sa/fatwas/12915/حكم-تخصيص-دعاء-معين-بين-ركعات-التراويح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_554/55406.mp3","categories":["الوتر وقيام الليل"]},{"id":14457,"question":"السائل يقول في هذا  هل صحيح بأنه لا صلاة بعد الوتر؟","title":"هل صحيح أنه لا صلاة بعد الوتر؟","answer":"الجواب: لا بأس، ليس بصحيح، له أن يصلي بعد الوتر ما هو بوقت نهي، لكن الأفضل أن يختم الليل بالوتر، أن يختم صلاته بالليل بالوتر، والنبي ﷺ كان ربما صلى ركعتين بعد الوتر؛ ليعلم الناس أنه لا حرج في ذلك، فلو أوتر في الليل في أول الليل أو في وسط الليل، ثم قام في آخر الليل وصلى ما يسر الله له ركعتين أو أربعًا أو ستًا أو ما أشبهه فلا بأس. المقصود: أن الصلاة بعد الوتر لا حرج فيها، لكن الأفضل لمن صلى آخر الليل أن يختم بالوتر أن يختم بالركعة الأخيرة الواحدة تكون هي الخاتمة؛ لقوله ﷺ: اجعلوا آخر صلاتكم بالليل وترًا متفق على صحته. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12934/هل-صحيح-انه-لا-صلاة-بعد-الوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_554/55413.mp3","categories":["الوتر وقيام الليل"]},{"id":14488,"question":"صلينا المغرب والعشاء جماعة في المسجد لوجود مطر وبرد، و متى نصلي الرواتب إذا جمعنا، وكم يصبح عددها، وهل يصلى الشفع والوتر في نفس الوقت أم لا بد من تأخيره؟","title":"متى تصلى الرواتب والوتر عند الجمع بين الصلاتين؟","answer":"الجواب: إذا صليت العشاء مع المغرب جمع تقديم فإنك تصلي سنة المغرب وسنة العشاء بعد ذلك، وتصلي الوتر بعد ذلك، ولو في وقت المغرب؛ لأن العشاء متى قدمت دخل وقت الوتر وسنة العشاء، ولو كانت مجموعة مع المغرب جمع تقديم. وهكذا الظهر والعصر إذا جمعا وأنت مقيم للمطر أو للمرض تصلي سنة الظهر... ، لا، ليس بهذا، ليس في هذا قضاء؛ لأن صلاة العصر ليس بعدها صلاة؛ لأنها وقت نهي، إذا جمعت الظهر مع العصر فإنها تسقط حينئذٍ راتبة الظهر البعدية التي بعدها؛ لأن الأفضل أن تضم إليها العصر قبل أن تصلي الراتبة، فحينئذٍ تسقط الراتبة البعدية في الظهر عند الجمع في حال المرض والمطر ونحو ذلك، وتصلي الراتبة القبلية، وهي أربع قبل الظهر، وتصلي العصر بعد الظهر متصلة من دون حاجز من دون فصل براتبة الظهر البعدية. أما المغرب والعشاء فإنهما تقعان في غير وقت نهي، فلهذا إذا صليت العشاء تصلي سنة المغرب ركعتين وتصلي بعدها سنة العشاء ركعتين، وإذا أردت الوتر أوترت، أو أجلت ذلك إلى وسط الليل، أو آخر الليل، الأمر في هذا واسع، والحمد لله، نعم. المقدم: الحمد لله، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12966/متى-تصلى-الرواتب-والوتر-عند-الجمع-بين-الصلاتين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_625/62502.mp3","categories":["صلاة التطوع","الوتر وقيام الليل"]},{"id":14547,"question":"نفس السؤال تقريبًا إنما عن القنوت في الوتر؟","title":"هل القنوت في الوتر سنة؟","answer":"الجواب: سنة أيضًا القنوت، من فعله فهو أفضل، ومن ترك فلا حرج، نعم. المقدم: جزاكم الله خيرًا، إذًا من جاء بدعاء الاستفتاح وجاء بالقنوت في الوتر فثوابه أكثر؟ الشيخ: فهو السنة، فهو السنة. المقدم: فهو سنة. الشيخ: ومن ترك فلا حرج عليه. المقدم: ولكن الثواب لمن جاء؟ الشيخ: أي نعم، من فعل السنة له ثوابها، ومن ترك فلا حرج عليه، مثل صلاة الراتبة للظهر، صلاة الراتبة للمغرب، صلاة العشاء، صلاة راتبة الفجر، الرواتب صلاة الضحى، من أتى بها حصل أجرها، ومن تركها فاته أجرها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13044/هل-القنوت-في-الوتر-سنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_489/48905.mp3","categories":["القنوت في الصلاة","الوتر وقيام الليل"]},{"id":14909,"question":"هذا سائل أخوكم في الله يحيى دايل، يقول في سؤاله الأول: قال لي أحد الإخوة بأن صلاة الوتر بعد العشاء سنة، إن تركتها لا شيء عليك، وأنا بدأت أفعل ذلك، أفتونا في عملي، مأجورين.","title":"حكم صلاة الوتر عقب صلاة العشاء","answer":"نعم سنة إذا كان يخشى أن لا يقوم من آخر الليل؛ لأن الرسول ﷺ أوصى أبا هريرة وأبا الدرداء بصيام ثلاثة أيام من كل شهر، والوتر قبل النوم.  أما من طمع أن يقوم آخر الليل فهو أفضل؛ لما جاء في الحديث الصحيح عن جابر -رضي الله عنه- عن النبي ﷺ أنه قال: من خاف أن لا يقوم من آخر الليل فليوتر أوله، ومن طمع أن يقوم آخر الليل فليوتر آخر الليل، فإن صلاة آخر الليل مشهودة؛ وذلك أفضل أخرجه مسلم، فهذا يدل على أنه إذا تيسر له القيام في آخر الليل فهو أفضل، والنبي ﷺ أوتر من أوله، ومن وسطه، ومن آخره، كله جائز والحمد لله، لكن إذا تيسر من آخر الليل فهو الأفضل. المقدم: أحسن الله إليكم، وأثابكم الله سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13407/حكم-صلاة-الوتر-عقب-صلاة-العشاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_562/56209.mp3","categories":["الوتر وقيام الليل"]},{"id":14976,"question":"السائل (أ. ر. س. ع) من اليمن يقول: هل تجوز الزيادة عن ثمان ركعات في صلاة التراويح؟ وإن كانت تجوز فما أقصى عدد لها؟","title":"حكم الزيادة على ثمان ركعات في التراويح","answer":"الجواب: الرسول -عليه الصلاة والسلام- لم يشترط عددًا معينًا، بل قال: «صلاة الليل مثنى مثنى، فإذا خشي أحدكم الصبح صلى ركعة واحدة، توتر له ما قد صلى» فليس لهذا حد محدود، فإذا أوتر بتسع أو بخمس أو بسبع أو بأكثر، لكن الأفضل إحدى عشرة، أو ثلاث عشرة؛ لأن هذا هو الغالب من فعل النبي ﷺ، ولو أوتر بثلاث وعشرين، أو بأكثر من هذا فلا بأس، لكن الأفضل إحدى عشرة، أو ثلاث عشرة يسلم من كل ثنتين؛ لأن هذا هو الغالب من فعل النبي -عليه الصلاة والسلام-، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13477/حكم-الزيادة-على-ثمان-ركعات-في-التراويح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_562/56218.mp3","categories":["الوتر وقيام الليل"]},{"id":15101,"question":"سؤال للأخت في الله أم كلثوم من العراق الثاني تقول: ما هي صلاة الشفع وصلاة الوتر؟ وكم عدد ركعات الوتر التي كان يصليها رسول الله ﷺ؟","title":"ما هي صلاة الشفع والوتر؟ وكم عدد ركعاتها؟","answer":"الجواب: الشفع معناه: ركعتان، هذا الشفع، تسمى ركعتان شفع، والوتر واحدة.  والسنة الإيتار بواحدة، أو ثلاث، أو خمس، أو سبع أو تسع، أو إحدى عشرة أو ثلاث عشرة أو أكثر من ذلك، لكن الأفضل إحدى عشرة هذا هو الأفضل؛ لأن هذا في الغالب هو وتر النبي ﷺ كان في الغالب يواظب على إحدى عشرة ركعة -عليه الصلاة والسلام-، وربما أوتر بثلاث عشرة، وربما أوتر بتسع أو بسبع أو بأقل من ذلك، لكن كان غالب إيتاره ﷺ يوتر بإحدى عشرة، يسلم من كل ثنتين، ثم يوتر بواحدة -عليه الصلاة والسلام-، هذا هو الأفضل. وإذا أوتر الإنسان بثلاث أو بخمس أو بسبع أو بتسع فكله طيب، والوتر نافلة ليس بفرض على الصحيح، الذي عليه جمهور أهل العلم أنه سنة، وليس بواجب، الوتر التهجد بـالليل وأقله واحدة ركعة واحدة بعد العشاء بعد راتبة العشاء، هذا أقله، وإذا أوتر بثلاث أفضل وبخمس أفضل وبسبع أفضل، وهكذا، لكن إذا بلغ إحدى عشرة فهو أفضل، وإن زاد وأوتر بثلاث عشرة، أو بخمس عشرة، أو بسبع عشرة، أو بأكثر من هذا فلا بأس، الأمر واسع؛ لقول النبي ﷺ لما سئل عن صلاة الليل قال: مثنى مثنى ولم يحدد عددًا، ثم قال: فإذا خشي أحدكم الصبح صلى ركعة واحدة، توتر له ما قد صلى هذا يدلنا على أن الوتر يكون ركعة في آخر الصلاة، سواء كان في أول الليل، أو في وسط الليل، أو في آخر الليل يوتر بواحدة، وليس له حد محدود، فإذا أوتر بعشرين ركعة مع الوتر كما في التراويح المنقولة عن عمر -رضي الله عنه وأرضاه- أو أوتر بثلاث عشرة أو بإحدى عشرة، كما جاء عن النبي ﷺ في إيتاره في صلاة الليل، أو أوتر بسبع أو تسع أو خمس أو ثلاث كل هذا لا بأس به، وأقله واحدة في أول الليل أو آخره، نعم. المقدم: هي تسأل عن عدد ركعات الوتر التي كان يصليها الرسول، وقد عرفناها من الإجابة؟ الشيخ: إحدى عشرة، هذا هو الغالب، ربما أوتر بأقل ربما أوتر بأكثر ثلاثة عشر، اللهم ﷺ، نعم.","link":"https://binbaz.org.sa/fatwas/13598/ما-هي-صلاة-الشفع-والوتر-وكم-عدد-ركعاتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_656/nour_65602.mp3","categories":["الوتر وقيام الليل"]},{"id":15126,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين، يبدو أنه نسي أن يذكر اسمه، إنما ضمن الرسالة جمعًا من الأسئلة، في بعضها يقول: إنسان تعوّد أن يصلي الوتر في آخر الليل، ولكن في بعض الأيام، لا يستيقظ إلا عند أذان الفجر، فهل يصليها بعد الأذان أو متى؟جزاكم الله خيرًا.","title":"متى يصلى الوتر لمن فاته بالليل؟","answer":"الجواب: يصليها في النهار، والحمد لله، كان النبي ﷺ إذا شغله مرض، أو نوم، صلى من النهار، تقول عائشة -رضي الله عنها-: كان ﷺ إذا شغله مرض أو نوم، صلى من النهار ثنتي عشرة ركعة وكان وتره ﷺ في الغالب بإحدى عشرة ركعة، فإذا نام ولم يستيقظ، أو شغله مرض، صلى من النهار ست تسليمات، ثنتي عشرة ركعة.  والأفضل أن يكون في الضحى، هذا هو الأفضل، وإن صلاها بعد الظهر فلا بأس، وليس بواجب، هذا سنة مستحب، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13626/متى-يصلى-الوتر-لمن-فاته-بالليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_495/49510.mp3","categories":["قضاء الفوائت","الوتر وقيام الليل"]},{"id":15157,"question":"يقول السائل من جمهورية مصر العربية: أنا -والحمد لله- قبل ما أنام أصلي أربع ركعات قيام الليل، وبعدها أصلي ركعتين شفع، واحدة وتر، فهل في هذا شيء غير مشروع، وبالأخص بالنسبة لركعة الوتر؛ لأنه عندنا في بلدنا أكثر الناس يصلون صلاة الوتر ركعة واحدة؟أفيدونا سماحة الشيخ.","title":"ما المشروع والأفضل في عدد ركعات الوتر؟","answer":"الجواب: الأمر في هذا واسع، إن صليت في أول الليل، أو في وسط الليل، أو في آخر الليل، كله طيب، النبي فعل هذا كله ﷺ، أوتر في أول الليل، وأوتر في وسطه، وأوتر في آخره، واستقر وتره في السحر -عليه الصلاة والسلام-. ولك أن توتر بثلاث، أو بواحدة، أو بخمس، أو بسبع، أو بتسع، أو بإحدى عشرة، أو بثلاث عشرة، لكن تسلم من كل ثنتين، يقول النبي ﷺ: صلاة الليل والنهار مثنى مثنى يعني: ثنتين ثنتين، فإذا أوترت بواحدة مفردة كان هذا هو الأفضل، وإن سردت ثلاثًا جميعًا، ولم تجلس إلا في الثالثة فلا بأس، ولكن الوتر بواحدة أفضل، تصلي كل ثنتين على حدة، ثم توتر بواحدة، سواءً في وسط الليل، أو في آخره، أو في أوله، وإن صليت بعض التهجد في أوله، وبعض التهجد في آخره، فكله حسن، ولا بأس به، والحمد لله. المقدم: الحمد لله، أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13651/ما-المشروع-والافضل-في-عدد-ركعات-الوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_564/56415.mp3","categories":["الوتر وقيام الليل"]},{"id":15192,"question":"يقول عبدالرحمن ظافر العمري، من القصيم، بريدة: ما هو الدعاء الذي يستحب أن يقال في الوتر بعد صلاة العشاء؟ ومتى تستحب صلاة الوتر؟أفيدونا، جزاكم الله عنا خيرًا.","title":"وقت صلاة الوتر والدعاء الوارد فيها","answer":"الجواب: والسنة واحدة فأكثر، إذا أوتر بواحدة أو بثلاث أو بخمس أو أكثر من ذلك؛ فقد أصاب السنة، وكان النبي ﷺ في الغالب يوتر بإحدى عشرة ركعة يسلم من كل ثنتين -عليه الصلاة والسلام-، ويوتر بواحدة، وربما أوتر بثلاث وربما أوتر بخمس وربما أوتر بسبع، وربما أوتر بتسع -عليه الصلاة والسلام-، وربما أوتر بثلاث عشرة، وهذا أكثر ما نقل عنه -عليه الصلاة والسلام-، ولكنه أجاز للأمة أن يوتروا بأكثر من ذلك، فقال -عليه الصلاة والسلام-: صلاة الليل مثنى مثنى، فإذا خشي أحدكم الصبح صلى ركعً واحدة توتر له ما قد صلى فهذا يدل على أنه لا بأس بالإيتار بأكثر من ذلك: خمسًا، عشرًا، سبع عشر، تسعة عشر، إحدى وعشرين، ثلاث وعشرين، إلى غير ذلك.\nومن هذا ما فعله عمر والصحابة  حين صلوا في رمضان ثلاثًا وعشرين ركعة، التراويح، هو من هذا الباب، ويشمله الحديث الصحيح الذي رواه الشيخان من حديث ابن عمر -رضي الله عنهما- عن النبي -عليه الصلاة والسلام- أنه قال: صلاة الليل مثنى مثنى لما سئل عن صلاة الليل، قال: مثنى مثنى ولم يحدد عشر ركعات ولا عشرين، ولا أكثر، ولا أقل، بل أطلق، فدل ذلك على أن صلاة الليل موسعة في رمضان وفي غيره، من أوتر بإحدى عشرة أو بثلاث عشرة أو بأكثر من ذلك؛ فقد أصاب السنة.\nوالسنة له أن يجعل الركعة الأخيرة هي الآخر هي الختام لصلاته، وبها يحصل الإيتار، سواء في رمضان، أو في غير رمضان، وإذا اقتصر على ثلاث ركعات، أو خمس ركعات؛ لأن ذلك أسهل عليه، فكله حسن، ولو أوتر بواحدة فقط، فلا بأس بذلك.","link":"https://binbaz.org.sa/fatwas/13689/وقت-صلاة-الوتر-والدعاء-الوارد-فيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_660/nour_66001.mp3","categories":["الوتر وقيام الليل"]},{"id":15357,"question":"إحدى الأخوات المستمعات من الخبر، بعثت برسالة، ضمنتها ثلاثة أسئلة، في أحدها تقول: لقد قرأت في بعض الكتب أن صلاة التراويح عشرين ركعة، لم ترد عن الرسول ﷺ، وكذلك لم ترد عن عمر بن الخطاب، كما يزعم بعض الناس، فهل صلاة عشرين ركعة بدعة، أم هي جائزة ولا حرج فيها أبدًا؟ جزاكم الله خيرًا.","title":"حكم صلاة التراويح عشرين ركعة","answer":"الجواب: وكان ﷺ ربما أوتر بسبع، ربما أوتر بخمس، ربما أوتر بتسع، وكان في الأغلب يصلي إحدى عشرة، يسلم من كل ثنتين، ويوتر بواحدة، وربما صلى ثلاث عشرة، صلى ثنتي عشرة، ثنتين ثنتين، ثم يوتر بواحدة، هذا هو الغالب من فعله ﷺ، وربما نقص فصلى سبعًا أو تسعًا أو خمسًا أو ثلاثًا، لكن الغالب والأكثر يصلي إحدى عشرة، وفي بعض الأحيان ثلاث عشرة، ولكن ما نهى عن الزيادة -عليه الصلاة والسلام- من شاء زاد، وثبت عن عمر  والصحابة أنهم فعلوا ذلك، صلوا إحدى عشرة، وصلوا ثلاثة وعشرين، ثبت هذا وهذا، عن عمر . ومن صلى أكثر كما فعل بعض الصحابة فلا بأس، بعض السلف كان يصلي ستًا وثلاثين، ويوتر بثلاث، الجميع تسعة وثلاثين، وبعضهم يصلي إحدى وأربعين، فليس في هذا حد محدود، والحمد لله، لكن مثنى مثنى، ثنتين ثنتين، هذا هو السنة في رمضان وفي غيره. ولكن كونه يصلي ثلاث عشرة إحدى عشرة أفضل؛ لأنه أرفق؛ لأنها توافق فعل النبي ﷺ، وإن صلى ثلاثًا وعشرين كما فعل عمر في بعض الأحيان فلا بأس، وإن أحب الزيادة هو وجماعته فلا بأس، لكن يرفق بالذين معه، لا يطول عليهم، ويطمئن في ركوعه وسجوده، يرتل في قراءته؛ لأن هذا أنفع للمسلمين، ولا يجوز له أن ينقرها نقرًا، بل يجب أن يطمئن، فإذا صلى إحدى عشرة مع الطمأنينة والترتيل في القراءة كان أفضل، من عشرين، وإذا صلى ثلاث عشرة كذلك، وإذا كان يشق عليه صلى سبعًا مع الترتيل، ومع الطمأنينة أفضل، وهكذا، خمس، ثلاث، حسب طاقته فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]. وإن من أهم المهمات أنه يطمئن، ولا يعجل في قراءته، يطمئن ويرتل حتى يستفيد، وحتى يستفيد الجماعة الذين خلفه، ينتفعون بالقراءة إذا رتل واطمأن استفاد الجميع هو والجماعة، فيطمئن في ركوعه وسجوده ويرتل في قراءته ويخشع فيها حتى يستفيد من وراءه، وحتى يستفيد هو، وفق الله الجميع، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13860/حكم-صلاة-التراويح-عشرين-ركعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_498/49807.mp3","categories":["الوتر وقيام الليل"]},{"id":15540,"question":"يقول السائل: سماحة الشيخ، هل يصح أن أصلي الوتر في أول الليل، ثم أكمل هذا الوتر في آخر الليل؟","title":"حكم الوتر أول الليل ثم القيام في آخره","answer":"الجواب: الأمر واسع، إذا أوترت في أول الليل فتصلي في آخر الليل ما تيسر، لكن من دون وتر؛ لقوله ﷺ: لا وتران في ليلة، صل ركعتين، أو أربع ركعات، أو ست ركعات، أو أكثر تسلم من كل ثنتين ويكفيك الوتر الأول، ولكن الأفضل أنك تأخر الوتر، وتخليه في آخر الليل، فإذا صليت ما يسر الله لك توتر بواحدة، هذا هو الأفضل؛ لقوله ﷺ: صلاة الليل مثنى مثنى، فإذا خشي أحدكم الصبح صلى ركعة واحدة، توتر له ما قد صلى هذا هو المشروع.","link":"https://binbaz.org.sa/fatwas/14082/حكم-الوتر-اول-الليل-ثم-القيام-في-اخره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_691/nour_69119.mp3","categories":["الوتر وقيام الليل"]},{"id":15562,"question":"يقول السائل عبدالله علي محسن، من اليمن، شبوة: ما رأي سماحتكم فيمن يتحرى قيام الليل قبل أذان الفجر بساعة إلا ربع؛ لكوني إذا صليت الساعة الواحدة أو الثانية بعد منتصف الليل أحيانًا أنام عن صلاة الفجر مع الجماعة؟","title":"الوقت المفضل لقيام الليل","answer":"الجواب: الأفضل أن تؤخر قيام الليل إلى آخر الليل، حتى تصلي ما يسر الله لك، وتحضر صلاة الفجر، أما إذا صليت في وسط الليل، ثم نمت هذا قد يخشى عليك أن تنام عن الفجر، فالواجب عليك الاحتياط، الواجب عليك أن تحرص على أن لا تفوتك صلاة الفجر؛ لأن صلاتها في الجماعة أمر لازم، فعلى الرجل أن يصلي في الجماعة صلاة الفجر كبقية الصلوات، ليس له أن يصلي في البيت، فصل آخر الليل حتى تجمع بين الأمرين، وقّت الساعة على قرب الفجر، إذا بقي ساعة أو أكثر صل فيها، ثم تقوم إلى المسجد، إذا أذن توجه إلى المسجد، نعم. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/14105/الوقت-المفضل-لقيام-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_691/nour_69134.mp3","categories":["الوتر وقيام الليل"]},{"id":15591,"question":"يقول السائل: في بعض الأحيان أنسى قراءة دعاء القنوت في صلاة الوتر، فهل أكمل الصلاة أم أصليها مرة أخرى؟","title":"حكم نسيان القنوت في صلاة الوتر","answer":"الجواب: ما هو بلازم، دعاء القنوت مستحب، لو رفع رأسه من الركعة الأخيرة الوتر، ثم سجد، ولم يقنت لا بأس، القنوت مستحب فقط، ما هو لازم، فلو فعله بعض الأحيان، وتركه بعض الأحيان، فلا بأس، القنوت مستحب، وليس بواجب، نعم.","link":"https://binbaz.org.sa/fatwas/14130/حكم-نسيان-القنوت-في-صلاة-الوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_570/57016.mp3","categories":["القنوت في الصلاة","الوتر وقيام الليل"]},{"id":15650,"question":"سؤاله الثاني يقول: رأيت والدي في منتصف الليل يصلي صلاة الليل ثمان ركعات، فسألته عن فائدة الصلاة في الليل، فقال: إن الإنسان الذي يصلي في الليل لا تأكل الأرض جسده بعد وفاته، فهل هذا صحيح؟ وهل يبقى الإنسان في قبره إذا كان يصلي صلاة الليل والناس نيام؟ وهل الروح تبقى في الجسد بعد الوفاة أم تصعد إلى خالقها؟","title":"ما صحة عدم أكل الأرض جسد من يقوم الليل؟","answer":"الجواب:  صلاة الليل قربة عظيمة، وسنة مؤكدة، قال الله -جل وعلا- في وصف عباد الرحمن: وَالَّذِينَ يَبِيتُونَ لِرَبِّهِمْ سُجَّدًا وَقِيَامًا[الفرقان:64] وقال سبحانه في وصف المتقين: كَانُوا قَلِيلًا مِنَ اللَّيْلِ مَا يَهْجَعُونَ ۝ وَبِالأَسْحَارِ هُمْ يَسْتَغْفِرُونَ[الذاريات:18] قال الله لنبيه -عليه الصلاة والسلام-: يَا أَيُّهَا الْمُزَّمِّلُ ۝ قُمِ اللَّيْلَ إِلَّا قَلِيلًا ۝ نِصْفَهُ أَوِ انْقُصْ مِنْهُ قَلِيلًا ۝ أَوْ زِدْ عَلَيْهِ وَرَتِّلِ الْقُرْآنَ تَرْتِيلًا[المزمل:4] وقال سبحانه: تَتَجَافَى جُنُوبُهُمْ عَنِ الْمَضَاجِعِ يَدْعُونَ رَبَّهُمْ خَوْفًا وَطَمَعًا وَمِمَّا رَزَقْنَاهُمْ يُنفِقُونَ[السجدة:16] والآيات في هذا كثيرة تدل على فضل قيام الليل، والنبي ﷺ كان يتهجد بالليل كثيرًا -عليه الصلاة والسلام-، ويقول: أيها الناس، أفشوا السلام، وأطعموا الطعام، وصلوا الأرحام، وصلوا بالليل والناس نيام، تدخلوا الجنة بسلام التهجد بالليل من أفضل القربات، ومن أعظم الطاعات، وكان ﷺ في الأغلب يصلي إحدى عشرة ركعة، يسلم من كل ثنتين، ويوتر بواحدة -عليه الصلاة والسلام-، وربما أوتر بأقل من هذا، ربما أوتر بتسع، وربما أوتر بسبع، وربما أوتر بخمس، ولكن الأغلب أنه كان يصلي إحدى عشرة، وربما صلى ثلاث عشرة -عليه الصلاة والسلام- في الليل، يطيل في قراءته وركوعه وسجوده -عليه الصلاة والسلام-. أما كونه لا تأكل الأرض جسمه إذا كان يصلي من الليل فهذا لا أعلم له أصلًا، لا أعلم في الأدلة الشرعية ما يدل على ذلك. وأما الروح -روح المؤمن- فإنها تعلق في شجر الجنة، تكون في الجنة.....، الله الجنة -جل وعلا-، وتعلق في أشجارها كالطائر، شبه طائر تعلق في أشجار الجنة وثمارها، كما صح به الخبر عن رسول الله ﷺ أنه قال: روح المؤمن طائر، يعلق في شجر الجنة. وأما أرواح الشهداء فأخبر النبي ﷺ أنها تكون في أجواف طير خضر، تسرح في الجنة حيث شاءت، ثم تعود إلى قناديل معلقة تحت العرش. فأرواح المؤمنين في الجنة مكرمة، لكن أرواح الشهداء لها شأن، ويعيد الله الأرواح إلى أجسادها إذا شاء كما يعيدها عند السؤال، حين يموت الإنسان، ويوضع في قبره يأتيه الملك فيسأله عن ربه وعن دينه وعن نبيه، ويعيد الله له روحه فيسمع السؤال، ويجيب إن كان صالحًا، ويتردد ولا يستطيع الإجابة إذا كان كافرًا أو منافقًا، نسأل الله السلامة. أما أرواح الكفار ففي النار، نسأل الله العافية، أرواحهم في النار، قد قال الله -جل وعلا- في آل فرعون: النَّارُ يُعْرَضُونَ عَلَيْهَا غُدُوًّا وَعَشِيًّا وَيَوْمَ تَقُومُ السَّاعَةُ أَدْخِلُوا آلَ فِرْعَوْنَ أَشَدَّ الْعَذَابِ[غافر:46]. واختلف أهل العلم في مستقرها، فقيل: في نفس النار، وقيل: في قبور أصحابها، وقيل في غير ذلك. ولكنها بكل حال معذبة نعوذ بالله، وتعرض على النار ومصيرها إلى النار نسأل الله العافية، نعم. المقدم: أثابكم الله.","link":"https://binbaz.org.sa/fatwas/14192/ما-صحة-عدم-اكل-الارض-جسد-من-يقوم-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_698/nour_69802.mp3","categories":["الوتر وقيام الليل","عذاب القبر ونعيمه "]},{"id":15670,"question":"أولى رسائل هذه الحلقة، رسالة وصلت إلى البرنامج من الإخوة عبدالرحمن جمعة عمارة، ومحمد جمعة عمارة و(ع. ف. غ) يسألون عدة أسئلة، أولها يقول: صلى إمامنا التراويح، وفي إحدى التسليمات قام للثالثة، ولم يتذكر أنه أتى بالثالثة إلا بعد أن اعتدل قائمًا، وحينئذٍ قرر أن يأتي برابعة، وفعلًا أتى بالرابعة، ثم تشهد وسجد للسهو، ثم سلم، فما حكم ما فعل؟","title":"حكم من صلى أربعًا في التراويح بسلام واحد","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فالمشروع لمن قام إلى الثالثة في صلاة التراويح أن يرجع ويجلس ويتشهد ويصلي على النبي ﷺ ويدعو، ثم يسلم بعدما يسجد للسهو سجدتين، وإن أخرهما بعد السلام فلا بأس.  والأفضل أن يكون سجود السهو قبل السلام في مثل هذا؛ لقول النبي ﷺ: صلاة الليل مثنى مثنى فهذا نوى ثنتين، فيكون مثل الفجر إذا قام إلى الثالثة يجلس، يكمل التشهد، والصلاة على النبي ﷺ والدعاء، ثم يسجد للسهو ويسلم، لكن ما دام أنه فعل هذا كان جاهلًا، وكملها أربعًا، وسجد للسهو لا حرج -إن شاء الله-، نعم. المقدم: جزاكم الله خيرًا، إنما كان الأولى أن يكتفي بالاثنتين، ولو اعتدل قائمًا. الشيخ: الواجب أنه يرجع؛ لقول النبي ﷺ: صلاة الليل مثنى مثنى فإذا قام إلى الثالثة ناسيًا وجب عليه الرجوع في الأصح، حتى يحقق ما نواه من الثنتين، ثم يسجد للسهو ويسلم بعدما يأتي بالتشهد، وهكذا في النهار على الأصح؛ لقوله ﷺ: صلاة الليل والنهار مثنى مثنى يعني: ثنتين ثنتين، لكن لو نوى خمسًا جميعًا أو سبعًا جميعًا؛ فهذا لا حرج؛ لأنه فعله النبي ﷺ، أو نواها تسعًا جميعًا وجلس في الثامنة للتشهد الأول، ثم قام وأتى بالتاسعة لا بأس. أما أنه يصلي أربعًا جميعًا، أو ستًا جميعًا؛ لا، هذا خلاف المشروع، خالف قوله ﷺ: صلاة الليل مثنى مثنى فلا يستثنى من ذلك إلا ما فعله النبي ﷺ خلاف ذلك، فإنه ﷺ أوتر بثلاث جميعًا لم يجلس إلا في آخرها، وأوتر بخمس جميعًا لم يجلس إلا في آخرها، وأوتر بسبع جميعًا لم يجلس إلا في آخرها، وفي بعض الأحيان يجلس في السادسة، ويتشهد التشهد الأول، ثم يقوم للسابعة، وأوتر بتسع جميعًا، وجلس في الثامنة، وتشهد التشهد الأول، ثم قام وأتى بالتاسعة، ولم يحفظ عنه ﷺ أنه صلى أربعًا جميعًا في الليل، ولا ستًا جميعًا، ولا ثمانًا جميعًا، بل يصلي ثنتين ثنتين -عليه الصلاة والسلام-، وهو القائل -عليه الصلاة والسلام-: صلوا كما رأيتموني أصلي وقد رآه الصحابة يصلي ثنتين ثنتين، وقد أمر بذلك قال: صلاة الليل مثنى مثنى فإن هذا خبر معناه الأمر، معناه: صلوا مثنى مثنى، وفق الله الجميع. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14214/حكم-من-صلى-اربعا-في-التراويح-بسلام-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_706/nour_70601.mp3","categories":["الوتر وقيام الليل"]},{"id":15713,"question":"يقول هذا السائل: أرجو أن تبينوا لي كيفية أداء الصلاة، وقيام الليل، وعن عدد الركعات، وماذا يقال في الركوع والسجود؟ وعن الآيات التي يستحب أن نقرأ في كل ركعة فيها؟","title":"كيفية قيام الليل","answer":"الجواب: قيام الليل مشروع وسنة، ومن أعمال الصالحين، ومن أعماله ﷺ، قال الله -جل وعلا-: يَا أَيُّهَا الْمُزَّمِّلُ ۝ قُمِ اللَّيْلَ إِلَّا قَلِيلًا [المزمل:1-2] يعني: النبي ﷺ. قال الله -جل وعلا-: وَمِنَ اللَّيْلِ فَتَهَجَّدْ بِهِ نَافِلَةً لَكَ [الإسراء:79] الآية، وقال عن عباد الرحمن في سورة الفرقان: وَالَّذِينَ يَبِيتُونَ لِرَبِّهِمْ سُجَّدًا وَقِيَامًا [الفرقان:64] وقال في صفة عباد الله المسلمين المؤمنين: كَانُوا قَلِيلًا مِنَ اللَّيْلِ مَا يَهْجَعُونَ  ۝  وَبِالأَسْحَارِ هُمْ يَسْتَغْفِرُونَ[الذاريات:17-18] فقيام الليل سنة مؤكدة، سواءً في أوله، أو في وسطه، أو في آخره، لكن آخره أفضل، الثلث الأخير أفضل، إلا إذا كان يشق عليه ذلك فإنه يوتر في أول الليل، يوتر بواحدة، بثلاث، بخمس، بسبع، بأكثر، يسلم من كل ثنتين، يصلي ثنتين ثنتين. ويجتهد في ترتيل القراءة، ويوتر بواحدة، وليس هناك شيء محدود، يقرأ ما تيسر من أول القرآن، من أوسط القرآن، من آخره، أو ينظم ختمه؛ يبدأ من أول القرآن إلى أن يختم، ثم يعود، كله طيب، ليس في هذا حد محدود، لكن السنة أن يرتل، كما قال الله -جل وعلا-: وَرَتِّلِ الْقُرْآنَ تَرْتِيلًا [المزمل:4] كان النبي ﷺ يقرأ قراءة واضحة يرتلها حتى يستفيد من يسمعها. ويستحب له السؤال عند آية الرحمة، والتعوذ عند آية الوعيد، والتسبيح عند آية التسبيح في تهجده؛ كما كان النبي يفعل -عليه الصلاة والسلام-. والسنة أن يسلم من كل ثنتين؛ لقوله ﷺ: صلاة الليل مثنى مثنى يعني: ثنتين ثنتين فإذا خشي أحدكم الصبح، صلى ركعة واحدة، توتر له ما قد صلى. يقرأ فيها الحمد وقُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص:1] إذا صار إلى الركعة الأخيرة، ويقنت فيها بعد الركوع بالقنوت الشرعي الذي علمه النبي ﷺ الحسن، وهو معروف عند أهل العلم. والسنة عدم العجلة، يطمئن في ركوعه، سجوده وقراءته، لا يعجل، يطمئن، كان النبي ﷺ يصلي بطمأنينة وترتيل للقراءة، خشوعًا في الركوع والسجود، هكذا المؤمن لا يعجل يطمئن في ركوعه وسجوده، يطمئن في قراءته، ولا يعجل، يخشع فيها، تأسيًا بالنبي -عليه الصلاة والسلام-، وإذا أوتر بواحدة أو بثلاث أو بخمس أو بأكثر فلا بأس، الأمر واسع، صلاة الليل ما فيها حد محدود، لكن أفضلها إحدى عشرة، أو ثلاث عشرة تأسيًا بالنبي ﷺ، يسلم من كل ثنتين، ويوتر بواحدة، هذا هو أفضلها، وإن أوتر بأكثر من هذا فلا بأس. المقدم: أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/14271/كيفية-قيام-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_574/57403.mp3","categories":["الوتر وقيام الليل"]},{"id":15897,"question":"يقول: عندنا فتيات عندما يأتي رمضان يجتمعن في بيت إحداهن، ويصلين صلاة التراويح جماعة، فهل هذا جائز أم هو من البدع؟مع العلم أننا في تلك القرية لا نذهب مع الرجال إلى المسجد خوفًا من الفتنة، هذا كلام البنات.","title":"حكم اجتماع النساء لصلاة التراويح","answer":"الجواب: هذا طيب لا بأس به، إذا صلين جميعًا التراويح جماعة فلا حرج في ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14490/حكم-اجتماع-النساء-لصلاة-التراويح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_745/nour_74517.mp3","categories":["قضايا المرأة","الوتر وقيام الليل"]},{"id":16036,"question":"تقول: بحمد الله تعالى وشكره أصبحت أصلي الليل، لكن الذي حدث ذات مرة أنني لم أفق في ليلة من الليالي إلا على أذان الفجر، فصليت الفجر، هل علي قضاء ما كنت أصلي؟","title":"حكم قضاء صلاة الليل","answer":"الجواب: ليس عليك قضاء، لكن الأفضل أن تقضي، كان النبي ﷺ إذا فاته ورده من الليل؛ قضاه من النهار -عليه الصلاة والسلام- لكنه نافلة مستحب، فإذا كنت تصلين من الليل عشر ركعات مع الوتر واحدة، إحدى عشرة؛ فالأفضل لك أن تصلي من النهار ثنتا عشرة ركعة، مثلما كان النبي يفعل -عليه الصلاة والسلام- تسلمين من كل ثنتين، وإذا كانت عادتك سبع ركعات تصلي من النهار ثمانًا، أربع تسليمات، وهكذا لو كانت عادتك ثلاثًا تصلي من النهار تسليمتين، أربع ركعات هذه السنة. تقول عائشة -رضي الله عنها-: \"كان النبي ﷺ إذا شغله عن صلاته بالليل مرض، أو نوم؛ صلى من النهار ثنتي عشرة ركعة\". وكان الغالب عليه ﷺ في الليل أن يصلي إحدى عشرة، يسلم من كل ثنتين، ويوتر بواحدة، فإذا شغله مرض، أو نوم؛ صلاها من النهار، وزاد ركعة؛ صارت ثنتي عشرة ركعة، ويسلم من كل ثنتين، هذا هو السنة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14667/حكم-قضاء-صلاة-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_748/nour_74805.mp3","categories":["الوتر وقيام الليل"]},{"id":16046,"question":"رسالة بعث بها أحد الإخوة المستمعين، كتب اسمه بالأحرف اللاتينية، يسأل جمعًا من الأسئلة -سماحة الشيخ- من بينها سؤال يقول: هل لي أن أصلي صلاة التراويح وأنا منفرد؟ جزاكم الله خيرًا.","title":"ما حكم صلاة التراويح بانفراد؟","answer":"الجواب: صلاة التراويح في الجماعة أفضل، النبي ﷺ صلاها بأصحابه جماعةً عدة ليالي، ثم ترك ذلك، وقال: إني أخاف أن تفرض عليكم صلاة الليل فلما توفي ﷺ وانقطع الوحي؛ جمع الناس عمر على إمام واحد، يصلي بهم في مسجد النبي ﷺ في.. شهر رمضان، وقد قال -عليه الصلاة والسلام-: من قام مع الإمام حتى ينصرف؛ كتب له قيام ليلة. فالأفضل أن تصلي مع الجماعة من أجل هذا الفضل العظيم، وإن صليت في بيتك؛ فلا بأس؛ لأنها نافلة، لكن من صلاها مع الجماعة؛ حصل له فضل الجماعة، وحصل له فضل قيام الليل كله إذا قام مع الإمام حتى ينصرف، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14676/ما-حكم-صلاة-التراويح-بانفراد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_711/nour_71103.mp3","categories":["الوتر وقيام الليل"]},{"id":16081,"question":"بعد هذا رسالة وصلت إلى البرنامج من ليبيا وباعثها المستمع محمد صالح المهدي، الأخ محمد يسأل سماحتكم فيقول: ما هو الوقت المناسب لصلاة الليل؟ وما هو وقت الدعاء المناسب؟ وماذا يقول الإنسان فيه؟ جزاكم الله خيرًا.","title":"أفضل الأوقات لقيام الليل","answer":"الجواب: أفضل الأوقات الثلث الأخير إذا تيسر ذلك؛ لقول النبي ﷺ: من خاف ألا يقوم من آخر الليل؛ فليوتر أول الليل، ومن طمع أن يقوم آخر الليل؛ فليوتر آخر الليل؛ فإن صلاة آخر الليل مشهودة، وذلك أفضل رواه مسلم في الصحيح. ولقوله ﷺ: ينزل ربنا إلى سماء الدنيا كل ليلة حين يبقى ثلث الليل الآخر فيقول سبحانه: من يدعوني؛ فأستجيب له؟ من يسألني؛ فأعطيه؟ من يستغفرني؛ فأغفر له؟ حتى ينفجر الفجر متفق على صحته. هذا الحديث العظيم يدل على أن التعبد في آخر الليل في الثلث الأخير أفضل لهذا الحديث العظيم، وينبغي له الإكثار من الدعاء، والسؤال، والتوبة إلى الله  في هذا الوقت العظيم. وإن صلى في وسط الليل فهو وقت أيضًا عظيم.... جوف الليل، وإن صلى في أول الليل كذلك بعد صلاة العشاء كله خير، ولاسيما إذا كان يخشى ألا يقوم؛ فالسنة أن يصلي قبل أن ينام، قد أوصى النبي ﷺ أبا هريرة، وأبا الدرداء بالإيتار قبل النوم، والسبب -والله أعلم- أنهما يدرسان الحديث، ويخشيان ألا يقوما في آخر الليل. والخلاصة: أن من طمع أن يقوم آخر الليل؛ فهو أفضل، ومن خاف ألا يقوم من آخر الليل؛ فليوتر أول الليل، والحمد لله. وأما قوله: ينزل ربنا فهذا وصف يليق بالله عند أهل السنة والجماعة، يثبتونه كما يليق بالله، نزول يليق بالله، لا يشابه خلقه في نزولهم، كما أنه لا يشابه خلقه في صفاته كلها، لا في الاستواء، ولا في الرحمة، ولا في الغضب، ولا في الرضا، ولا في غير ذلك من الصفات، فيجب إثبات صفات الله لله على الوجه اللائق بالله  من غير تحريف، ولا تعطيل، ولا تكييف، ولا تمثيل، هكذا قال أهل السنة والجماعة، كما نص على ذلك أهل العلم، كمالك بن أنس -رحمه الله- والشافعي، وأحمد، والثوري، وابن المبارك، والأوزاعي .. وغيرهم.  وقد جمع أبو العباس ابن تيمية -رحمه الله- أقوالهم في رسالة الحموية، وهو كتاب عظيم مفيد، فـأهل السنة والجماعة يثبتون جميع الصفات لله الواردة في القرآن، وفي السنة الصحيحة على الوجه اللائق بالله كالاستواء، والنزول، والغضب، والرضا، والرحمة، والسمع، والبصر، والكلام.. وغير ذلك؛ كلها يثبتونها لله سبحانه على الوجه اللائق بالله -جل وعلا- من غير تحريف، ولا تعطيل، ولا تكييف، ولا تمثيل كما قال الله سبحانه: قُلْ هُوَ اللَّهُ أَحَدٌ ۝ اللَّهُ الصَّمَدُ ۝ لَمْ يَلِدْ وَلَمْ يُولَدْ ۝ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ [الإخلاص:1-4] وقال سبحانه: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11] وقال سبحانه: فَلا تَضْرِبُوا لِلَّهِ الأَمْثَالَ إِنَّ اللَّهَ يَعْلَمُ وَأَنْتُمْ لا تَعْلَمُونَ [النحل:74].  هذا هو الواجب على جميع المسلمين إثبات صفات الله، وأسمائه له سبحانه كما جاءت في القرآن، وكما جاءت في السنة الصحيحة، من غير تحريف، ولا تعطيل، ولا تكييف، ولا تمثيل، بل يجب إثباتها لله على الوجه اللائق بالله  مع الإيمان بحقائقها، وأنها حق، وأنها لا تشابه صفات المخلوقين، بل هي ثابتة لله على الوجه اللائق بالله  من غير مشابهة لخلقه في شيء من صفاته -جل وعلا- هذا قول أهل الحق، هذا قول أهل السنة والجماعة، وهم الطائفة المنصورة، وهم الفرقة الناجية. أهل السنة والجماعة هم الطائفة المنصورة، وهم الفرقة الناجية، وهم أهل الحق، فالواجب السير على منهجهم، والاستقامة على طريقهم، وهو طاعة الله ورسوله، والإخلاص لله في العمل، واتباع الشريعة، وعدم البدعة، هكذا درج أهل السنة من أصحاب النبي ﷺ وأتباعهم بإحسان بتوحيد الله، والإخلاص له، والإيمان بكل ما أخبر الله به ورسوله، والاستقامة على دين الله، وإثبات صفات الله وأسمائه على الوجه اللائق بالله  هكذا درج أهل السنة والجماعة: وهم أصحاب النبي ﷺ وأتباعهم بإحسان، وهم الفرقة الناجية المذكورة في قوله ﷺ: افترقت أمتي على ثلاث وسبعين فرقة، كلها في النار إلا واحدة هذه الواحدة هم أهل السنة والجماعة، وهم الطائفة المنصورة التي قال فيها النبي ﷺ: لا تزال طائفة من أمتي على الحق منصورة، لا يضرهم من خذلهم، ولا من خالفهم حتى يأتي أمر الله. والعلماء هم رأس هذه الطائفة، العلماء وأهل الحديث هم رأس هذه الطائفة، وهم أئمة هذه الطائفة، وعلى رأسهم أصحاب النبي ﷺ هم خير هذه الأمة، ثم العلماء من أهل السنة والجماعة بعدهم، وأهل الحديث هم أئمة هذه الطائفة، هم من رؤسائهم وقادتهم، ولهذا قال بعض السلف: إن لم يكونوا أهل الحديث فلا أدري من هم؟  المعنى أن أهل الحديث هم خلاصتهم، وهم أئمتهم، وهكذا العلماء علماء الحق كلهم من أهل السنة والجماعة، وكلهم من الطائفة المنصورة، وهكذا عامتهم يدخلون في الطائفة المنصورة، العامة من الرجال والنساء الذين درجوا على هذا المنهج، وساروا على طريق أهل السنة والجماعة في الاستقامة على الحق، والإيمان بأسماء الله، وصفاته على الوجه اللائق بالله، وتمسكوا بشرعه، هؤلاء كلهم أهل السنة والجماعة، وكلهم يدعون الفرقة الناجية، وكلهم يقال لهم: الطائفة المنصورة إلى قيام الساعة. نسأل الله أن يجعلنا وإياكم -أيها المستمعون- من أهل السنة، نسأل الله أن يجعلنا وإياكم منهم، نسأل الله أن يجعلنا وجميع إخواننا المستمعين من أهل السنة والجماعة، نسأل الله أن يثبتنا على الحق، وأن يعيذنا من مضلات الفتن، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14716/افضل-الاوقات-لقيام-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_711/nour_71107.mp3","categories":["الوتر وقيام الليل"]},{"id":16094,"question":"هل يوجد حديث ورد أن في الوتر صلاة تصلى مثل صلاة المغرب؟","title":"صلاة الوتر لا تصلى كالمغرب","answer":"الجواب: لا لم يرد، لا، يُكره، النبي ﷺ نهى عن تشبيهها بالمغرب، لكن يصليها سردًا -ثلاثة مسرودة- لا بأس، أو يوتر بواحدة -وهو الأفضل- يسلم من الثنتين، ثم يأتي بواحدة، هذا هو الأفضل، وإن سرد الثلاث سردًا، ولم يجلس إلا في الثالثة؛ فلا بأس، أما يشبهها بالمغرب لا، يكره، ما ينبغي. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/14736/صلاة-الوتر-لا-تصلى-كالمغرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_579/57914.mp3","categories":["الوتر وقيام الليل"]},{"id":16098,"question":"هذا السائل (ب. س. م) من الرياض يقول: صلى بنا الإمام ذات مرة صلاة التراويح أربع تسليمات، ثم صلى بنا الوتر بتسليمة واحدة، وثلاث ركعات الوتر، فهل عمله صحيح؟","title":"حكم صلاة الوتر ثلاث ركعات بتسليمة واحدة","answer":"الجواب: هذا أفضل إذا صلى إحدى عشر، أربع تسليمات، ثم الوتر: ترويحات، ركعتين، ثم ركعة، أحد عشر الجميع، هذا هو الغالب من فعل النبي ﷺ، يصلي ثنتين ثنتين ثنتين.. هذه ثمان، ثم ثنتين فيها سَبِّحِ [الأعلى:1] والكافرون، ثم واحدة فيها قُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص:1] هذا هو الأفضل. وإن صلى ثلاثة عشر فلا بأس، وإن سرد الثلاث، سَبِّحِ [الأعلى:1] وقُلْ يَا أَيُّهَا الْكَافِرُونَ [الكافرون:1] ... سردها جميعًا؛ فلا بأس، لكن لا يشبهها بالمغرب، بل يسردها جميعًا بسلام واحد، لا بأس، والأفضل أن يسلم من كل ثنتين كما سلم من أربع الأول من كل ثنتين، كذلك يقرأ (سبح) والكافرون ويسلم، ثم يأتي بواحدة فيها قُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص: 1] ويسلم -مع الفاتحة- هذا هو الأفضل، والواحدة وحدها مستقلة، وإن جمعها مع الثنتين -سرد الثلاث جميعًا- فلا حرج؛ فعل النبي هذا وهذا، اللهم صل عليه وسلم. المقدم: اللهم صل وسلم عليه.","link":"https://binbaz.org.sa/fatwas/14741/حكم-صلاة-الوتر-ثلاث-ركعات-بتسليمة-واحدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_579/57918.mp3","categories":["الوتر وقيام الليل"]},{"id":16099,"question":"سماحة الشيخ! هذا السائل يقول: من يصلي مع الإمام أربع ركعات، أو ستًا.. وهكذا، ولا يكمل مع الإمام بقية الصلاة؛ فهل يكتب له أجر القائم مع الإمام، وتكتب له قيام ليلة؟ وما حكم من يصلي الوتر فقط في رمضان؟","title":"أجر من لم يكمل مع الإمام التراويح","answer":"الجواب: له أجر ما صلى، ولا يكتب له قيام الليلة إلا إذا كمل مع الإمام حتى ينصرف الإمام، يكتب له قيام ليلة، أما إذا صلى معه تسليمة، أو تسليمتين؛ فله أجرها نافلة، كلها نافلة، لكن الأفضل أن يكمل معه حتى يحصل له فضل قيام الليل. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14742/اجر-من-لم-يكمل-مع-الامام-التراويح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_579/57919.mp3","categories":["الوتر وقيام الليل"]},{"id":16122,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين، يقول المرسل صبار محمد السيد، أخونا يسأل سماحتكم -لو تكرمتم- شيخ عبدالعزيز عن صلاة التهجد، متى تكون؟ وهل هي في أول الليل، أو في آخره؟ وما الحكم ما إذا قرأ فيها الإنسان بسورة يس، أو تبارك من المصحف الشريف حتى لا يخطئ في القراءة؟ جزاكم الله خيرًا.","title":"أفضل وقت للتهجد","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  لقول النبي ﷺ: من خاف ألا يقوم من آخر الليل؛ فليوتر أوله، ومن طمع أن يقوم آخر الليل؛ فليوتر آخر الليل، فإن صلاة آخر الليل مشهودة، وذلك أفضل رواه مسلم في الصحيح، ولقوله ﷺ: صلاة داود كان ينام نصف الليل، ويقوم ثلثه، وينام سدسه قال: وهي أفضل الصلاة وقال -عليه الصلاة والسلام-: ينزل ربنا إلى سماء الدنيا كل ليلة حين يبقى ثلث الليل الآخر، فيقول: من يدعوني؛ فأستجيب له، من يسألني؛ فأعطيه، من يستغفرني؛ فأغفر له، حتى ينفجر الفجر متفق على صحته، هذا يدل على شرعية القيام آخر الليل، وأنه أفضل، وأنه مظنة الاستجابة، يقول الرب -جل وعلا-: من يدعوني؛ فأستجيب له. وهكذا جوف الليل، صلاة داود السدس الرابع والخامس كلها مظنة إجابة، وكلها محل فضل للصلاة والتهجد، وذلك أفضل من أول الليل، لكن من كان يخشى ألا يقوم من آخر الليل؛ فإنه يشرع له الإيتار في أول الليل بعد صلاة العشاء، قبل أن ينام. قول النبي ﷺ: ينزل ربنا إلى سماء الدنيا كل ليلة هذا نزول يليق بالله، لا يكيف، لا يعلم كيفيته إلا هو  يوصف -جل وعلا- بالنزول، والاستواء على العرش، والكلام، والإرادة، والمشيئة، والسمع، والبصر، وغير هذا من الصفات الواردة في القرآن العظيم، والسنة الصحيحة، يجب وصفه بها سبحانه على الوجه اللائق به -جل وعلا- من غير تشبيه له بخلقه، كما قال سبحانه: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11] قال سبحانه: قُلْ هُوَ اللَّهُ أَحَدٌ ۝ اللَّهُ الصَّمَدُ ۝ لَمْ يَلِدْ وَلَمْ يُولَدْ ۝ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ [الإخلاص:1-4] قال سبحانه: فَلا تَضْرِبُوا لِلَّهِ الأَمْثَالَ [النحل:74]. فالله -جل وعلا- لا مثيل له، ولا كفء له، ولا شبيه له  هو الكامل في ذاته، وأسمائه، وصفاته، وأفعاله، وهو ينزل نزولًا يليق بجلاله، لا يعلم كيفيته إلا هو  إلى سماء الدنيا آخر الليل في الثلث الأخير، يقول -جل وعلا-: من يدعوني؛ فأستجيب له، من يسألني؛ فأعطيه، من يستغفرني فأغفر له. فنوصي باغتنام هذا الخير العظيم، ومن تيسر له قيام آخر الليل فهو أفضل، ومن لم يتيسر له ذلك؛ فليوتر أول الليل، وأقل ذلك ركعة واحدة، يوتر بها في أول الليل، أو في آخره، وكلما زاد؛ فهو أفضل، يسلم من كل ثنتين؛ لقول النبي ﷺ: صلاة الليل مثنى مثنى يعني: ثنتين ثنتين فإذا خشي أحدكم الصبح؛ صلى ركعة واحدة توتر له ما قد صلى يعني: المتهجد بالليل يصلي ثنتين... يسلم من كل ثنتين، ثم يوتر بواحدة، يقرأ فيها الحمد وقُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص:1] هذا هو السنة.  وأفضل ذلك إحدى عشرة، أو ثلاث عشرة؛ لأن هذا هو وتر النبي ﷺ في الغالب، كان وتره في الغالب إحدى عشرة، أو ثلاثة عشرة -عليه الصلاة والسلام- ومن زاد، وأوتر بأكثر من هذا؛ فلا بأس، ليس له حد محدود، ولو أوتر بخمسين، أو ستين، أو مائة ركعة يسلم من كل ثنتين؛ فلا بأس، ويوتر بواحدة.  لكن كونه يوتر بإحدى عشرة، أو ثلاث عشرة هذا هو الأفضل، وإن أوتر بثلاث، أو بخمس، أو بسبع، أو بتسع كله طيب، لكن السنة أن يسلم من كل ثنتين، فإن سرد ثلاثًا، وأوتر بها، أو خمسًا، وأوتر بها سردًا، لم يجلس فيها إلا في الآخر؛ فلا بأس، قد ثبت هذا عن النبي ﷺ في بعض الأحيان، عليه الصلاة والسلام. وهكذا لو سرد سبعًا، لم يجلس إلا في آخرها؛ فلا بأس، وإن جلس في السادسة وأتى بالتشهد الأول، ثم قام وأتى بالسابعة كذلك هذا ورد ....... وهذا عن النبي ﷺ ثبت هذا وهذا عنه -عليه الصلاة والسلام- سرد السبع في بعض الأحيان، وفي بعض الأحيان جلس في السادسة، وتشهد، ثم قام قبل أن يسلم، وأتى بالسابعة. وهكذا سرد تسعًا، جلس في الثامنة للتشهد الأول، تشهد التشهد الأول، ثم قام وأتى بالتاسعة، ولكن الأفضل هو ما كان يغلب عليه -عليه الصلاة والسلام- وهو أن يسلم من كل ثنتين، هذا هو الأفضل، وهو موافق لقوله ﷺ: صلاة الليل مثنى مثنى يعني: ثنتين ثنتين، يسلم من كل ثنتين. وفق الله الجميع، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14777/افضل-وقت-للتهجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_713/nour_71301.mp3","categories":["الوتر وقيام الليل"]},{"id":16136,"question":"في سؤالها الثاني تقول: صلاة الوتر ركعتان، أو أكثر، ثم واحدة، هل ورد عن الرسول ﷺ أنه واصل الثلاث ركعات بتسليمة واحدة، وهل إذا كان هذا صحيحًا عن الرسول ﷺ أن يجلس في كل الركعتين، أم لا، وما هي صفتها، وكذلك الدعاء بعد السلام، أو قبله، أو في السجود، هل يجوز أن يأتي بدعاء من نفسه، أو بما ورد عن الرسول ﷺ؟","title":"صفة صلاة الوتر","answer":"الجواب: ثبت عن النبي ﷺ أنه أوتر بثلاث مفصولة يسلم من الثنتين، وأوتر بواحدة، وهذا هو الغالب من فعله ﷺ أنه يوتر بالواحدة وحدها، ويفصل ما قبلها، وكان في الغالب يصلي إحدى عشرة، يسلم من كل ثنتين، ثم يوتر بواحدة، وربما أوتر بثلاث سردهن، لم يجلس إلا في الأخيرة، وهذا قليل، والغالب أنه يسلم من الثنتين. أما كونه يصليها كالمغرب فهذا مكروه لا ينبغي؛ لأنه تشبيه لها بالمغرب، وقد جاء في بعض الأحاديث النهي عن ذلك، فلا تصلى كالمغرب، ولكن يصليها بالتسليم من الثنتين، ثم يوتر بواحدة، أو يسردها سردًا، ويصليها جميعًا بدون جلوس إلا في الأخيرة، هذا هو المشروع، ولكن الأفضل أن يسلم من كل ثنتين، وأن تكون الواحدة مفردة مستقلة، سواء صلى ثلاثًا، أو خمسًا، أو أكثر من ذلك، نعم. المقدم: جزاكم الله خيرًا، وفيما يخص الدعاء، جزاكم الله خيرًا تسأل. الشيخ: أما الدعاء فالإنسان يدعو بما شاء، بما أحب من الدعوات الطيبة، التي ليس فيها محذور، لكن الوارد أفضل إذا تيسر له دعاء يحفظه، فهو أفضل، وله أن يدعو بحاجاته، يقول النبي ﷺ في الحديث الصحيح: ما من عبد يدعو الله بدعوة ليس فيها إثم، ولا قطيعة رحم إلا أعطاه الله بها إحدى ثلاث: إما أن تعجل له دعوته في الدنيا، وإما أن تدخر له في الآخرة، وإما أن يصرف عنه من الشر مثل ذلك قالوا: يا رسول الله! إذًا نكثر، قال: الله أكثر. فلم يحدد دعاء -عليه الصلاة والسلام- بل بين لنا كل دعاء ليس فيه إثم، ولا قطيعة رحم يرجى إجابته مطلقًا، لكن إذا تيسر له دعاء معروف عن النبي ﷺ ودعا به يكون أفضل من غيره، مثلًا في السجود يقول: اللهم اغفر لي ذنبي كله، دقه وجله، وأوله وآخره، وعلانيته وسره هذا كان يدعو به النبي ﷺ وإذا دعا بغير ذلك: اللهم يا مقلب القلوب ثبت قلبي على دينك هذا من دعاء النبي ﷺ.  وإذا دعا بقوله: اللهم اغفر لي، ولوالدي، ولجميع المسلمين؛ لا بأس، أو قال: اللهم أصلح قلبي، وعملي، أو اللهم ارزقني كسبًا حلالًا، أو زوجة صالحة، أو ذرية طيبة، أو ما أشبه ذلك من الدعوات الطبية، لا حرج في السجود، وفي آخر الصلاة، وفي كل وقت من أوقات حياته، لكن في السجود أفضل، يقول النبي ﷺ: أقرب ما يكون العبد من ربه وهو ساجد؛ فأكثروا الدعاء ويقول ﷺ: أما الركوع فعظموا فيه الرب، وأما السجود فاجتهدوا في الدعاء؛ فقمن أن يستجاب لكم يعني: فحري أن يستجاب لكم. وكان ﷺ لما علم أصحابه التحيات أرشدهم إلى الدعاء، فقال: ثم ليختر من الدعاء أعجبه إليه فيدعو وفي اللفظ الآخر: ثم ليختر من المسألة ما شاء فبين ﷺ أنه يدعو بما أحب، ولا يتقيد بالوارد، بل يدعو بما يسر الله له، لكن يكون الدعاء دعاءً طيبًا ليس فيه إثم، وليس فيه قطيعة رحم، جميع الدعوات الطيبة النافعة ولو كانت ما وردت ،ولو كان ما سمعها في الأحاديث، والحمد لله.  وهكذا في بقية الأوقات يدعو في غير الصلاة يدعو الضحى وهو جالس، أو في الظهر، أو في الليل وهو جالس، أو واقف، أو يمشي، أو يدعو في صلاة النافلة الضحى، أو في تهجده بالليل. المقصود: أن الدعاء مطلوب في الصلاة، وفي خارج الصلاة، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14792/صفة-صلاة-الوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_804/nour_80402.mp3","categories":["الوتر وقيام الليل"]},{"id":16166,"question":"يسأل ويقول: في صلاة التراويح، والقيام في شهر رمضان هل يجوز التلاوة من مصحف صغير لمن لم يتمكن من حفظ القرآن كله، علمًا بأن ذلك يتم بطريقة عادية، دون أن يسبب أي حركات تخل بالصلاة، نرجو الجواب الشافي في هذا الأمر؟ جزاكم الله خيرًا.","title":"حكم قراءة القرآن في التراويح من المصحف","answer":"الجواب: ليس هناك حرج في أن يقرأ من المصحف في صلاة التراويح، أو قيام رمضان، أو في أي صلاة إذا دعت الحاجة إلى ذلك، إذا دعت الحاجة إلى المصحف، سواء كان صغيرًا، أو كبيرًا، إذا دعت الحاجة إلى القراءة من المصحف؛ فلا بأس بذلك؛ لأن ليس كل أحد يحفظ القرآن، فإذا صلى بالناس التراويح، أو القيام من المصحف؛ فلا حرج في ذلك. وقد ثبت أن ذكوان -رحمه الله- مولى عائشة -يعني: عتيقها- كان يصلي بها في رمضان من المصحف، ومن منع ذلك ليس عنده دليل، فالصواب: أنه لا حرج في ذلك إذا دعت الحاجة إلى أن الإمام يقرأ من المصحف، أو إنسانًا في تهجده بالليل يقرأ من المصحف؛ فلا حرج في ذلك، والحمد لله. أما الفرائض يكفي فيها ما تيسر والحمد لله، وليس فيه حاجة إلى المصحف يقرأ فيها ما تيسر، ولو قرأ من المصحف في مثل صلاة الفجر، أو غيرها؛ صحت صلاته، لا حرج في ذلك، لكن الحمد لله، الغالب أنه لا يحتاج إلى المصحف في الفرائض؛ لأن القراءة فيها ميسرة، لكن لو أن إنسانًا احتاج المصحف في صلاة الفجر؛ لأنه لم يحفظ الم تنزيل السجدة وهَلْ أَتَى عَلَى الإِنسَانِ [الإنسان:1] وقرأ من المصحف ليقرأ هذه القراءة المشروعة في صباح الجمعة؛ فلا حرج في ذلك، والحمد لله، نعم. المقدم: الحمد لله، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14851/حكم-قراءة-القران-في-التراويح-من-المصحف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_805/nour_80507.mp3","categories":["الوتر وقيام الليل"]},{"id":16223,"question":"في سؤاله الأخير يقول: كم هي ركعات التهجد؟","title":"عدد ركعات التهجد","answer":"الجواب: أفضلها إحدى عشرة، أو ثلاث عشرة، يسلم من كل ثنتين، هذا فعل النبي ﷺ في الغالب -عليه الصلاة والسلام- وإن صلى أكثر: عشرين، أو أكثر، أو أقل؛ فلا بأس، ولو واحدة في كل ليلة بعد العشاء، أو في آخر الليل، لكن الأفضل إحدى عشرة، أو ثلاث عشرة، يسلم من كل ثنتين، ويوتر بواحدة، وهذا هو فعله ﷺ في الغالب -عليه الصلاة والسلام- وربما أوتر بثلاث.. ربما أوتر بخمس.. ربما أوتر بسبع، ربما أوتر بتسع -عليه الصلاة والسلام- لكن الأفضل والأغلب من فعله إحدى عشرة، أو ثلاث عشرة.  ومن أوتر بعشرين، وصلى عشرين، وأوتر بثلاث، أو بواحدة، أو أوتر بثلاثين، وصلى واحدة، أو ثلاث، كله طيب لا حرج، ليس له حد محدود، يقول النبي ﷺ: صلاة الليل مثنى مثنى، فإذا خشي الصبح؛ صلى ركعة واحدة، توتر له ما قد صلى ولم يحدد حدًا في ذلك -عليه الصلاة والسلام- نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14897/عدد-ركعات-التهجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_751/nour_75112.mp3","categories":["الوتر وقيام الليل"]},{"id":16240,"question":"من المستمعة (س. أ. ع) من الأردن رسالة ضمنتها بعض الأسئلة في أحدها تقول: كيف نصلي صلاة الوتر؟ جزاكم الله خيرًا.","title":"كيف نصلي صلاة الوتر؟","answer":"الجواب: صلاة الوتر سنة سنها الرسول الله ﷺ قولًا وفعلًا، كان يوتر من الليل -عليه الصلاة والسلام- وأرشد الناس إلى ذلك، فقال -عليه الصلاة والسلام-: صلاة الليل مثنى مثنى، فإذا خشي أحدكم الصبح؛ صلى ركعة واحدة، توتر له ما قد صلى متفق على صحته، وقال -عليه الصلاة والسلام-: الوتر حق، فمن أحب أن يوتر بخمس؛ فليفعل، ومن أحب أن يوتر بثلاث؛ فليفعل، ومن أحب أن يوتر بواحدة؛ فليفعل. وكان ﷺ يوتر كل ليلة، والغالب أنه كان يوتر بإحدى عشرة، يسلم من كل ثنتين، ويوتر بواحدة، وربما أوتر بثلاث عشرة، وربما أوتر بتسع، وربما أوتر بأقل من ذلك. فالسنة للمؤمن والمؤمنة التهجد بالليل، والإيتار في أول الليل، أو في وسطه، أو في آخره، والأفضل في آخر الليل، لقول النبي ﷺ: من خاف ألا يقوم من آخر الليل؛ فليوتر أوله، ومن طمع أن يقوم آخر الليل؛ فليوتر آخر الليل، فإن صلاة آخر الليل مشهودة، وذلك أفضل رواه مسلم في صحيحه. وقال -عليه الصلاة والسلام-: ينزل ربنا إلى سماء الدنيا كل ليلة حين يبقى ثلث الليل الآخر، فيقول: من يدعوني؛ فأستجيب له، من يسألني؛ فأعطيه، من يستغفرني؛ فأغفر له حتى يطلع الفجر متفق على صحته. وهذا النزول يليق بالله، هذا النزول يليق بالله  لا يعلم كيفيته إلا هو  كالاستواء، والضحك، والرضا، والغضب، كلها صفات تليق بالله، لا يشابه فيها خلقه  يجب أن تمر كما جاءت من غير تحريف، ولا تعطيل، ولا تكييف، ولا تمثيل، كما قال الله سبحانه: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11] وقال : وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ [الإخلاص:4] فليس نزوله كنزولنا، وليس غضبه كغضبنا، وليس ضحكه كضحكنا، وليس سمعه كأسماعنا وهكذا بقية الصفات، له الكمال المطلق  في كل شيء، لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11]. فالإيتار في آخر الليل أفضل، ولو بواحدة، لكن إذا أوتر بثلاث، أو بخمس، أو بأكثر؛ فهو أفضل، يسلم من كل ثنتين، ثم يوتر بواحدة، وإن أوتر في أول الليل قبل أن ينام؛ فلا بأس إذا كان يخشى ألا يقوم، أو في وسط الليل كله حسن، لكن أفضل ذلك آخر الليل في الثلث الأخير، هذا هو الأفضل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14936/كيف-نصلي-صلاة-الوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_807/nour_80707.mp3","categories":["الوتر وقيام الليل"]},{"id":16259,"question":"تسأل سماحتكم وتقول: حدثوني عن كيفية صلاة التهجد؟ ومتى يبدأ بالساعة تقريبًا؟ لأني لم أعرف وقتها بالضبط، وهو الثلث الأخير من الليل، وهل يجوز للمرأة أن تفعل ذلك؟ جزاكم الله خيرًا.","title":"أفضل وقت لقيام الليل","answer":"الجواب: التهجد من الليل يبدأ من صلاة العشاء، إذا فرغ من صلاة العشاء إلى طلوع الفجر، هذا هو، بل التهجد ما بين صلاة العشاء إلى طلوع الفجر، في الحديث عن خارجة بن حذافة  عن النبي ﷺ أنه قال: إن الله أمدكم بصلاة، هي خير لكم من حمر النعم، ما بين صلاة العشاء إلى طلوع الفجر فإذا أوتر الإنسان في أول الليل، أو في وسطه، أو في آخره؛ فقد فعل السنة، والأفضل في آخر الليل إذا تيسر ذلك، فإن لم يتيسر؛ أوتر في أوله قبل أن ينام لقول النبي ﷺ: من خاف ألا يقوم من آخر الليل؛ فليوتر أوله، ومن طمع أن يقوم آخر الليل؛ فليوتر آخر الليل، فإن صلاة آخر الليل مشهودة، وذلك أفضل. وقالت عائشة -رضي الله عنها-: \"من كل الليل قد أوتر رسول الله ﷺ أوتر من أوله، ومن وسطه، ومن آخره، ثم انتهى وتره إلى السحر، عليه الصلاة والسلام\" يعني: في آخر حياته استقر وتره في آخر الليل. وقال ﷺ: أفضل الصلاة صلاة داود، كان ينام نصف الليل، ويقوم ثلثه، وينام سدسه فإذا تهجد في السدس الرابع، أو السدس الخامس؛ فهذا أفضل ما يكون، وإن جعل وتره، وتهجده كله في الثلث الأخير؛ فذلك أفضل، كما في حديث جابر حيث قال ﷺ: من خاف ألا يقوم من آخر الليل؛ فليوتر أوله، ومن طمع أن يقوم آخر الليل؛ فليوتر آخر الليل، فإن صلاة آخر الليل مشهودة، وذلك أفضل. وإذا صار تهجده في السدس الرابع، والخامس؛ صار ذلك أفضل؛ لأنه يوافق صلاة داود، فيجمع بين آخر الليل في السدس الخامس، والسدس الرابع في أول النصف الأخير، وكل ذلك بحمد الله فيه خير عظيم، نعم. المقدم: الله أكبر.. الله أكبر، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14962/افضل-وقت-لقيام-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_808/nour_80811.mp3","categories":["الوتر وقيام الليل"]},{"id":16291,"question":"أيضًا تقول: سمعت أن الإنسان يقرأ في الشفع قبل الوتر: سورة الأعلى في الركعة الأولى، ويقرأ في الثانية سورة الكافرون، فهل ما سمعت صحيح؟","title":"ما يقرأ في ركعات الوتر الثلاث","answer":"الجواب: نعم، وهذا هو الأفضل، في الثلاث الأخيرة يقرأ بسبح في الأولى: سَبِّحِ اسْمَ رَبِّكَ الأَعْلَى [الأعلى:1] وفي الثانية: قُلْ يَا أَيُّهَا الْكَافِرُونَ [الكافرون:1] وفي الثالثة: قُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص:1]. والأفضل يسلم من الثنتين، ثم يفرد واحدة، وإن جمع الثلاث سردها كلها سردًا، ولم يجلس إلا في الأخيرة، فكل ذلك سنة، لكن الأفضل أن يسلم من الثنتين، ثم يوتر بواحدة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14977/ما-يقرا-في-ركعات-الوتر-الثلاث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_752/nour_75213.mp3","categories":["الوتر وقيام الليل"]},{"id":16346,"question":"أحد الإخوة المستمعين يقول: مصري مقيم في حوطة بني تميم، ما حكم تأدية سنة الوتر بعد العشاء جماعة في غير رمضان؟","title":"حكم أداء الوتر جماعة في غير رمضان","answer":"الجواب: لا حرج في ذلك إذا أدى الجماعة صلاة الوتر في غير رمضان، لكن لا يتخذ عادة، إذا اتفقوا، واجتمعوا في بيت أحد، أو في أي مكان، وصلوا جماعة؛ لا بأس، أما اتخاذه عادة، كل ليلة يجتمعون لأداء الوتر، هذا ليس بمشروع، إلا في رمضان. لكن إذا زار بعضهم بعضًا، وصلوا الوتر جماعة؛ هذا حسن -إن شاء الله- مثل ما زار سلمان أبا الدرداء، وصلى معه جماعة في الليل، رضي الله عنهما، ومثلما زار النبي ﷺ جدة أنس وصلى بـأنس واليتيم جماعة، والمرأة خلفهم، كل هذا لا بأس، الشيء الذي ليس بمعتاد، إنما عند الصدفة، والزيارة يصلون جماعة لا بأس، أما اتخاذه عادة في كل شهر، أو في كل يوم، أو في كل أسبوع هذا غير مشروع، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15040/حكم-اداء-الوتر-جماعة-في-غير-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_714/nour_71409.mp3","categories":["الوتر وقيام الليل"]},{"id":16349,"question":"بعد هذا رسالة وصلت إلى البرنامج من إحدى الأخوات تقول: أختكم في الله مسعودة سفيان، أختنا تقول: أريد أن أعرف كيفية صلاة التراويح بالنسبة للمرأة بدون إمام، أي في بيتها، هل تكون جهرًا؟ وهل تستطيع النساء أن يصلين جماعة في بيوتهن؟ جزاكم الله خيرًا.","title":"كيفية أداء صلاة التراويح للنساء في البيت","answer":"الجواب: نعم صلاة التراويح يسلم من كل ثنتين في البيوت، تصلي المرأة بهن، وتكون وسطهن، لا أمامهن، بل وسطهن، تكبر وترفع صوتها بالقراءة؛ حتى يستفدن منها، وهذا مشروع قد روي عن عائشة، وغيرها من أزواج النبي ﷺ فعل ذلك، قد أمر النبي ﷺ أم ورقة أن تؤم أهل دارها، فإذا صلى النساء في بيوتهن جماعة في رمضان، أو في الأوقات التي يصلون فيها الفريضة كله حسن، كله طيب. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15043/كيفية-اداء-صلاة-التراويح-للنساء-في-البيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_714/nour_71412.mp3","categories":["قضايا المرأة","الوتر وقيام الليل","صلاة الجماعة"]},{"id":16481,"question":"السائل أبو عبدالله من القصيم، يقول: إذا حصل مطر، فهل يجمعون المغرب والعشاء والتراويح جمع تقديم إذا كانوا في رمضان؟","title":"حكم تقديم صلاة التراويح عند الجمع لعذر","answer":"الجواب: نعم، إذا كان مطرًا، أو مشقة بالدحض، والزلق في الأسواق؛ فالأفضل الجمع تسهيلًا على الناس، وإذا جمع؛ صلى التراويح بعد... العشاء؛ لأنها صار وقتهما واحدًا، فإذا جمع بينهما في وقت المغرب؛ صلوا التراويح بعد ذلك، لا بأس والحمد لله.","link":"https://binbaz.org.sa/fatwas/15183/حكم-تقديم-صلاة-التراويح-عند-الجمع-لعذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_582/58210.mp3","categories":["الوتر وقيام الليل"]},{"id":16482,"question":"يقول في سؤاله الثاني: ما الأفضل للإمام المتقن، القراءة حفظًا، أم من المصحف، وخصوصًا في صلاة التراويح؟","title":"الأفضل في صلاة التراويح القراءة حفظًا","answer":"الجواب: إذا كان حافظًا فالأفضل عن ظهر قلب، إذا كان حافظًا يقرأ عن ظهر قلب؛ لأن هذا أجمع لقلبه على القراءة، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15186/الافضل-في-صلاة-التراويح-القراءة-حفظا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_582/58211.mp3","categories":["الوتر وقيام الليل"]},{"id":16487,"question":"بعد هذه الرسالة رسالة وصلت إلى البرنامج من اليمن، وباعثها مستمع رمز إلى اسمه بالحروف (م. أ) يقول في أحد أسئلته: صلاة الوتر هل هي بعد صلاة العشاء مباشرة، أم بعد منتصف الليل؟ ذلك لأنني أصلي الوتر الساعة الحادية عشرة بعد الانتهاء من عملي، فهل لي أن أصلي التهجد قبل طلوع الفجر؟ لأنني سمعت أناسًا يقولون: لا صلاة بعد الوتر، وأنا أصلي الوتر الحادية عشرة -كما قلت لكم من قبل- قبل النوم؛ لأنني أكثر الأيام لم أستيقظ إلا وقت صلاة الفجر، أفيدوني جزاكم الله خيرًا.","title":"ما يعمل من أوتر قبل النوم ثم قام آخر الليل؟","answer":"الجواب: وقت الوتر يبتدئ من حين تنتهي من صلاة العشاء، يدخل وقت الوتر، ما بين صلاة العشاء إلى طلوع الفجر، هذا وقت الوتر، والتهجد ما بين صلاة العشاء إلى طلوع الفجر، وإذا أوترت في جوف الليل، أو في آخر الليل؛ يكون أفضل، وآخر الليل أفضل، وقت النزول الإلهي، الثلث الأخير، أو في ... في السدس الرابع، والسدس الخامس من الليل، وقت صلاة داود -عليه الصلاة والسلام- يقول فيه النبي ﷺ: أفضل الصلاة صلاة داود يعني: النبي -عليه الصلاة والسلام- كان ينام نصف الليل، ويقوم ثلثه، وينام سدسه فهو ينام النصف الأول، ثم يقوم السدس الرابع والخامس، يتهجد فيقوم من الثلث الأوسط نصفه، ومن الثلث الأخير نصفه. وإن أوترت، تهجدت في الثلث الأخير فهو أيضًا وقت عظيم فاضل، فيه نصفه من الثلث الأخير مما كان يصلي فيه داود، والنصف الثاني من الثلث الأخير الذي قال فيه النبي ﷺ: ينزل ربنا إلى سماء الدنيا كل ليلة حين يبقى ثلث الليل الآخر، فيقول: من يدعوني فأستجيب له، من يسألني فأعطيه، من يستغفرني فأغفر له. الخلاصة: أن أفضل ما يكون للتهجد النصف الأخير مبدأ النصف الأخير إلى نهاية الليل؛ يعني: السدس الرابع، والسدس الخامس، والسادس يعني: النصف الأخير النصف الثاني. وإذا أوترت في أول الليل قبل أن تنام، ويسر الله لك القيام في آخر الليل؛ صل ما يسر الله لك، ويكفيك الوتر الأول، وتصلي ما يسر الله لك ركعتين، أو أكثر، تسلم من كل ركعتين، ولا تعيد الوتر، يكفي الوتر الأول، وكان النبي ﷺ يصلي بعد الوتر ركعتين وهو جالس؛ ليعلم الناس أنه لا حرج في ذلك. الأفضل أن يكون الوتر آخر الليل، يختم به صلاة الليل، لكن إذا أوتر في أول الليل، أو في وسطه، ثم يسر الله له القيام في آخر الليل؛ فإنه يتهجد ما يسر الله له، ويسلم من كل ركعتين، ولا يعيد الوتر، يكفيه الوتر الأول، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15195/ما-يعمل-من-اوتر-قبل-النوم-ثم-قام-اخر-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_756/nour_75606.mp3","categories":["الوتر وقيام الليل"]},{"id":16513,"question":"بالنسبة لقيام الليل هل صحيح أنه لا يصح للمصلي أن يصلي بعد صلاة الوتر مباشرة، ويجب النوم، ومن ثم الصلاة بعد ذلك؟","title":"حكم التنفل بعد صلاة الوتر","answer":"الجواب: لا حرج في الصلاة بعد الوتر، إذا أوتر الإنسان في أول الليل، أو في وسط الليل، ثم يسر الله له القيام في آخر الليل؛ فإنه يصلي ما كتب الله له، ويكفي الوتر الأول، لا يعيد الوتر لقوله ﷺ: لا وتران في ليلة وقد ثبت عن النبي ﷺ أنه صلى بعد الوتر ركعتين؛ ليبين للناس أنه لا حرج في ذلك. فالحاصل: أنه إذا أوتر في أول الليل، أو في وسطه، ثم يسر الله له القيام في آخر الليل؛ فإنه يشرع له أن يصلي ما يسر الله له، ولا يعيد الوتر، بل يكفيه الوتر الأول، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15234/حكم-التنفل-بعد-صلاة-الوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_756/nour_75615.mp3","categories":["الوتر وقيام الليل"]},{"id":16876,"question":"يسأل ويقول: هل تجوز صلاة التراويح في البيت إذا كان الإمام ليس حافظًا للقرآن، أو حافظًا لبعض السور، والبعض الآخر يخطئ فيها؟","title":"هل يجوز أداء صلاة التراويح بالبيت؟","answer":"الجواب: لا بأس بها في البيت، ولكن في المسجد أفضل، السنة أن تصلى في المساجد كما فعلها النبي ﷺ وفعلها الصحابة، وهي نافلة، لكن في المساجد أفضل، وإذا كان الإمام لا يصلح؛ يبدل بإمام أصلح منه، ولو أن يقرأ من المصحف، ولو قرأ من المصحف لا بأس، فإقامتها في المساجد هي السنة، وهي التي درج عليها السلف الصالح، ولو صلى في بيته فلا حرج، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15643/هل-يجوز-اداء-صلاة-التراويح-بالبيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_825/nour_82508.mp3","categories":["الوتر وقيام الليل"]},{"id":16985,"question":"سمعت أن القنوت ليس ضروريًا أداؤه باستمرار في صلاة الوتر، إلا أنني أرتاح في أدائه، فهل يجوز ذلك، أو لا؟","title":"هل القنوت مستحب في الوتر؟","answer":"الجواب: القنوت ليس بواجب، بل هو مستحب، فإذا تركه المؤمن أو المؤمنة بعض الأحيان؛ فلا بأس، ولكن استعماله دائمًا أولى وأفضل؛ لأن النبي ﷺ علم ابن بنته الحسن بن علي ذلك، علمه قنوت الوتر، ولم يقل له: في بعض الأحيان، بل علمه ما يدل على أنه يلازمه، ويفعله في جميع الأوقات، أن يقول: اللهم اهدني فيمن هديت .. إلى آخره، فكون الإنسان يأتي بالقنوت في الوتر في السنة كلها طيب على أصح أقوال العلماء، لا بأس، وإن ترك بعض الأحيان؛ فلا حرج. المقصود: أنه سنة ليس بواجب، والمحافظة عليه دائمًا أفضل، وأولى في ظاهر حديث الحسن بن علي، والصحابة يفعلونه تارة، ويتركونه تارة  فالأمر واسع -بحمد الله- لكن المحافظة عليه لظاهر الحديث الصحيح أولى وأفضل.  جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15797/هل-القنوت-مستحب-في-الوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_829/nour_82917.mp3","categories":["الوتر وقيام الليل","القنوت في الصلاة"]},{"id":17021,"question":"مع بداية هذه الحلقة نعود إلى رسالة المستمعة (ن. ب) من جدة، أختنا عرضنا جزءًا من أسئلتها في حلقة مضت، وبقي لها في هذه الحلقة عدد من الأسئلة، في أحدها تقول: إنني -ولله الحمد- أقوم الليل، إلا أنني أوتر بعد أداء سنة العشاء؛ وذلك خوفًا من أن يقبض الله روحي قبل أدائها؛ وخوفًا من أن يغلبني النوم فلا أستطيع أداءها، فبماذا تنصحونني، وهل ما أنا عليه صحيح؟","title":"حكم صلاة الوتر في أول الليل ثم القيام في آخره","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فقيام الليل من أفضل القربات، ومن صفات عباد الرحمن الأخيار، ومن صفات المتقين، قال الله -جل وعلا- في كتابه العظيم: إِنَّ الْمُتَّقِينَ فِي جَنَّاتٍ وَعُيُونٍ ۝ آخِذِينَ مَا آتَاهُمْ رَبُّهُمْ إِنَّهُمْ كَانُوا قَبْلَ ذَلِكَ مُحْسِنِينَ ۝ كَانُوا قَلِيلًا مِنَ اللَّيْلِ مَا يَهْجَعُونَ ۝ وَبِالأَسْحَارِ هُمْ يَسْتَغْفِرُونَ [الذاريات:15-18] وقال سبحانه في صفات عباد الرحمن: وَالَّذِينَ يَبِيتُونَ لِرَبِّهِمْ سُجَّدًا وَقِيَامًا [الفرقان:64]. فأنت على خير، فنوصيك بالثبات، وسؤال الله القبول، وعليك بالاستقامة، ولكن الأفضل لك أن تجعلي الوتر آخر الليل، ما دمت تقومين آخر الليل؛ فاجعلي الوتر آخر الليل، وأحسني الظن بالله، أحسني الظن بالله، وأبشري بالخير، ما دمت قد اعتدت هذا الخير، وتقومي آخر الليل؛ فاجعلي وترك آخر الليل؛ لقول النبي ﷺ في الحديث الصحيح: من خاف ألا يقوم من آخر الليل؛ فليوتر أوله، ومن طمع أن يقوم آخر الليل فليوتر آخر الليل، فإن صلاة آخر الليل مشهودة، وذلك أفضل.  بين ﷺ أن صلاة آخر الليل مشهودة، وأنها أفضل من أول الليل، وأنت -بحمد الله- تطمعين أن تقومي، وقد اعتدت القيام؛ فأخري الوتر في آخر الليل. وإذا غلبك نوم؛ صليتي من النهار ما يقابل ذلك شفعًا دون وتر، كما كان النبي يفعل ﷺ كان إذا غلبه نوم، أو وجع صلى من النهار ثنتي عشرة ركعة، وكانت عادته ﷺ غالبًا إحدى عشرة ركعة، فإذا شغله نوم، أو مرض؛ زاد واحدة، صلى ثنتي عشرة ركعة، هكذا روت عائشة -رضي الله عنها- في صحيح مسلم.  والمؤمن يجب أن يكون حسن الظن بالله  فعليك بحسن الظن بالله، والاجتهاد في الخير، وأن تكون صلاتك آخر الليل مع الوتر لهذا الحديث الصحيح، ولقوله ﷺ في الحديث الصحيح: ينزل ربنا إلى سماء الدنيا كل ليلة حين يبقى ثلث الليل الآخر، فيقول: من يدعوني فأستجيب له؟ من يسألني فأعطيه؟ من يستغفرني فأغفر له؟ وهذا الحديث العظيم متواتر عن النبي ﷺ وهو يدل على فضل آخر الليل، وأن العبادة فيه لها شأن عظيم، وأن دعاء العبد حري بالاستجابة، وهكذا توبته، واستغفاره. وهذا النزول نزول يليق بجلال الله -جل وعلا- لا يشابه خلقه في شيء من صفاته  فهو في نزوله كسائر صفاته كالاستواء، والكلام، والغضب، والرضا، وغير ذلك، كلها صفات تليق بالله، لا يشابه فيها خلقه  فكما قال السلف في الاستواء: أنه على الوجه اللائق بالله، فهكذا النزول، وهكذا بقية الصفات، يقول -جل وعلا-: الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى [طه:5].  سئل مالك -رحمه الله- الإمام المشهور، إمام دار الهجرة في زمانه مالك بن أنس، قيل له: يا أبا عبدالله: الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى [طه:5] كيف استوى؟ قال: الاستواء معلوم، والكيف مجهول، والإيمان به واجب، وهكذا روي عن أم سلمة أم المؤمنين، وعن ربيعة شيخ مالك أنهم قالوا هذا المعنى: الاستواء غير مجهول، والكيف غير معقول، وهكذا النزول معروف، والكيف مجهول، ينزل: كما يشاء  نزولًا يليق بجلاله، لا يشابه خلقه في صفاته  وهكذا يتكلم إذا شاء كلامًا يليق بجلاله، ويغضب إذا شاء على أهل معصيته، والكفر به غضبًا يليق بجلاله، لا يشابه غضب المخلوقين.  وهكذا رضاه، وهكذا سائر الصفات  كلها يجب أن تمر كما جاءت مع الإيمان بها، واعتقاد أنها حق، وأنها تليق بالله، لا يشابه فيها خلقه، ولا يعلم كيفيتها إلا هو . المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15807/حكم-صلاة-الوتر-في-اول-الليل-ثم-القيام-في-اخره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_830/nour_83002.mp3","categories":["الوتر وقيام الليل"]},{"id":17137,"question":"من المستمع أحمد عوض زائد من جمهورية مصر العربية رسالة وضمنها سؤالين، في سؤاله الأول يقول: أرجو من سماحتكم إرشادي عن صلاة التراويح، هل الأفضل فيها أن يصلي المرء منفردًا، أم لا بد من الجماعة، وهل لا بد أن تكون القراءة جهرية، جزاكم الله خيرًا؟","title":"هل الأفضل صلاة التراويح في جماعة؟ وحكم الجهر بالقراءة","answer":"الجواب: الجماعة أفضل، كونه يصلي جماعة التراويح في رمضان، يصليها جماعة كما صلاها النبي ﷺ والصحابة أفضل، والقراءة تكون جهرية أفضل، وإن أسر فلا حرج، لكن الجهرية هو السنة، النبي ﷺ جهر والصحابة جهروا، صلاة الليل كلها جهرية، وصلاة النهار سرية، إلا صلاة الفجر فإنها جهرية، وصلاة الجمعة جهرية، وصلاة العيد جهرية، وصلاة الكسوف جهرية، وصلاة الاستسقاء جهرية، وإن كانت في النهار، لكن صلاة الظهر والعصر سرية. فالمقصود: أن السنة في التراويح أن تصلي مع الجماعة في المساجد، هذا هو الأفضل، تأسيًا بالنبي ﷺ وبالصحابة  والسنة للإمام أن يجهر بالقراءة، وإن صليت في بيتك فلا بأس، والسنة أن تجهر بالقراءة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16029/هل-الافضل-صلاة-التراويح-في-جماعة-وحكم-الجهر-بالقراءة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_832/nour_83210.mp3","categories":["الوتر وقيام الليل"]},{"id":17143,"question":"يقول: أرجو إرشادي عن صلاة التهجد إذ أني أصليها في الحادية عشرة ليلًا، وأتلو فيها القرآن جهرًا، هل لها ميعاد غير ذلك؟","title":"ما الوقت الأفضل لصلاة التهجد؟","answer":"الجواب: الصلاة في جوف الليل، وآخر الليل أفضل، وإن صليتها في أوله قبل أن تنام فلا بأس، والصلاة في جوف الليل أفضل، وفي آخر الليل أفضل وأفضل، وإن صليتها بعد صلاة العشاء قبل أن تنام خوفًا أن لا تقوم فلا بأس بذلك. المقدم: جزاكم الله خيرًا، يقول..  الشيخ: أعد، أعد.. أعد السؤال. المقدم: يقول: أرجو إرشادي عن صلاة التهجد إذ أني أصليها في الحادية عشرة ليلًا، وأقرأ فيها القرآن جهرًا، هل هناك وقت أفضل من ذلك؟ الشيخ: آخر الليل أفضل، في جوف الليل طيب، لكن آخر الليل أفضل، لقول النبي ﷺ: من خاف ألا يقوم من آخر الليل؛ فليوتر أوله، ومن طمع أن يقوم آخر الليل؛ فليوتر آخر الليل، فإن صلاة آخر الليل مشهودة وذلك أفضل رواه مسلم في صحيحه؛ ولقوله ﷺ: ينزل ربنا إلى سماء الدنيا كل ليلة، حين يبقى ثلث الليل الآخر، فيقول: من يدعوني فأستجيب له، من يسألني فأعطيه، من يستغفرني فأغفر له وفي لفظ آخر يقول -جل وعلا-: هل من سائل فيعطى سؤله، هل من مستغفر فيغفر له، هل من تائب فيتاب عليه هذا في الثلث الأخير، وهذا أفضل الأوقات للتهجد، والعبادة. وهذا النزول يليق بالله، لا يشابه نزول المخلوقين، هذا النزول ثابت في الأحاديث الصحيحة المتواترة، وهو نزول يليق بالله، مثل الاستواء، ومثل الغضب، والرضا كلها تليق بالله، لا يشابه خلقه في استوائه على عرشه، ولا يشابه خلقه في غضبه، ورضاه، ولا يشابه خلقه في كلامه، ومحبته، ونحو ذلك، وهكذا النزول، نزول يليق بالله، لا يعلم كيفيته إلا هو  لكنه لا يشابه خلقه في شيء من الصفات، لقوله سبحانه: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11] ولقوله سبحانه: فَلا تَضْرِبُوا لِلَّهِ الأَمْثَالَ [النحل:74] وقوله : قُلْ هُوَ اللَّهُ أَحَدٌ ۝ اللَّهُ الصَّمَدُ ۝ لَمْ يَلِدْ وَلَمْ يُولَدْ ۝ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ[الإخلاص:4]  وهذه قاعدة عند أهل السنة والجماعة، قاعدة أن جميع أسماء الرب، وصفاته كلها تليق به، وأسماؤه كلها نعوت.. كلها صفات: الرحمن.. الرحيم.. العليم.. الحكيم.. السميع.. البصير، هي أسماء، وهي نعوت، وصفات، كلها تليق بالله، يجب إثباتها لله إثباتًا بريئًا من التمثيل، ويجب أن ينزه الله سبحانه عن مشابهة خلقه تنزيهًا بريئًا من التعطيل. فأهل الحق من أهل السنة والجماعة يثبتون صفات الله، وأسماءه، ويمرونها كما جاءت، مع الإيمان بها، واعتقاد أنها حق على الوجه اللائق به سبحانه، لا يشابه خلقه في شيء من صفاته -جل وعلا- هذا هو قول أهل الحق من أهل السنة، والجماعة من الصحابة، وأتباعهم، والتابعين، وأتباع التابعين، كمالك، والشافعي، وأحمد، وأبي حنيفة، والثوري، وغيرهم من أئمة الإسلام، كلهم هذه عقيدتهم تابعين في ذلك للنبي ﷺ ولأصحابه  وأرضاهم. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16031/ما-الوقت-الافضل-لصلاة-التهجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_832/nour_83211.mp3","categories":["الوتر وقيام الليل"]},{"id":17468,"question":"بالنسبة للوتر، مرة، أو مرتين حدث وأنا أصلي الوتر أن أذن الفجر، وأحيانًا بعد السلام يكون الأذان في بدايته، هل علي إعادة هذا الوتر؟","title":"هل يُعاد الوتر إذا أُذن للفجر أثناء تأديته؟","answer":"الجواب: يكفي؛ لأن الأذان يكون على الظن، ظن الصبح، فإذا أذن والإنسان في الوتر؛ كمله، والحمد لله، ولا بأس يكفي، نعم. المقدم: جزاكم الله خيرًا، و أحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16336/هل-يعاد-الوتر-اذا-اذن-للفجر-اثناء-تاديته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_725/nour_72505.mp3","categories":["الوتر وقيام الليل"]},{"id":17471,"question":"بالنسبة لمسك المصحف للقراءة منه في صلاة القيام هل هذا جائز يا شيخ؟","title":"حكم القراءة من المصحف في صلاة القيام","answer":"الجواب: لا حرج أن يقرأ من المصحف في صلاة القيام في التراويح في القيام، أو في غيرهما، لا بأس إذا احتاج إلى ذلك، كان مولى عائشة -رضي الله عنها- يصلي بها في رمضان من المصحف، نعم.  المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16374/حكم-القراءة-من-المصحف-في-صلاة-القيام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_773/nour_77307.mp3","categories":["الوتر وقيام الليل"]},{"id":17696,"question":"هذا سائل يقول: سماحة الشيخ! البكاء من خشية الله أمر طيب ولكن في صلاة التراويح نسمع بكاءً مرتفعًا يشوش على المصلين، فما حكم هذا البكاء المرتفع؟ جزاكم الله خيرًا.","title":"حكم رفع الصوت بالبكاء أثناء التراويح","answer":"الجواب: المشروع للمؤمن أن يجاهد نفسه حتى لا يشغل المصلين ببكائه ويكون بكاءه بصوت منخفض، هذا هو المشروع له، ولهذا كان عليه الصلاة والسلام يسمع لصدره أزيز كأزيز المرجل من البكاء ولكن لا يكون رفيع يؤذي الناس، وربما دمعت عيناه من دون صوت. فالحاصل أن المؤمن يجاهد نفسه حتى لا يتأذى أحد ببكائه، وأما إذا غلبه ولم يستطع فهذا لا يضره ذلك. نعم. المقدم: أحسن الله إليكم وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16647/حكم-رفع-الصوت-بالبكاء-اثناء-التراويح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_776/nour_77607.mp3","categories":["الوتر وقيام الليل"]},{"id":17790,"question":"السائلة أم خالد من الباحة استعرضنا سؤالاً لها وفي هذا السؤال تقول: أنا أوتر قبل النوم خوفًا من أن أنام ولا أوتر؛ اقتداءً بقوله ﷺ: أوتروا يا أهل القرآن وإذا حصل ونهضت قبل الفجر فإني أصلي أربعًا أو ستًا أو ما تيسر لي من الركعات ولكنني لا أوتر؛ لأنني أوترت قبل النوم، فهل عملي هذا صحيح؟","title":"حكم من أوتر أول الليل ثم أراد القيام في آخره","answer":"نعم، هذا العمل صحيح، الإنسان إذا خاف أن لا يقوم من آخر الليل يوتر أول الليل، وإذا يسر الله له القيام في آخر الليل يصلي ما تيسر ثنتين أو أربعًا أو ستًا أو أكثر يسلم من كل ثنتين يقول النبي ﷺ: من خاف أن لا يقوم من آخر الليل فليوتر أوله، ومن طمع أن يقوم آخر الليل فليوتر آخر الليل، فإن صلاة آخر الليل مشهودة وذلك أفضل.","link":"https://binbaz.org.sa/fatwas/16783/حكم-من-اوتر-اول-الليل-ثم-اراد-القيام-في-اخره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_778/nour_77812.mp3","categories":["الوتر وقيام الليل"]},{"id":17870,"question":"من إحدى الأخوات المستمعات رسالة سمت نفسها أمة الله أم عبد الرحمن من المنطقة الشرقية، تسأل عن كيفية قضاء الوتر في النهار إذا نام عنه صاحبه؛ لأنه بلغنا أن بعض العلماء يقول بقضاء الوتر؟ جزاكم الله خيرًا.","title":"كيفية قضاء الوتر","answer":"السنة أن يقضى الوتر، كان النبي ﷺ إذا شغله مرض أو نوم عن وتره من الليل صلى من النهار، تقول عائشة رضي الله عنها: \"كان النبي ﷺ إذا شغله عن وتره مرض أو نوم صلى من النهار ثنتي عشرة ركعة\"، وكان وتره في الغالب إحدى عشرة، فإذا شغله عنه شاغل صلى ثنتي عشرة، زاد واحدة، فهذا هو السنة، أنه يقضى من النهار ولكن شفعًا لا وترًا، يزيدها ركعة اقتداءً بالنبي ﷺ، فإذا كانت عادته في الليل ثلاث ركعات تسليمة واحدة صلى من النهار أربع ركعات تسليمتين، وإذا كانت عادته خمس ركعات صلى من النهار ست ركعات ثلاث تسليمات، وإذا كانت عادته سبع ركعات من الليل صلى من النهار ثمان ركعات أربع تسليمات وهكذا، وإذا كانت عادته إحدى عشرة كفعل النبي ﷺ صلى من النهار ثنتي عشرة ركعة ست تسليمات، وإذا كانت عادته ثلاثة عشر صلى من النهار سبع تسليمات أربعة عشر، هذا هو الأفضل، وهو سنة نافلة ليس بواجب. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16890/كيفية-قضاء-الوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_845/nour_84507.mp3","categories":["قضاء الفوائت","الوتر وقيام الليل"]},{"id":17872,"question":"رأيت بعض الناس يصلون التراويح ثمان ركعات والبعض الآخر عشرين ركعة؟","title":"كم عدد ركعات التراويح؟","answer":"الأمر واسع والحمد لله، من صلى ثمانًا أو عشرًا أو عشرين ثم أوتر كله طيب فلا حرج في ذلك، ولكن الأفضل أن يصلي ثمانًا مع الوتر ثلاث إحدى عشرة، أو عشرًا مع الوتر ثلاثًا تكون ثلاث عشرة؛ لأن هذا هو المحفوظ عن النبي ﷺ في الأغلب، كان يوتر بإحدى عشرة وربما أوتر بثلاث عشرة، هذا هو الأغلب وربما أوتر بأقل من ذلك، فكون الإمام أو المنفرد يتحرى ذلك أفضل، ومن صلى عشرين أو أكثر فلا حرج. وقد ثبت عن عمر والصحابة  وأرضاهم أنهم صلوا عشرين بالوتر ثلاثًا، وصلوا إحدى عشرة.. صلوا هذا وهذا، وكله بحمد الله واسع؛ لأن النبي ﷺ لم يحدد حدًا في ذلك بل قال: صلاة الليل مثنى مثنى، فإذا خشي أحدكم الصبح صلى ركعة واحدة توتر له ما قد صلى فلم يحدد فظاهره أنه إذا صلى عشرين أو ثلاثين أو أربعين فلا حرج ثم يوتر بواحدة والحمد لله. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16877/كم-عدد-ركعات-التراويح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_845/nour_84504.mp3","categories":["الوتر وقيام الليل"]},{"id":18217,"question":"أعرفكم بأنني مداوم -والحمد لله- على صلاة الليل، لكني أرجو أن تعرفوني عن صلاة القيام في الوقت المحدد؟ وكم عدد ركعاتها؟ جزاكم الله خيرًا.","title":"فضل قيام الليل وأحكامه","answer":"الجواب: قيام الليل سنة مؤكدة، ومن عمل الصالحين، وهو دأب الصالحين، وهو من فعله ﷺ ومما كان يداوم عليه -عليه الصلاة والسلام- والله يقول في مدح عباد الرحمن، ويثني عليهم، فيقول: وَالَّذِينَ يَبِيتُونَ لِرَبِّهِمْ سُجَّدًا وَقِيَامًا [الفرقان:64]، ويقول في صفة المتقين: كَانُوا قَلِيلًا مِنَ اللَّيْلِ مَا يَهْجَعُونَ ۝ وَبِالأَسْحَارِ هُمْ يَسْتَغْفِرُونَ [الذاريات:17-18]، والله يقول لنبيه ﷺ: يَا أَيُّهَا الْمُزَّمِّلُ ۝ قُمِ اللَّيْلَ إِلَّا قَلِيلًا ۝ نِصْفَهُ أَوِ انْقُصْ مِنْهُ قَلِيلًا ۝ أَوْ زِدْ عَلَيْهِ وَرَتِّلِ الْقُرْآنَ تَرْتِيلًا [المزمل:1-4]. فالسنة قيام الليل، وآخر الليل أفضل من أوله، وإذا لم يتيسر له آخر الليل، أوتر في أول الليل، والوتر سنة مؤكدة، أقله ركعة، أقله ركعة واحدة، وإن أوتر بثلاث، أو بخمس، أو بأكثر؛ فهو أفضل، يسلم من كل ثنتين، هذا هو السنة، يسلم من كل ثنتين، وأفضله إحدى عشر ركعة، أو ثلاث عشر ركعة، النبي ﷺ كان النبي يوتر بإحدى عشرة، وربما أوتر بثلاث عشرة عليه الصلاة والسلام، هذا هو أفضل الوتر، يسلم من كل ثنتين، ويوتر بواحدة، وإن أوتر بأكثر: أوتر بعشرين، أو بأكثر؛ فلا بأس، الأمر واسع، كله سنة. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17262/فضل-قيام-الليل-واحكامه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_731/nour_73122.mp3","categories":["فضائل الأعمال","الوتر وقيام الليل"]},{"id":18306,"question":"تقول: أنا عندما أصلي الشفع، وأوتر في بعض الأحيان، لا أدعو بعد الركوع من الوتر، فقط أسجد، ثم أسلم، هل صلاتي صحيحة؟ أم أن هناك غير ذلك؟ وهل يجوز لي أن أدعو بعد التشهد من الوتر، بدلًا من كوني أدعو بعد الركوع؟ أفتوني جزاكم الله خيرًا.","title":"هل يصح الوتر دون دعاء القنوت وحكم الدعاء قبل التسليم","answer":"الجواب: القنوت مستحب بالوتر، ليس بواجب، لكن يستحب لمن حفظه أن يقنت في الوتر بعد الركوع في الركعة الأخيرة، وهي الواحدة التي يوتر بها في أول الليل، أو في آخره، يقنت بقوله: اللهم اهدني فيمن هديت، وعافني فيمن عافيت.. إلى آخره؛ لأن الرسول ﷺ علمه ابن بنته الحسن، وتعليم النبي ﷺ لواحد، تعليم للجميع، فإذا تيسر ذلك فهو أفضل، وإلا فلا حرج، والحمد لله، فليس بواجب، وإذا دعا الإنسان بعد التشهد، قبل أن يسلم؛ فهذا مستحب أيضًا، الدعاء في آخر التحيات، قبل أن يسلم، النبي ﷺ علم الصحابة، لما علمهم التشهد قال ﷺ: ثم ليتخير من الدعاء أعجبه إليه فيدعو، وفي اللفظ الآخر: ثم ليختر من المسألة ما شاء. وكان النبي يدعو ﷺ في صلاته، في آخر التحيات، قبل أن يسلم، بعد التشهد، وبعد الصلاة على النبي ﷺ، يدعو، ويستحب أنه يقرأ التحيات، ثم يصلي على النبي ﷺ، ثم يستعيذ بالله من عذاب جهنم، ومن عذاب القبر، ومن فتنة المحيا والممات، ومن فتنة المسيح الدجال ، ثم يدعو بما يسر الله من الدعوات الطيبة، الواردة عن النبي ﷺ، مثل: اللهم أعني على ذكرك، وشكرك، وحسن عبادتك، اللهم إني ظلمت نفسي ظلمًا كثيرًا، ولا يغفر الذنوب إلا أنت، فاغفر لي مغفرة من عندك، وارحمني، إنك أنت الغفور الرحيم، هذا دعاء عظيم. كذلك الدعاء بما ثبت عنه ﷺ في البخاري: اللهم إني أعوذ بك من البخل، وأعوذ بك من الجبن، وأعوذ بك أن أرد إلى أرذل العمر، وأعوذ بك من فتنة الدنيا، ومن عذاب القبر، كل هذا قبل السلام يستحب، قبل أن يسلم، يجتهد في الدعاء، ومن أفضل ذلك ما تقدم: اللهم أعني على ذكرك، وشكرك، وحسن عبادتك -للرجل والمرأة- اللهم إني ظلمت نفسي ظلمًا كثيرًا، ولا يغفر الذنوب إلا أنت، فاغفر لي مغفرةً من عندك، وارحمني، إنك أنت الغفور الرحيم، اللهم إني أعوذ بك من البخل، وأعوذ بك من الجبن، وأعوذ بك أن أرد إلى أرذل العمر، وأعوذ بك من فتنة الدنيا، وأعوذ بك من عذاب القبر. ومن الدعاء أيضًا في آخر الصلاة، قبل السلام: اللهم اغفر لي ما قدمت، وما أخرت، وما أسررت، وما أعلنت، وما أسرفت، وما أنت أعلم به مني، أنت المقدم، وأنت المؤخر، لا إله إلا أنت، كل هذا حسن، دعوات في آخر الصلاة قبل السلام، أما القنوت فهو مستحب في الوتر، في الركعة الأخيرة بعد الركوع، ومن تركه فلا حرج عليه. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17355/هل-يصح-الوتر-دون-دعاء-القنوت-وحكم-الدعاء-قبل-التسليم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_732/nour_73203.mp3","categories":["الأدعية والأذكار","الوتر وقيام الليل","القنوت في الصلاة"]},{"id":18359,"question":"سماحة الشيخ! كيف يكون قيام الليل؟ أرجو بيان كيفية ذلك؟ وأين يكون موقع الدعاء والتسبيح، مفصلًا؟ جزاكم الله خيرًا.","title":"ما كيفية قيام الليل والدعاء والتسبيح فيه؟","answer":"قيام الليل سنة مؤكدة، فعله النبي ﷺ وفعله الأخيار، كما قال الله  عن نبيه ﷺ: يَا أَيُّهَا الْمُزَّمِّلُ ۝ قُمِ اللَّيْلَ إِلَّا قَلِيلًا [المزمل:1-2]، وقال سبحانه، يخاطب نبيه ﷺ: وَمِنَ اللَّيْلِ فَتَهَجَّدْ بِهِ نَافِلَةً لَكَ[الإسراء:79]، ومدح المؤمنين، عباد الرحمن بذلك، فقال سبحانه: وَالَّذِينَ يَبِيتُونَ لِرَبِّهِمْ سُجَّدًا وَقِيَامًا[الفرقان:64]، وقال أيضًا عن المتقين: كَانُوا قَلِيلًا مِنَ اللَّيْلِ مَا يَهْجَعُونَ ۝ وَبِالأَسْحَارِ هُمْ يَسْتَغْفِرُونَ [الذاريات:17-18]. وإن سرد ثلاثًا جميعًا، بسلام واحد، وجلسة واحدة في آخرها؛ فلا بأس، فعله النبي ﷺ في بعض الأحيان، أوتر بخمس جميعًا، بغير جلوس، إلا في آخرها، فلا بأس، قد فعله النبي ﷺ في بعض الأحيان، لكن الأفضل أن يسلم من كل ثنتين. والأفضل وتره ﷺ إحدى عشرة، أو ثلاث عشرة، هذا هو الأفضل، ومن أوتر بعشرين، أو بأكثر، وزاد الوتر؛ فلا بأس، سواء أوتر بثلاث وعشرين، أو بسبعٍ وعشرين، أو بإحدى وثلاثين، أو بأكثر، كله لا بأس به، الله وسع في صلاة في الليل، لكن السنة أن يسلم من كل ثنتين، لقول النبي ﷺ: صلاة الليل مثنى مثنى، فإذا خشي أحدكم الصبح؛ صلى ركعةً واحدة، توتر له ما قد صلى. فالسنة هكذا، يصلي ثنتين ثنتين، فإذا خشي الصبح أوتر بواحدة، تقول عائشة رضي الله عنها كان النبي ﷺ يوتر بإحدى عشرة -يعني: غالبًا- ويسلم من كل ثنتين، عليه الصلاة والسلام. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17420/ما-كيفية-قيام-الليل-والدعاء-والتسبيح-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_732/nour_73210.mp3","categories":["الوتر وقيام الليل"]},{"id":18408,"question":"بعد هذا ننتقل إلى رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات تقول المرسلة: أختكم في الله الحربي، أختنا لها عدد كبير من الأسئلة في أحدها تقول: أصلي في الليل ركعتين وأصلي ثلاثًا وترًا، هل هذا يجوز؟","title":"ما أقل عدد لركعات الوتر؟","answer":"الجواب: نعم، الوتر أقله ركعة فمن أوتر بركعة أو بثلاث أو بأكثر فقد أصاب وأحسن، وأقله ركعة الحمد لله. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17482/ما-اقل-عدد-لركعات-الوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_733/nour_73303.mp3","categories":["الوتر وقيام الليل"]},{"id":18411,"question":"هل ورد أحاديث في قراءة سورة الأعلى، والكافرون، والإخلاص في الشفع والوتر هذا في رمضان؟ وماذا يلزم الإمام في رمضان؟ هل يستمر في قراءة هذه السور يا شيخ؟","title":"المشروع قراءته في صلاة الوتر","answer":"الجواب: هذا هو الأفضل، نعم، ثبت أن النبي ﷺ أنه كان يقرأ في الثلاث الأخيرة بسبح وقل يا أيها الكافرون وقل هو الله أحد، فإذا أوتر بثلاث قرأ في الأولى بسبح، وفي الثانية بـ (الكافرون)، وفي الثالثة بـ قل هو الله أحد هذا هو الأفضل، وإن قرأ بغيرها فلا حرج، الأمر واسع؛ لأن الله قال: فَاقْرَءُوا مَا تَيَسَّرَ مِنْهُ[المزمل:20] وإذا سرد الركعات وسلم من كل ثنتين ثم أوتر بواحدة فكل ذلك حسن، وإن لم يقرأ سبح ...... المقصود أنه يصلي ثنتين ثنتين ثم يوتر بواحدة، والأفضل في الواحدة أن يقرأ فيها بعد الفاتحة قل هو الله أحد تأسيًا بالنبي عليه الصلاة والسلام، ولو قرأ بغير ذلك فلا حرج لعموم قوله جل وعلا: فَاقْرَءُوا مَا تَيَسَّرَ مِنْهُ[المزمل:20] وقوله ﷺ للمسيء: ثم اقرأ بما تيسر لك من القرآن فالأمر في هذا واسع والحمد لله. نعم. المقدم: أحسن الله إليكم وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17498/المشروع-قراءته-في-صلاة-الوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_784/nour_78419.mp3","categories":["الوتر وقيام الليل"]},{"id":18465,"question":"تقول السائلة: ما الحكم إذا تركت المرأة صلاة الوتر مع العشاء على أمل أن تصليها عند قيام الليل، ولكنها أحيانًا لا تقوم، فهل يصح لها أن تصليها مع صلاة الفجر؛ علمًا بأنها تقدم الوتر، ثم السنة، ثم الفريضة للفجر، فهل هذا العمل صحيح؟","title":"كيفية قضاء الوتر لمن فاته قبل الفجر","answer":"إذا فاتها قيام الليل وطلع الفجر تصلي من النهار بعد طلوع الشمس، تصلي الضحى ما فاتها من الورد من الليل، تقول عائشة رضي الله عنها: \"كان النبي ﷺ إذا فاته ورده من الليل لنوم أو مرض صلاه من النهار\"، فالمرأة والرجل إذا ناما عن وردهما من الليل شرع لهما أن يصلياه من النهار قبل الظهر أفضل، وفي الحديث الصحيح: من نام عن حزبه بالليل ثم قضاه قبل الظهر فكأنما قرأه من الليل كما في حديث عمر . المقدم: أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17552/كيفية-قضاء-الوتر-لمن-فاته-قبل-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_785/nour_78511.mp3","categories":["الوتر وقيام الليل"]},{"id":18521,"question":"أختنا تسأل في سؤال آخر وتقول: هل تجوز صلاة النوافل ما بين صلاة العشاء والوتر وصلاة الفجر؟ لأنني أسمع من البعض يقولون: لا يجوز صلاة بعد الوتر حتى الفجر، والبعض يقولون: النوم يفصل بينها.وأحد الشيوخ في بلدنا قال: يمكن الصلاة قبل الفجر ما بين الأذانين الأول والثاني للفجر، والبعض يقول: لا يجوز وإنني غالبًا ما أستيقظ قبل الفجر، وأريد أن أصلي ولا أدري هل يجوز أم لا؟","title":"هل تجوز صلاة النافلة بعد الوتر؟","answer":"نعم، لا بأس بالصلاة بعد الوتر، إذا أوتر الإنسان في أول الليل، أو في وسط الليل، ثم يسر الله له القيام في آخر الليل، فإنه يشرع له أن يصلي ما قسم الله له، ركعتين أو أكثر من ذلك، ويكفيه الوتر الأول لا حاجة إلى وتر ثانٍ، يقول النبي ﷺ: لا وتران في ليلة فإذا استيقظ المؤمن أو المؤمنة في آخر الليل، وقد أوتر في أول الليل، فإنه يشرع له أن يصلي ما كتب الله له، ولا يعيد الوتر الأول. فإذا صلى ركعتين أو أربع أو أكثر كل هذا طيب ولا بأس به، لكن يكون مثنى مثنى؛ لقول النبي ﷺ: صلاة الليل مثنى مثنى يعني: ثنتين ثنتين، وقد ثبت عنه ﷺ أنه صلى ركعتين بعدما أوتر في آخر الليل ليعلم الناس أن الصلاة بعد الوتر جائزة، وإنما الأفضل أن يكون الوتر آخر الشيء، كما قال ﷺ: اجعلوا آخر صلاتكم بالليل وترًا، فالأفضل أن يكون الوتر هو آخر شيء، لكن إذا صار هناك سعة وصلى بعد الوتر ركعتين أو أكثر، فلا حرج في ذلك، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17624/هل-تجوز-صلاة-النافلة-بعد-الوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_869/nour_86908.mp3","categories":["الوتر وقيام الليل"]},{"id":18530,"question":"أختنا تسأل في سؤال آخر وتقول: هل تجوز صلاة النوافل ما بين صلاة العشاء والوتر وصلاة الفجر؟ لأنني أسمع من البعض يقولون: لا يجوز صلاة بعد الوتر حتى الفجر، والبعض يقولون: النوم يفصل بينها.وأحد الشيوخ في بلدنا قال: يمكن الصلاة قبل الفجر ما بين الأذانين الأول والثاني للفجر، والبعض يقول: لا يجوز وإنني غالبًا ما أستيقظ قبل الفجر، وأريد أن أصلي ولا أدري هل يجوز أم لا؟","title":"هل تجوز صلاة النافلة بعد الوتر؟","answer":"نعم، لا بأس بالصلاة بعد الوتر، إذا أوتر الإنسان في أول الليل، أو في وسط الليل، ثم يسر الله له القيام في آخر الليل، فإنه يشرع له أن يصلي ما قسم الله له، ركعتين أو أكثر من ذلك، ويكفيه الوتر الأول لا حاجة إلى وتر ثانٍ، يقول النبي ﷺ: لا وتران في ليلة فإذا استيقظ المؤمن أو المؤمنة في آخر الليل، وقد أوتر في أول الليل، فإنه يشرع له أن يصلي ما كتب الله له، ولا يعيد الوتر الأول. فإذا صلى ركعتين أو أربع أو أكثر كل هذا طيب ولا بأس به، لكن يكون مثنى مثنى؛ لقول النبي ﷺ: صلاة الليل مثنى مثنى يعني: ثنتين ثنتين، وقد ثبت عنه ﷺ أنه صلى ركعتين بعدما أوتر في آخر الليل ليعلم الناس أن الصلاة بعد الوتر جائزة، وإنما الأفضل أن يكون الوتر آخر الشيء، كما قال ﷺ: اجعلوا آخر صلاتكم بالليل وترًا، فالأفضل أن يكون الوتر هو آخر شيء، لكن إذا صار هناك سعة وصلى بعد الوتر ركعتين أو أكثر، فلا حرج في ذلك، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17624/هل-تجوز-صلاة-النافلة-بعد-الوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_869/nour_86908.mp3","categories":["الوتر وقيام الليل"]},{"id":18569,"question":"تقول الأخت السائلة في آخر أسئلتها: ما حكم دعاء القنوت في الوتر؟ هل هو واجب يوميًا؟","title":"ما حكم دعاء القنوت في الوتر؟ هل هو واجب يوميًا؟","answer":"الجواب: مستحب وليس بواجب، دعاء القنوت في النوازل وفي الوتر مستحب فقط، وإذا تركه بعض الأحيان حسن.","link":"https://binbaz.org.sa/fatwas/17683/ما-حكم-دعاء-القنوت-في-الوتر-هل-هو-واجب-يوميا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_918/nour_91803.mp3","categories":["الوتر وقيام الليل"]},{"id":18608,"question":"يقول في هذا  هل عدد ركعات التراويح ثلاثة عشر ركعة أو واحد وعشرين ركعة؟ وما هو الأفضل في ذلك؟ مأجورين.","title":"ما الأفضل في التراويح ثلاثة عشر ركعة أم واحد وعشرين؟","answer":"الجواب: الأفضل إحدى عشرة أو ثلاثة عشرة، هذا هو الأفضل، هذا هو الثابت عن النبي ﷺ كان في الغالب يوتر بإحدى عشرة، يسلم من كل ثنتين، كما روت عائشة -رضي الله عنها- ذلك، وربما أوتر بثلاثة عشرة كما روت عائشة ذلك وابن عباس أيضًا، هذا هو الأفضل، وإن زاد وصلى إحدى وعشرين، أو ثلاثة وعشرين، أو أكثر فلا حرج؛ لقوله ﷺ: صلاة الليل مثنى مثنى، فإذا خشي الصبح صلى ركعة واحدة، توتر له ما قد صلى فلم يحدد حدًا، فلو صلى عشرين أو ثلاثين أو أربعين أو أكثر، ثم أوتر بواحدة فلا بأس، لكن الأفضل والأرفق بالمسلمين إحدى عشرة أو ثلاثة عشرة، هذا هو الذي فعله النبي ﷺ وهو الأرفق بالناس. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17710/ما-الافضل-في-التراويح-ثلاثة-عشر-ركعة-ام-واحد-وعشرين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_918/nour_91817.mp3","categories":["الوتر وقيام الليل"]},{"id":18609,"question":"هل دعاء القنوت في رمضان محدد بدعاء معين، أو تجوز الزيادة فيه، وما هو الأفضل في دعاء القنوت وخصوصًا في رمضان؟","title":"الدعاء المشروع في قنوت الوتر","answer":"الجواب: دعاء القنوت على ما روي عن النبي ﷺ من حديث الحسن: اللهم اهدنا فيمن هديت... ويزيد فيه من الدعوات الطيبة ما يناسب، إذا دعا فيه بعض الدعوات الطيبة لا بأس، كما كان النبي ﷺ علم الحسن: اللهم اهدني فيمن هديت... وكما كان عمر -رضي الله عنه وأرضاه- يقنت: «اللهم إنا نستعينك ونستهديك» وكما قنت النبي ﷺ في النوازل إذا دعا بدعوات مع: اللهم! اهدنا فيمن هديت كله حسن -إن شاء الله- كما جرى للسلف ، نعم.","link":"https://binbaz.org.sa/fatwas/17713/الدعاء-المشروع-في-قنوت-الوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_918/nour_91818.mp3","categories":["القنوت في الصلاة","الوتر وقيام الليل"]},{"id":18618,"question":"السائلة تقول: هل يجوز أن توتر المرأة بعد صلاة الليل وقد صلت الوتر بعد صلاة العشاء؟","title":"حكم صلاة الوتر مرتين في الليلة","answer":"الجواب: تصلي ما تيسر ولا يحتاج وتر، الوتر الأول يكفي، يقول النبي ﷺ: لا وتران في ليلة فإذا أوترت في أول الليل، ثم يسر الله لها القيام آخر الليل تصلي ما تيسر ركعتين، أربع ركعات، ست ركعات، أكثر، تسلم من كل ركعتين، مثنى مثنى، تسلم من كل ركعتين، والوتر الأول يكفي، والحمد لله.","link":"https://binbaz.org.sa/fatwas/17739/حكم-صلاة-الوتر-مرتين-في-الليلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_787/nour_78710.mp3","categories":["الوتر وقيام الليل"]},{"id":18620,"question":"السائلة تقول: هل يجوز أن توتر المرأة بعد صلاة الليل وقد صلت الوتر بعد صلاة العشاء؟","title":"حكم صلاة الوتر مرتين في الليلة","answer":"الجواب: تصلي ما تيسر ولا يحتاج وتر، الوتر الأول يكفي، يقول النبي ﷺ: لا وتران في ليلة فإذا أوترت في أول الليل، ثم يسر الله لها القيام آخر الليل تصلي ما تيسر ركعتين، أربع ركعات، ست ركعات، أكثر، تسلم من كل ركعتين، مثنى مثنى، تسلم من كل ركعتين، والوتر الأول يكفي، والحمد لله.","link":"https://binbaz.org.sa/fatwas/17739/حكم-صلاة-الوتر-مرتين-في-الليلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_787/nour_78710.mp3","categories":["الوتر وقيام الليل"]},{"id":18637,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من السودان، باعثتها إحدى الأخوات المستمعات رمزت إلى اسمها بالحروف (ت. أ) أختنا لها جمع من الأسئلة في أحدها تسأل وتقول: ما حكم الشرع في صلاة المرأة التراويح في المسجد؟جزاكم الله خيرًا.","title":"حكم صلاة المرأة التراويح في المسجد","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فإن الأصل في صلاة المرأة أن بيتها أفضل لها، وخير لها كما جاء به الحديث عن رسول الله -عليه الصلاة والسلام- لكن إذا رأت المصلحة في الصلاة في المسجد مع التستر والتحفظ؛ لأنه أنشط لها أو لأنها تستمع الفائدة من الدروس العلمية هكذا لا بأس به، ولا حرج في ذلك، والحمد لله، وهو أيضًا طيب لما فيه من الفائدة العظيمة والنشاط للعمل الصالح، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17749/حكم-صلاة-المراة-التراويح-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_735/nour_73501.mp3","categories":["قضايا المرأة","الوتر وقيام الليل"]},{"id":18886,"question":"رسالة من أحد الإخوة المستمعين ضمنها عددًا من الأسئلة في أحدها يقول: متى نؤدي صلاة الليل؟","title":"ما وقت صلاة الليل؟","answer":"الجواب: صلاة الليل ما بين صلاة العشاء إلى طلوع الفجر، كله صلاة الليل، أثناء صلاة العشاء إلى طلوع الفجر، لكن الأفضل في آخر الليل، أو في جوف الليل، وإن صليته قبل أن تنام فذلك خيرًا طيب وخير، إذا كنت تخشى، تخشى أن لا تقوم من آخر الليل؛ فالأفضل أن تصلي في أول الليل قبل أن تنام، وقد أوصى النبي ﷺ بعض الصحابة بالإيتار قبل النوم، وكل إنسان أعلم بنفسه، فإذا كان يستطيع القيام في آخر الليل فهذا أفضل، وإلا صلى في أول الليل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18025/ما-وقت-صلاة-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_736/nour_73617.mp3","categories":["الوتر وقيام الليل"]},{"id":18903,"question":"أختنا تسأل في سؤال آخر وتقول: هل تجوز صلاة النوافل ما بين صلاة العشاء والوتر وصلاة الفجر؛ لأنني أسمع من البعض يقولون: لا يجوز صلاة بعد الوتر حتى الفجر، والبعض يقولون: النوم يفصل بينها، وأحد الشيوخ في بلدنا قال: يمكن الصلاة قبل الفجر ما بين الأذانين الأول والثاني للفجر، والبعض يقول: لا يجوز، وإنني غالبًا ما أستيقظ قبل الفجر، وأريد أن أصلي، ولا أدري هل يجوز أم لا؟","title":"حكم صلاة شيء بعد صلاة الوتر","answer":"الجواب: نعم، نعم لا بأس بالصلاة بعد الوتر، إذا أوتر الإنسان في أول الليل، أو في وسط الليل، ثم يسر الله له القيام في آخر الليل؛ فإنه يشرع له أن يصلي ما قسم الله له، كركعتين أو أكثر من ذلك، ويكفيه الوتر الأول، لا حاجة إلى وتر ثاني، يقول النبي ﷺ: لا وتران في ليلة فإذا استيقظ المؤمن أو المؤمنة في آخر الليل وقد أوتر في أول الليل؛ فإنه يشرع له أن يصلي ما كتب الله له، ولا يعيد الوتر الأول، فإذا صلى ركعتين أو أربع أو أكثر، كل هذا طيب ولا بأس به، لكن يكون مثنى مثنى؛ لقول النبي ﷺ: صلاة الليل مثنى مثنى يعني: ثنتين ثنتين. وقد ثبت عنه ﷺ: أنه صلى ركعتين بعدما أوتر في آخر الليل؛ ليعلم الناس أن الصلاة بعد الوتر جائزة، وإنما الأفضل أن يكون الوتر آخر الشيء، كما قال ﷺ: اجعلوا آخر صلاتكم بالليل وترًا فالأفضل أن يكون الوتر هو آخر شيء، لكن إذا صار هناك سعة، وصلى بعد الوتر ركعتين أو أكثر؛ فلا حرج في ذلك، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18056/حكم-صلاة-شيء-بعد-صلاة-الوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_881/nour_88107.mp3","categories":["الوتر وقيام الليل"]},{"id":19115,"question":"رسالة من أحد الإخوة المستمعين يقول: صالح أحمد عالي الغامدي أخونا له جمع من الأسئلة في سؤاله الأول يقول: كم عدد ركعات صلاة الليل؟ وهل هي سرية أم جهرية؟ وهل تصح جماعة؟ وما هو وقتها؟ علمًا أنني أصليها بعد منتصف الليل، وأوقات قبل ذلك، وأصليها أربع ركعات، ثم أوتر بركعة أرجو التوضيح والتوجيه؟ جزاكم الله خيرًا.","title":"قيام الليل .. صفته ووقته وفضله","answer":"الجواب: صلاة الليل ليس لها عدد محصور، ولو صلى مائة ركعة وأوتر بواحدة أو أكثر من ذلك لا بأس بذلك، ليس لها عدد محصور، الله جل وعلا ندب إلى صلاة الليل وحث عليها  في كتابه العظيم قال جل وعلا: يَا أَيُّهَا الْمُزَّمِّلُ ۝ قُمِ اللَّيْلَ إِلَّا قَلِيلًا ۝ نِصْفَهُ أَوِ انْقُصْ مِنْهُ قَلِيلًا ۝ أَوْ زِدْ عَلَيْهِ وَرَتِّلِ الْقُرْآنَ تَرْتِيلًا [المزمل:1-4]، وقال  في وصف عباده المتقين: كَانُوا قَلِيلًا مِنَ اللَّيْلِ مَا يَهْجَعُونَ ۝ وَبِالأَسْحَارِ هُمْ يَسْتَغْفِرُونَ [الذاريات:17-18] ، وقال عن عباد الرحمن: وَالَّذِينَ يَبِيتُونَ لِرَبِّهِمْ سُجَّدًا وَقِيَامًا [الفرقان:64]. لكن الأفضل أن يوتر بمثل ما فعل النبي ﷺ إحدى عشرة أو ثلاث عشرة يسلم من كل ثنتين ويوتر بواحدة هذا هو الأفضل. وإذا أوتر بأكثر من ذلك بعشرين أو بأربعين أو بأكثر من ذلك وختم بواحدة فلا بأس بذلك، لقوله ﷺ في الحديث الصحيح: صلاة الليل مثنى مثنى، فإذا خشي أحدكم الصبح فليوتر بواحدة هذا يدل على أن صلاة الليل ليس لها حد؛ ولهذا قال: صلاة الليل مثنى مثنى ولم يحد بحد عشر أو أكثر أو أقل، قال: فإذا خشي أحدكم الصبح فليصل ركعة واحدة توتر له ما قد صلى هذا هو المشروع في هذا الباب. ثم وقتها من صلاة العشاء إلى طلوع الفجر، بعد صلاة العشاء وسنة الراتبة إلى طلوع الفجر كله محل تهجد بالليل. وأفضل ذلك آخر الليل الثلث الأخير هذا أفضل ذلك، وإن أوتر في أول الليل أو من وسطه فلا بأس، قد فعل النبي ﷺ هذا كله، قد أوتر من أول الليل عليه الصلاة والسلام، وأوتر من وسطه، وأوتر من آخره، كما قالت عائشة رضي الله عنها، ثم استقر وتره في السحر عليه الصلاة والسلام. ولا مانع أن يصليها جماعة في بعض الأحيان مع أهله، أو مع زواره من غير أن يتخذها عادة، لكن إذا صادف ذلك أنه زاره بعض إخوانه فصلوا جماعة لا بأس، وقد زار سلمان  أبا الدرداء في بعض الليالي وصليا جماعة في الليل، والنبي ﷺ زار محل أنس وصلى الضحى بهم جماعة عليه الصلاة والسلام. فالمقصود أنه إذا صلى النافلة جماعة في بعض الأحيان من غير اتخاذ ذلك عادة راتبة فلا بأس بذلك، ولا حرج في ذلك. والوتر أقله واحدة، ولا حد لأكثره، لكن الأفضل إحدى عشرة أو ثلاث عشرة هذا هو الأفضل، لفعل النبي ﷺ. المقدم: من أسئلته سماحة الشيخ: هل هي سرية أم جهرية؟ الشيخ: سرية وجهرية، يجوز أن يجهر ويجوز أن يسر، تقول عائشة رضي الله عنها: «كل ذلك قد فعله النبي ﷺ »، ربما جهر بالقراءة وربما أسر عليه الصلاة والسلام. فالمؤمن يفعل ما هو أصلح لقلبه، وما هو أخشع له، فإذا كانت قراءته جهرة أخشع لقلبه جهر، وإذا كانت السرية أخشع لقلبه وأرفق به فعل ذلك سرية. نعم. المقدم: جزاكم الله خيرًا؛ للبرنامج بعض الأسئلة حول قيام الليل شيخ عبد العزيز . الشيخ: نعم. المقدم: رأيكم في الصوارف عن قيام الليل وما أكثرها في هذا الزمان؟ الشيخ: المؤمن ينبغي له أن يبذل وسعه في قيام الليل، وإذا خشي أن لا يقوم من آخر الليل فليوتر أوله، كما قال النبي ﷺ في حديث جابر عند مسلم: من خاف أن لا يقوم من آخر الليل فليوتر أوله، ومن طمع أن يقوم آخر الليل فليوتر آخر الليل، فإن صلاة آخر الليل مشهودة وذلك أفضل خرجه الإمام مسلم في صحيحه عن جابر  ولأن الرسول ﷺ أوتر من أول الليل، وأوتر من وسطه، وأوتر من آخره، فالأمر واسع، وقد أوصى عليه الصلاة والسلام أبا الدرداء و أبا هريرة بالوتر أول الليل، والسر في ذلك والله أعلم أنهما كانا يدرسان الحديث، فربما شق عليهما القيام في آخر الليل، فأوصاهما بالإيتار قبل النوم. فالمؤمن يجاهد نفسه في هذا والحمد لله ليس بفريضة إنما هو سنة، سنة مؤكدة وكان يفعله النبي في السفر والحضر عليه الصلاة والسلام، كان في السفر والحضر يوتر ويتهجد بالليل عليه الصلاة والسلام. فمن فعل هذا فقد أحسن وله أجر عظيم ومن ترك ذلك فلا حرج عليه لكنه ترك أمرًا عظيمًا وسنة كبيرة، نعم. المقدم: صلاة الرجل بأهل بيته، كيف يكون التوجيه بخصوصها شيخ عبد العزيز ؟ الشيخ: إن شاء فعل وإن شاء ترك، النبي ﷺ كان يصلي وحده، ما كان يصلي بأهل بيته، كان يصلي وحده ﷺ فإذا جاء الوتر أيقظ عائشة لتوتر. فالمقصود أنه ﷺ كان فيما علمنا يصلي وحده عليه الصلاة والسلام في تهجده بالليل، فإذا تهجد الإنسان بالليل وحده فلا بأس، وإن صلى بأهله أو بجماعة زاروه فلا بأس. نعم. المقدم: شيخ عبد العزيز ، المرغبات كثيرة في ديننا حبذا لو تفضلتم بذكر بعض منها ولاسيما فيما يخص صلاة الليل؟ الشيخ: مثلما تقدم صلاة الليل عبادة عظيمة ومن سنة الأنبياء ومن دأب الصالحين، وهي مثلما في الحديث تكفر السيئات، وقربة إلى الله ، وهي من دأب الصالحين قبلنا. فينبغي للمؤمن أن يعتادها وأن يفعلها تأسيًا بالأنبياء والأخيار، كما قال سبحانه في عباد الرحمن: وَالَّذِينَ يَبِيتُونَ لِرَبِّهِمْ سُجَّدًا وَقِيَامًا [الفرقان:64] ، وقال في المتقين: كَانُوا قَلِيلًا مِنَ اللَّيْلِ مَا يَهْجَعُونَ ۝ وَبِالأَسْحَارِ هُمْ يَسْتَغْفِرُونَ [الذاريات:17-18] ، وقال سبحانه في أهل الصلاح والخير: تَتَجَافَى جُنُوبُهُمْ عَنِ الْمَضَاجِعِ يَدْعُونَ رَبَّهُمْ خَوْفًا وَطَمَعًا وَمِمَّا رَزَقْنَاهُمْ يُنفِقُونَ ۝ فَلا تَعْلَمُ نَفْسٌ مَا أُخْفِيَ لَهُمْ مِنْ قُرَّةِ أَعْيُنٍ جَزَاءً بِمَا كَانُوا يَعْمَلُونَ [السجدة:16-17]. والله جل وعلا في كتابه العظيم رغب فيها كثيرًا، وهكذا نبيه عليه الصلاة والسلام، فينبغي للمؤمن أن يستكثر من ذلك وأن يعتاد ذلك، وأن لا يخل بذلك لا سفرًا ولا حضرًا. نعم. المقدم: جزاكم الله خيرًا، أعود مرة أخرى للصوارف عن قيام الليل؟ الشيخ: من الصوارف السهر، يعني السهر في القيل والقال، والأحاديث التي لا فائدة فيها، أو في مشاغل الدنيا كالصناعة والجشع والحرص على المال، يعمل ليلًا ونهارًا لجمع المال والحرص على المال، فإذا سقط في الفراش سقط سقوط الميت، لا يستطيع أن ينهض للعبادة، وربما ترك صلاة الفجر ولا حول ولا قوة إلا بالله. فينبغي للمؤمن أن ينام مبكرًا ويجتهد في ذلك، حتى يستطيع أن يقوم من آخر الليل، أو يصلي من الليل ما تيسر قبل أن ينام، ثم ينام مبكرًا، حتى يستطيع القيام لصلاة الفجر ويصليها في الجماعة، فمن فعل ذلك فقد أحسن، ومن تساهل وقع فيما وقع فيه المنافقون، من فوات الخير والحصول على الشر والندامة، قال تعالى: إِنَّ الْمُنَافِقِينَ يُخَادِعُونَ اللَّهَ وَهُوَ خَادِعُهُمْ وَإِذَا قَامُوا إِلَى الصَّلاةِ قَامُوا كُسَالَى يُرَاءُونَ النَّاسَ وَلا يَذْكُرُونَ اللَّهَ إِلَّا قَلِيلًا [النساء:142]، فالمؤمن ينبغي له البعد عن التشبه بهم في جميع الأحوال. نعم. المقدم: جزاكم الله خيرًا. أرجو أن نعود إلى البحث والمناقشة حول هذه القضية في حلقات قادمة شيخ عبد العزيز . الشيخ: نرجو ذلك. نعم. المقدم: إن شاء الله.","link":"https://binbaz.org.sa/fatwas/18313/قيام-الليل-صفته-ووقته-وفضله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_931/nour_93108.mp3","categories":["الوتر وقيام الليل"]},{"id":19270,"question":"هل يجوز الوتر بواحدة أم لا بد من الشفع؟","title":"حكم الوتر بواحدة","answer":"الجواب: تكفي واحدة، الوتر بواحدة لا بأس، في أول الليل أو في وسطه أو في آخره، ركعة واحدة، والأفضل أن يقرأ فيها الفاتحة وقل هو الله أحد، وإن قرأ الفاتحة وحدها، أو معها غير قل هو الله أحد فلا بأس، لكن الأفضل أن يكون معها قل هو الله أحد، وإن زاد على واحدة صلى ثلاثًا أو خمسًا أو أكثر فهو أفضل. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/18461/حكم-الوتر-بواحدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_892/nour_89207.mp3","categories":["الوتر وقيام الليل"]},{"id":19298,"question":"المستمعة (ف. ن. ح. م. مطيري ) بعثت تسأل وتقول: هل يجوز للمرأة أن تصلي في المسجد مع الرجال صلاة التراويح؟","title":"حكم صلاة المرأة التراويح في مسجد الرجال","answer":"الجواب: المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18480/حكم-صلاة-المراة-التراويح-في-مسجد-الرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_739/nour_73906.mp3","categories":["قضايا المرأة","الوتر وقيام الليل"]},{"id":19308,"question":"تقول أختنا هل يجوز أن أؤخر صلاة التراويح إلى آخر الليل؟","title":"تأخير صلاة التراويح إلى آخر الليل","answer":"الجواب: نعم، لا بأس، إذا تيسر هذا فهو أفضل آخر الليل، إذا تيسر هذا فآخر الليل أفضل، ولكن المسلمين يصلونها في أول الليل؛ لأنه أنشط لهم، وأقرب إلى القيام بها؛ لأن كثير من الناس لو نام ما قام في آخر الليل، فالمقصود إنه إذا تيسر أن تؤدى في آخر الليل فذلك أفضل. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18500/تاخير-صلاة-التراويح-الى-اخر-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_739/nour_73908.mp3","categories":["الوتر وقيام الليل"]},{"id":19322,"question":"تقول: أحفظ معنى حديث عن رسول الله ﷺ: اجعلوا آخر صلاتكم بالليل وترًا، أنا أنوي صلاة القيام ولكن أخشى أن يغلبني النعاس؛ لذلك أصلي الشفع والوتر قبل أن أنام فهل يجوز لي أن أصلي قيام الليل بعد الشفع والوتر؟ أم أؤجل الشفع والوتر مع صلاة القيام؟ جزاكم الله خيرًا.","title":"حكم النافلة آخر الليل بعد الوتر في أوله","answer":"الجواب: إذا خفت ألا تقومي في آخر الليل؛ فصلي في أول الليل، وقد أوصى النبي ﷺ جماعة من الصحابة أن يصلوا في أول الليل قبل النوم أن يوتروا؛ والسبب في ذلك أنهم يخشون أن لا يقوموا آخر الليل. فالإنسان إذا كان يخشى ألا يقوم آخر الليل فالسنة له أن يوتر في أول الليل، وإذا قام آخر الليل يسر الله له القيام صلى ما يسر الله له: ثنتين أو أربع أو أكثر يسلم من كل ثنتين، ولا يحتاج إلى وتر، الوتر الأول كاف؛ لقوله ﷺ: لا وتران في ليلة، فإذا يسر الله له القيام في وسط الليل أو في آخره؛ صلى ما تيسر ثنتين ثنتين وكفاه الوتر الأول والحمد لله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18519/حكم-النافلة-اخر-الليل-بعد-الوتر-في-اوله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_739/nour_73916.mp3","categories":["الوتر وقيام الليل"]},{"id":19429,"question":"المستمع (د. م. ع) من اليمن الجنوبي بعث يسأل ويقول: نحن فئة من المسلمين نصلي في شهر رمضان صلاة التراويح إحدى عشرة ركعة، وقد أنكر علينا بعض المسلمين ويقولون: إنها إحدى وعشرون ركعة كما فعل عمر  وضحوا لنا جزاكم الله خيرًا.","title":"ما الصحيح في عدد ركعات التراويح؟","answer":"الجواب: التراويح في رمضان بابها واسع، وقد صلاها النبي ﷺ إحدى عشرة كما روت عائشة رضي الله عنها ذلك، وصلى ثلاثة عشرة، وصلى أقل من ذلك عليه الصلاة والسلام، وصلاها عمر والمسلمون إحدى عشرة، وصلوها ثلاثًا وعشرين، كل هذا واقع، والأمر في هذا واسع، والحمد لله، فإن صلوها ثلاثًا وعشرين كما فعل عمر والصحابة فلا بأس، وإن صلوها إحدى عشرة كما فعله النبي ﷺ أو ثلاثة عشرة فهذا أفضل، وقد فعله عمر والصحابة في بعض الأوقات فعلوا هذا وهذا، فالأمر واسع في هذا. وإن صلوا أكثر من ثلاث وعشرين كأربعين بالوتر أو أكثر أو أقل فلا بأس بذلك، لكن الأفضل فعله ﷺ وهو إحدى عشرة أو ثلاثة عشرة يسلم من كل ثنتين ويوتر بواحدة، سواءً كان في أول الليل، أو في وسط الليل، أو في آخر الليل، كله واسع والحمد لله، نعم. المقدم: الحمد لله جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18695/ما-الصحيح-في-عدد-ركعات-التراويح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_944/nour_94405.mp3","categories":["الوتر وقيام الليل"]},{"id":19584,"question":"سماحة الشيخ، السائل (ع. ع) يقول : كنت في سفر وصليت المغرب والعشاء جمع تقديم، ثم صليت الوتر بعد ذلك، ولم يكن وقت صلاة العشاء قد حان بين المغرب والعشاء، فهل صلاتي الوتر في هذا الوقت صحيحة؟","title":"حكم الوتر عقب الجمع بين المغرب والعشاء","answer":"الجواب: نعم إذا صلى المسافر أو المريض المغرب والعشاء جمع تقديم دخل وقت الوتر بعد صلاة العشاء ولو كان وقت المغرب باقيًا، ما دام صلى المغرب والعشاء جمع تقديم في السفر أو في المرض؛ فإنه يوتر بعد ذلك، ولو كان وقت المغرب باقيًا. نعم.","link":"https://binbaz.org.sa/fatwas/18850/حكم-الوتر-عقب-الجمع-بين-المغرب-والعشاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_947/nour_94728.mp3","categories":["صلاة المسافر","الوتر وقيام الليل"]},{"id":19585,"question":"الوارد في عدد ركعات التراويح في رمضان يقول السائل؟","title":"الوارد في عدد ركعات التراويح","answer":"الجواب: كان النبي ﷺ لا يزيد في رمضان ولا في غيره على إحدى عشرة ركعة، وربما صلى ثلاث عشرة كما قالت عائشة رضي الله عنها، أقصى ما ورد ثلاث عشرة، هذا هو الثابت وإن صلى أكثر فلا بأس لقوله ﷺ: صلاة الليل مثنى مثنى، ولم يحدد، لكن فعله ﷺ كان يصلي إحدى عشرة، وربما صلى ثلاث عشرة، يسلم من كل ثنتين، ويوتر بواحدة في رمضان وفي غيره، من صلى عشرين وأوتر بثلاث، أو صلى ثلاثين أو أربعين، وأوتر بواحدة أو بثلاث كله لا بأس به لعموم قوله ﷺ: صلاة الليل مثنى مثنى، فإذا خشي الصبح صلى ركعة واحدة توتر له ما قد صلى. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/18848/الوارد-في-عدد-ركعات-التراويح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_947/nour_94727.mp3","categories":["الوتر وقيام الليل"]},{"id":19586,"question":"يقول هذا السائل: حسن سعيد من الدمام الظهران: أنا أشتغل في مجمع تجاري مكون من محطة بنزين وبقالة وكبينة، ويشتغل في الكبينة يقول: بجانبنا مسجد صغير، ولا يصلون صلاة التراويح فيه، وبعد صلاة العشاء يذهبون إلى أعمالهم؛ ماذا أفعل هل أصلي بعد صلاة العشاء التراويح وحدي، وهل من إرشاد؟","title":"حكم صلاة التراويح منفردًا","answer":"الجواب: أنت مخير إن صليت وحدك فأنت مأجور، أو صليت في بيتك كله طيب، ما دام ما في جماعة، وإن ذهبت إلى مسجد آخر فلا بأس؛ لأنها نافلة التراويح نافلة ما هي بفريضة إن صليتها في المسجد، أو في بيتك، أو في مسجد آخر، كله واسع والحمد لله. نعم. المقدم: حفظكم الله يا فضيلة الشيخ.","link":"https://binbaz.org.sa/fatwas/18846/حكم-صلاة-التراويح-منفردا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_947/nour_94726.mp3","categories":["الوتر وقيام الليل"]},{"id":19587,"question":"تقول السائلة يا سماحة الشيخ: ما هي بداية صلاة آخر الليل، جزاكم الله خيرًا؟","title":"مشروعية قيام الليل وأفضل أوقاته","answer":"الجواب: الصلاة في الليل كلها مشروعة، من أوله إلى آخره، وأفضلها الثلث الأخير، وأفضلها السدس الرابع والخامس، صلاة داود كان ينام نصف الليل ويقوم ثلثه، يقول ﷺ: أفضل الصلاة صلاة داود كان ينام نصف الليل ويقوم ثلثه وينام سدسه فإذا صلى الإنسان في السدس الرابع والخامس هذا أفضل الوقت، والسدس السادس من بقية ثلث الليل كله طيب، وقت التنزل الإلهي، يقول النبي ﷺ: ينزل ربنا إلى سماء الدنيا كل ليلة حين يبقى ثلث الليل الآخر فيقول: من يدعوني فأستجيب له؟ من يسألني فأعطيه؟ من يستغفرني فأغفر له؟ فالنصف الأخير كله خير، النصف الأخير كله محل إجابة دعاء وفضلاً عظيم. نعم. المقدم: أحسن الله إليكم وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/18847/مشروعية-قيام-الليل-وافضل-اوقاته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_949/nour_94906.mp3","categories":["الوتر وقيام الليل"]},{"id":19601,"question":"يقول: هل أصلي الوتر بعد الأذان الأول يا سماحة الشيخ؟","title":"هل يجوز صلاة الوتر بعد الأذان الأول؟","answer":"الجواب: الوتر في الليل كله، من بعد صلاة العشاء إلى طلوع الفجر، كل الليل محل وتر، بعد الفراغ من صلاة العشاء وسنتها الراتبة إلى طلوع الفجر كله محل وتر، وإذا تيسر في آخر الليل فهو أفضل، وإلا فأوتر قبل النوم، إذا كنت تخشى أن لا تقوم فالأفضل لك أن توتر قبل النوم. نعم. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/18874/هل-يجوز-صلاة-الوتر-بعد-الاذان-الاول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_948/nour_94810.mp3","categories":["الوتر وقيام الليل"]},{"id":19659,"question":"سماحة الشيخ أبو عمار له هذا السؤال يقول: بأنه يصلي من الليل إحدى عشرة ركعة بعد العشاء، يدخل فيها ركعتين بعد العشاء، وركعتين سنة الوضوء قبل صلاة الليل، وثلاث ركعات وترًا، فهل صلاتي صحيحة أفيدوني مأجورين؟","title":"صفة قيام الليل","answer":"الجواب: الوتر مشروع بما تيسر ولو واحدة، لو أوتر بواحدة في الليل بعد صلاة العشاء وسنتها كفى، فإذا أوتر بثلاث أو بخمس أو بسبع أو بتسع أو بإحدى عشرة أو ثلاثة عشرة كله طيب. والأفضل إحدى عشرة إذا تيسر أو ثلاثة عشرة يسلم من كل ثنتين، وإن أوتر بثلاث سردًا أو سلم من كل ثنتين أو أوتر بخمس سردًا، السنة أن يسرد الخمس لا يجلس فيها إلا في الخامسة وإلا يسلم من كل ثنتين هذا هو الأفضل يسلم من كل ثنتين، أو أوتر بسبع فلا بأس سردها أو جلس في السادسة في التشهد الأول ثم قام أو أوتر بتسع وجلس في الثامنة في التشهد الأول ثم قام كله لا بأس به. لكن الأفضل أن يسلم من كل ثنتين؛ لقوله ﷺ: صلاة الليل مثنى مثنى، فإذا خشي أحدكم الصبح صلى ركعة واحدة توتر له ما قد صلى. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/18948/صفة-قيام-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_950/nour_95013.mp3","categories":["الوتر وقيام الليل"]}]
